  "description": "An advanced AI system for detecting scam messages and automatically engaging scammers to extract actionable intelligence like UPI IDs, bank accounts, and malicious links.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ExtractedInfo {
  upiIds: string[];
  bankDetails: string[];
  phoneNumbers: string[];
  links: string[];
}

export interface ScamAnalysis {
  isScam: boolean;
  confidence: number;
  scamType: string;
  threatLevel: 'Low' | 'Medium' | 'High' | 'Critical';
  summary: string;
  extractedInfo: ExtractedInfo;
  suggestedBaitResponse: string;
}

export interface ChatMessage {
  role: 'user' | 'bot' | 'scammer';
  content: string;
  timestamp: number;
}

export interface IntelligenceLog extends ScamAnalysis {
  id: string;
  originalMessage: string;
  timestamp: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ScamAnalysis } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const SCAM_ANALYSIS_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    isScam: { type: Type.BOOLEAN, description: "Whether the message is a scam." },
    confidence: { type: Type.NUMBER, description: "Confidence score from 0 to 1." },
    scamType: { type: Type.STRING, description: "Type of scam (e.g., Phishing, Lottery, Job Scam)." },
    threatLevel: { type: Type.STRING, enum: ["Low", "Medium", "High", "Critical"] },
    summary: { type: Type.STRING, description: "Short summary of the threat." },
    extractedInfo: {
      type: Type.OBJECT,
      properties: {
        upiIds: { type: Type.ARRAY, items: { type: Type.STRING } },
        bankDetails: { type: Type.ARRAY, items: { type: Type.STRING } },
        phoneNumbers: { type: Type.ARRAY, items: { type: Type.STRING } },
        links: { type: Type.ARRAY, items: { type: Type.STRING } }
      },
      required: ["upiIds", "bankDetails", "phoneNumbers", "links"]
    },
    suggestedBaitResponse: { type: Type.STRING, description: "A human-like response to bait the scammer into revealing more details." }
  },
  required: ["isScam", "confidence", "scamType", "threatLevel", "summary", "extractedInfo", "suggestedBaitResponse"]
};

export const analyzeMessage = async (message: string): Promise<ScamAnalysis> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Analyze the following message for scam patterns. If it's a scam, extract all identifiable intelligence (UPI IDs, bank details, phone numbers, links). Also, provide a "bait" response that sounds like a naive, interested target who wants to proceed but needs more payment details to "verify" or "pay".

    Message: "${message}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: SCAM_ANALYSIS_SCHEMA,
      systemInstruction: "You are a professional Cyber Security Intelligence Analyst and Scam Baiter. Your goal is to identify fraud and trick scammers into revealing their operational details (accounts, numbers, links). Always provide structured, high-accuracy intelligence."
    },
  });

  return JSON.parse(response.text);
};

export const generateBaitResponse = async (history: { role: string, content: string }[]): Promise<string> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: history.map(h => ({
      parts: [{ text: `${h.role === 'scammer' ? 'Scammer' : 'You (Baiter)'}: ${h.content}` }]
    })),
    config: {
      systemInstruction: "You are baiting a scammer. Be extremely naive and slightly confused but very eager to send money. Ask things like 'I tried the link but it didnt work, do you have a UPI id?', or 'My bank is asking for your IFSC code to add you as a beneficiary'. Keep them engaged to extract their details. Return only the text of your next reply."
    }
  });

  return response.text.trim();
};

import React, { useState } from 'react';
import { analyzeMessage } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete }) => {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const handleAnalyze = async () => {
    if (!input.trim()) return;
    setLoading(true);
    try {
      const result = await analyzeMessage(input);
      onAnalysisComplete(input, result);
      setInput('');
    } catch (error) {
      console.error("Analysis failed", error);
      alert("Failed to analyze message. Please check console.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 shadow-xl">
      <h2 className="text-xl font-bold mb-4 text-blue-400 flex items-center">
        <svg className="w-6 h-6 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
        </svg>
        New Intelligence Intake
      </h2>
      <textarea
        className="w-full h-32 bg-slate-900 text-slate-200 p-4 rounded-lg border border-slate-700 focus:ring-2 focus:ring-blue-500 outline-none transition-all placeholder-slate-500"
        placeholder="Paste suspected scam message here (e.g. WhatsApp, SMS, Email)..."
        value={input}
        onChange={(e) => setInput(e.target.value)}
      />
      <button
        onClick={handleAnalyze}
        disabled={loading || !input.trim()}
        className={`mt-4 w-full py-3 rounded-lg font-bold flex items-center justify-center transition-colors ${
          loading 
          ? 'bg-slate-700 text-slate-400 cursor-not-allowed' 
          : 'bg-blue-600 hover:bg-blue-700 text-white shadow-lg shadow-blue-900/20'
        }`}
      >
        {loading ? (
          <>
            <svg className="animate-spin h-5 w-5 mr-3 border-2 border-white/30 border-t-white rounded-full" viewBox="0 0 24 24"></svg>
            Analyzing Patterns...
          </>
        ) : 'Scan for Fraud Patterns'}
      </button>
    </div>
  );
};

export default ScamAnalyzer;

import React from 'react';
import { IntelligenceLog } from '../types';

interface Props {
  logs: IntelligenceLog[];
}

const IntelligenceDashboard: React.FC<Props> = ({ logs }) => {
  const totalScams = logs.filter(l => l.isScam).length;

  const allUpi = logs.flatMap(l => l.extractedInfo.upiIds);
  const allLinks = logs.flatMap(l => l.extractedInfo.links);
  const allPhones = logs.flatMap(l => l.extractedInfo.phoneNumbers);

  const uniqueUpi = Array.from(new Set(allUpi));
  const uniqueLinks = Array.from(new Set(allLinks));
  const uniquePhones = Array.from(new Set(allPhones));

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatCard title="Total Analysed" value={logs.length} color="text-slate-400" />
        <StatCard title="Confirmed Scams" value={totalScams} color="text-red-500" />
        <StatCard title="Unique UPI IDs" value={uniqueUpi.length} color="text-amber-500" />
        <StatCard title="Malicious Links" value={uniqueLinks.length} color="text-purple-500" />
      </div>

      <div className="bg-slate-800 rounded-xl border border-slate-700 overflow-hidden">
        <div className="px-6 py-4 bg-slate-900/50 border-b border-slate-700 flex justify-between items-center">
          <h3 className="font-bold text-slate-200">Intelligence Activity Log</h3>
          <span className="text-xs text-slate-500 uppercase tracking-widest">Real-time Feed</span>
        </div>
        <div className="divide-y divide-slate-700">
          {logs.length === 0 ? (
            <div className="p-10 text-center text-slate-500 italic">No intelligence captured yet.</div>
          ) : (
            logs.map((log) => (
              <div key={log.id} className="p-4 hover:bg-slate-700/30 transition-colors">
                <div className="flex justify-between items-start mb-2">
                  <div className="flex items-center space-x-2">
                    <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                      log.threatLevel === 'Critical' ? 'bg-red-500/20 text-red-500' :
                      log.threatLevel === 'High' ? 'bg-orange-500/20 text-orange-500' :
                      'bg-blue-500/20 text-blue-500'
                    }`}>
                      {log.threatLevel} Threat
                    </span>
                    <span className="text-sm font-medium text-slate-300">{log.scamType}</span>
                  </div>
                  <span className="text-xs text-slate-500">{new Date(log.timestamp).toLocaleTimeString()}</span>
                </div>
                <p className="text-sm text-slate-400 line-clamp-2 mb-3">"{log.originalMessage}"</p>

                <div className="flex flex-wrap gap-2">
                  {log.extractedInfo.upiIds.map((upi, idx) => (
                    <span key={idx} className="bg-amber-500/10 text-amber-500 text-[10px] px-2 py-1 rounded border border-amber-500/20">UPI: {upi}</span>
                  ))}
                  {log.extractedInfo.links.map((link, idx) => (
                    <span key={idx} className="bg-purple-500/10 text-purple-500 text-[10px] px-2 py-1 rounded border border-purple-500/20">Link: {link}</span>
                  ))}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ title, value, color }: { title: string, value: number, color: string }) => (
  <div className="bg-slate-800 p-4 rounded-xl border border-slate-700 shadow-md">
    <div className="text-xs text-slate-500 uppercase font-bold tracking-wider mb-1">{title}</div>
    <div className={`text-2xl font-black ${color}`}>{value}</div>
  </div>
);

export default IntelligenceDashboard;

import React, { useState } from 'react';
import { analyzeMessage } from '../services/geminiService';

