export default ApiExplorer;

import React, { useState, useEffect, useRef } from 'react';
import { generateBaitResponse, analyzeMessage } from '../services/geminiService';
import { ChatMessage, ExtractedInfo } from '../types';

interface Props {
  initialScam: string;
  onIntelExtracted: (info: ExtractedInfo) => void;
}

const BaitSession: React.FC<Props> = ({ initialScam, onIntelExtracted }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'scammer', content: initialScam, timestamp: Date.now() }
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const runBaitCycle = async () => {
    setIsTyping(true);
    try {
      // 1. Get automated response from AI (acting as victim)
      const history = messages.map(m => ({ role: m.role, content: m.content }));
      const baitText = await generateBaitResponse(history);

      setMessages(prev => [...prev, { role: 'bot', content: baitText, timestamp: Date.now() }]);

      // 2. Simulate Scammer response after some time (Mocking the loop)
      // In a real system, this would wait for actual incoming webhook data from a messaging API.
    } catch (e) {
      console.error(e);
    } finally {
      setIsTyping(false);
    }
  };

  // Automated trigger on start
  useEffect(() => {
    if (messages.length === 1 && messages[0].role === 'scammer') {
      setTimeout(runBaitCycle, 1500);
    }
  }, []);

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim()) return;
    const newMsg: ChatMessage = { role: 'scammer', content: reply, timestamp: Date.now() };
    setMessages(prev => [...prev, newMsg]);

    // Analyze new reply for intel
    const analysis = await analyzeMessage(reply);
    if (analysis.isScam) {
      onIntelExtracted(analysis.extractedInfo);
    }

    // Trigger AI response
    setTimeout(runBaitCycle, 1000);
  };

  return (
    <div className="bg-slate-800 rounded-xl border border-slate-700 flex flex-col h-[500px] overflow-hidden">
      <div className="p-4 bg-slate-900 border-b border-slate-700 flex items-center justify-between">
        <div className="flex items-center space-x-2">
          <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>
          <span className="font-bold text-slate-200">Active Honeypot Session</span>
        </div>
        <span className="text-[10px] text-slate-500">SESSION_ID: BT-4491-X</span>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-900/30">
        {messages.map((m, idx) => (
          <div key={idx} className={`flex ${m.role === 'scammer' ? 'justify-start' : 'justify-end'}`}>
            <div className={`max-w-[80%] rounded-2xl px-4 py-2 text-sm ${
              m.role === 'scammer' 
              ? 'bg-slate-700 text-slate-200 rounded-tl-none' 
              : 'bg-blue-600 text-white rounded-tr-none'
            }`}>
              <div className="text-[10px] opacity-50 mb-1">{m.role === 'scammer' ? 'TARGET' : 'AI BAITER'}</div>
              {m.content}
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-end">
            <div className="bg-blue-600/30 text-white rounded-2xl px-4 py-2 text-xs flex items-center space-x-1">
              <span className="w-1 h-1 bg-white rounded-full animate-bounce"></span>
              <span className="w-1 h-1 bg-white rounded-full animate-bounce [animation-delay:0.2s]"></span>
              <span className="w-1 h-1 bg-white rounded-full animate-bounce [animation-delay:0.4s]"></span>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-slate-900 border-t border-slate-700">
        <form onSubmit={(e) => {
          e.preventDefault();
          const target = e.target as any;
          handleManualScammerReply(target.reply.value);
          target.reply.value = '';
        }} className="flex space-x-2">
          <input 
            name="reply"
            type="text" 
            placeholder="Simulate scammer's next reply..."
            className="flex-1 bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 text-sm text-slate-200 outline-none focus:ring-1 focus:ring-blue-500"
          />
          <button type="submit" className="bg-slate-700 hover:bg-slate-600 text-white px-4 py-2 rounded-lg text-xs font-bold transition-colors">
            Send
          </button>
        </form>
        <p className="text-[10px] text-slate-500 mt-2 text-center">In production, this input is replaced by a real-time messaging webhook.</p>
      </div>
    </div>
  );
};

export default BaitSession;

import React, { useState, useEffect } from 'react';
import ScamAnalyzer from './components/ScamAnalyzer';
import IntelligenceDashboard from './components/IntelligenceDashboard';
import ApiExplorer from './components/ApiExplorer';
import BaitSession from './components/BaitSession';
import { ScamAnalysis, IntelligenceLog, ExtractedInfo } from './types';

enum Tab {
  Dashboard = 'DASHBOARD',
  Intake = 'INTAKE',
  Baiting = 'BAITING',
  ApiDocs = 'API_DOCS'
}

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>(Tab.Dashboard);
  const [logs, setLogs] = useState<IntelligenceLog[]>([]);
  const [lastAnalyzedScam, setLastAnalyzedScam] = useState<{message: string, analysis: ScamAnalysis} | null>(null);

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis) => {
    const newLog: IntelligenceLog = {
      ...analysis,
      id: Math.random().toString(36).substr(2, 9),
      originalMessage: message,
      timestamp: Date.now()
    };
    setLogs(prev => [newLog, ...prev]);
    setLastAnalyzedScam({ message, analysis });

    if (analysis.isScam) {
      setActiveTab(Tab.Baiting);
    } else {
      setActiveTab(Tab.Dashboard);
    }
  };

  const updateIntel = (info: ExtractedInfo) => {
    // In a real app, this would merge into the logs
    console.log("New Intel Extracted:", info);
  };

  return (
    <div className="min-h-screen bg-slate-900 text-slate-200 flex flex-col">
      {/* Header */}
      <header className="bg-slate-800 border-b border-slate-700 px-6 py-4 flex items-center justify-between sticky top-0 z-50">
        <div className="flex items-center space-x-3">
          <div className="bg-blue-600 p-2 rounded-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
            </svg>
          </div>
          <div>
            <h1 className="text-xl font-black tracking-tighter text-white">SCAMBAITER <span className="text-blue-500">AI</span></h1>
            <p className="text-[10px] text-slate-400 font-mono">INTEL OPS / FRAUD PREVENTION</p>
          </div>
        </div>

        <nav className="flex space-x-1 bg-slate-900/50 p-1 rounded-xl border border-slate-700">
          <TabButton active={activeTab === Tab.Dashboard} onClick={() => setActiveTab(Tab.Dashboard)} label="Dashboard" />
          <TabButton active={activeTab === Tab.Intake} onClick={() => setActiveTab(Tab.Intake)} label="Intake" />
          <TabButton active={activeTab === Tab.Baiting} onClick={() => setActiveTab(Tab.Baiting)} label="Honeypot" />
          <TabButton active={activeTab === Tab.ApiDocs} onClick={() => setActiveTab(Tab.ApiDocs)} label="API" />
        </nav>
      </header>

      {/* Main Content */}
      <main className="flex-1 container mx-auto px-6 py-8 max-w-6xl">
        <div className="grid grid-cols-1 gap-8">
          {activeTab === Tab.Dashboard && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
              <IntelligenceDashboard logs={logs} />
            </div>
          )}

          {activeTab === Tab.Intake && (
            <div className="max-w-2xl mx-auto w-full animate-in fade-in zoom-in-95 duration-500">
              <ScamAnalyzer onAnalysisComplete={handleAnalysisComplete} />
              <div className="mt-8 p-6 bg-slate-800/50 border border-slate-700 rounded-xl">
                <h4 className="text-sm font-bold text-slate-400 mb-3 uppercase tracking-wider">How it works</h4>
                <ul className="text-sm text-slate-500 space-y-2 list-disc list-inside">
                  <li>Paste a suspected message to analyze scam linguistics.</li>
                  <li>AI extracts technical debt (UPI, Banks, Links, Phones).</li>
                  <li>Confirmed scams trigger an automated Baiting Session.</li>
                  <li>Intelligence is aggregated for institutional reporting.</li>
                </ul>
              </div>
            </div>
          )}

          {activeTab === Tab.Baiting && (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in fade-in slide-in-from-right-4 duration-500">
              <div className="lg:col-span-2">
                {lastAnalyzedScam ? (
                  <BaitSession 
                    initialScam={lastAnalyzedScam.message} 
                    onIntelExtracted={updateIntel} 
                  />
                ) : (
                  <div className="bg-slate-800 h-full rounded-xl flex items-center justify-center border border-slate-700 text-slate-500 flex-col p-8 text-center">
                    <svg className="w-16 h-16 mb-4 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
                    </svg>
                    <p>No active session. Please input a scam message in the <strong>Intake</strong> tab to start baiting.</p>
                  </div>
