                  {lastAnalyzedScam ? (
                    <div className="space-y-4">
                      <div className="p-3 bg-slate-900 rounded border border-slate-700 text-xs">
                        <span className="block text-slate-500 mb-1">Scam Profile:</span>
                        <span className="text-slate-200 font-medium">{lastAnalyzedScam.analysis.scamType}</span>
                      </div>
                      <div className="p-3 bg-slate-900 rounded border border-slate-700 text-xs">
                        <span className="block text-slate-500 mb-1">Threat Level:</span>
                        <span className="text-red-500 font-black">{lastAnalyzedScam.analysis.threatLevel}</span>
                      </div>
                    </div>
                  ) : <p className="text-xs text-slate-600">Waiting for target...</p>}
                </div>

                <div className="bg-amber-500/10 p-6 rounded-xl border border-amber-500/20">
                  <h3 className="text-amber-500 font-bold mb-2 uppercase text-xs tracking-widest">Baiting Strategy</h3>
                  <p className="text-xs text-amber-500/70 leading-relaxed">
                    System is currently using the <strong>"Naive Winner"</strong> persona. Eagerly asking for payment details to "reserve the prize" or "pay processing fees" while providing excuses for bank errors.
                  </p>
                </div>
              </div>
            </div>
          )}

          {activeTab === Tab.ApiDocs && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
              <ApiExplorer />
            </div>
          )}
        </div>
