import React, { useState, useEffect, useRef } from 'react';
import { analyzeMessage } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete }) => {
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'en-IN'; // Optimized for Indian English accents

      recognition.onresult = (event: any) => {
        let interimTranscript = '';
        let finalTranscript = '';

        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            finalTranscript += event.results[i][0].transcript;
          } else {
            interimTranscript += event.results[i][0].transcript;
          }
        }
        setInput(prev => prev + finalTranscript);
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognition.onerror = (event: any) => {
        console.error("Speech recognition error", event.error);
        setIsListening(false);
      };

      recognitionRef.current = recognition;
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) {
      alert("Speech recognition is not supported in this browser.");
      return;
    }

    if (isListening) {
      recognitionRef.current.stop();
    } else {
      setIsListening(true);
      recognitionRef.current.start();
    }
  };

  const handleAnalyze = async () => {
    if (!input.trim()) return;
    if (isListening) recognitionRef.current.stop();

    setLoading(true);
    try {
      const result = await analyzeMessage(input);
      onAnalysisComplete(input, result);
      setInput('');
    } catch (error) {
      console.error("Analysis failed", error);
      alert("Failed to analyze message. Please check console.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 shadow-xl">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold text-blue-400 flex items-center">
          <svg className="w-6 h-6 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          New Intelligence Intake
        </h2>
        <button
          onClick={toggleListening}
          className={`p-2 rounded-full transition-all ${
            isListening 
            ? 'bg-red-600 text-white animate-pulse shadow-lg shadow-red-900/40' 
            : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
          }`}
          title={isListening ? "Stop Listening" : "Input via Voice"}
        >
          {isListening ? (
            <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8 7a1 1 0 00-1 1v4a1 1 0 001 1h4a1 1 0 001-1V8a1 1 0 00-1-1H8z" clipRule="evenodd" />
            </svg>
          ) : (
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" />
            </svg>
          )}
        </button>
      </div>

      <div className="relative">
        <textarea
          className="w-full h-40 bg-slate-900 text-slate-200 p-4 rounded-lg border border-slate-700 focus:ring-2 focus:ring-blue-500 outline-none transition-all placeholder-slate-500 resize-none"
          placeholder={isListening ? "Listening... Speak now." : "Paste suspected scam message or click the mic to record a transcript..."}
          value={input}
          onChange={(e) => setInput(e.target.value)}
        />
        {isListening && (
          <div className="absolute top-3 right-3 flex space-x-1">
            <span className="w-1.5 h-1.5 bg-red-500 rounded-full animate-bounce"></span>
            <span className="w-1.5 h-1.5 bg-red-500 rounded-full animate-bounce [animation-delay:0.2s]"></span>
            <span className="w-1.5 h-1.5 bg-red-500 rounded-full animate-bounce [animation-delay:0.4s]"></span>
          </div>
        )}
      </div>

      <button
        onClick={handleAnalyze}
        disabled={loading || !input.trim()}
        className={`mt-4 w-full py-3 rounded-lg font-bold flex items-center justify-center transition-colors ${
          loading 
          ? 'bg-slate-700 text-slate-400 cursor-not-allowed' 
          : 'bg-blue-600 hover:bg-blue-700 text-white shadow-lg shadow-blue-900/20'
        }`}
      >
        {loading ? (
          <>
            <svg className="animate-spin h-5 w-5 mr-3 border-2 border-white/30 border-t-white rounded-full" viewBox="0 0 24 24"></svg>
            Analyzing Patterns...
          </>
        ) : 'Scan for Fraud Patterns'}
      </button>
    </div>
  );
};

export default ScamAnalyzer;

