// Helper to decode base64
export function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Helper to decode PCM audio data
export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { generateBaitResponse, analyzeMessage, generateAudioFromText, decodeBase64, decodeAudioData } from '../services/geminiService';
import { ChatMessage, ExtractedInfo } from '../types';

interface Props {
  initialScam: string;
  onIntelExtracted: (info: ExtractedInfo) => void;
}

const BaitSession: React.FC<Props> = ({ initialScam, onIntelExtracted }) => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'scammer', content: initialScam, timestamp: Date.now() }
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping, isSpeaking]);

  const playVoiceResponse = async (text: string) => {
    try {
      setIsSpeaking(true);
      const base64Audio = await generateAudioFromText(text);

      if (base64Audio) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }

        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);

        source.onended = () => {
          setIsSpeaking(false);
        };

        source.start(0);
      } else {
        setIsSpeaking(false);
      }
    } catch (e) {
      console.error("Voice synthesis failed", e);
      setIsSpeaking(false);
    }
  };

  const runBaitCycle = async () => {
    setIsTyping(true);
    try {
      const history = messages.map(m => ({ role: m.role, content: m.content }));
      const baitText = await generateBaitResponse(history);

      setMessages(prev => [...prev, { role: 'bot', content: baitText, timestamp: Date.now() }]);

      // Trigger Voice Playback
      await playVoiceResponse(baitText);

    } catch (e) {
      console.error(e);
    } finally {
      setIsTyping(false);
    }
  };

  useEffect(() => {
    if (messages.length === 1 && messages[0].role === 'scammer') {
      setTimeout(runBaitCycle, 1500);
    }
  }, []);

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim()) return;
    const newMsg: ChatMessage = { role: 'scammer', content: reply, timestamp: Date.now() };
    setMessages(prev => [...prev, newMsg]);

    const analysis = await analyzeMessage(reply);
    if (analysis.isScam) {
      onIntelExtracted(analysis.extractedInfo);
    }

    setTimeout(runBaitCycle, 1000);
  };

  return (
    <div className="bg-slate-800 rounded-xl border border-slate-700 flex flex-col h-[500px] overflow-hidden shadow-2xl">
      <div className="p-4 bg-slate-900 border-b border-slate-700 flex items-center justify-between">
        <div className="flex items-center space-x-2">
          <div className="relative">
            <div className={`w-2 h-2 rounded-full bg-red-500 ${isSpeaking ? 'animate-ping' : 'animate-pulse'}`}></div>
            {isSpeaking && <div className="absolute top-0 left-0 w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>}
          </div>
          <span className="font-bold text-slate-200">Autonomous Voice Baiting</span>
        </div>
        <div className="flex items-center space-x-3">
          {isSpeaking && (
            <div className="flex items-center space-x-1">
              <div className="w-0.5 h-3 bg-blue-500 animate-[bounce_1s_infinite_0s]"></div>
              <div className="w-0.5 h-4 bg-blue-400 animate-[bounce_1s_infinite_0.1s]"></div>
              <div className="w-0.5 h-2 bg-blue-600 animate-[bounce_1s_infinite_0.2s]"></div>
              <div className="w-0.5 h-3 bg-blue-400 animate-[bounce_1s_infinite_0.3s]"></div>
            </div>
          )}
          <span className="text-[10px] text-slate-500 font-mono">BCR_LIVE_FEED</span>
        </div>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-900/30">
        {messages.map((m, idx) => (
          <div key={idx} className={`flex ${m.role === 'scammer' ? 'justify-start' : 'justify-end'}`}>
            <div className={`max-w-[80%] rounded-2xl px-4 py-3 text-sm transition-all duration-300 ${
              m.role === 'scammer' 
              ? 'bg-slate-700 text-slate-200 rounded-tl-none border border-slate-600' 
              : 'bg-blue-600 text-white rounded-tr-none shadow-lg shadow-blue-900/20'
            }`}>
              <div className="flex items-center justify-between mb-1">
                <div className="text-[10px] font-black uppercase tracking-tighter opacity-50">
                  {m.role === 'scammer' ? 'Suspicious Entity' : 'Rakshak AI (Voice)'}
                </div>
                {m.role === 'bot' && idx === messages.length - 1 && isSpeaking && (
                  <svg className="w-3 h-3 text-white/50 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
                  </svg>
                )}
              </div>
              <div className="leading-relaxed">{m.content}</div>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-end">
            <div className="bg-blue-600/30 text-white rounded-2xl px-4 py-2 text-xs flex items-center space-x-1 border border-blue-500/10">
              <span className="w-1 h-1 bg-white rounded-full animate-bounce"></span>
              <span className="w-1 h-1 bg-white rounded-full animate-bounce [animation-delay:0.2s]"></span>
              <span className="w-1 h-1 bg-white rounded-full animate-bounce [animation-delay:0.4s]"></span>
              <span className="ml-2 font-mono text-[9px] uppercase tracking-widest opacity-70">Synthesizing Strategy</span>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-slate-900 border-t border-slate-700">
        <form onSubmit={(e) => {
          e.preventDefault();
          const target = e.target as any;
          handleManualScammerReply(target.reply.value);
          target.reply.value = '';
        }} className="flex space-x-2">
          <input 
            name="reply"
            type="text" 
            autoComplete="off"
            placeholder="Simulate target's text/voice reply..."
            className="flex-1 bg-slate-800 border border-slate-700 rounded-lg px-4 py-2 text-sm text-slate-200 outline-none focus:ring-1 focus:ring-blue-500 transition-all"
          />
          <button type="submit" className="bg-blue-600 hover:bg-blue-500 text-white px-5 py-2 rounded-lg text-xs font-black uppercase tracking-widest transition-all active:scale-95 shadow-lg shadow-blue-900/30">
            Push
          </button>
        </form>
        <p className="text-[9px] text-slate-600 mt-2 text-center font-mono uppercase tracking-[0.2em]">
          End-to-End Forensic Encryption: ACTIVE
        </p>
      </div>
    </div>
  );
};

