  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis) => {
    const logId = Math.random().toString(36).substr(2, 9);
    const newLog: IntelligenceLog = {
      ...analysis,
      id: logId,
      originalMessage: message,
      timestamp: Date.now()
    };
    setLogs(prev => [newLog, ...prev]);

    if (analysis.isScam) {
      const newSession: HoneypotSession = {
        id: logId,
        targetAlias: `TARGET_${logId.toUpperCase()}`,
        analysis: analysis,
        messages: [{ role: 'scammer', content: message, timestamp: Date.now() }],
        status: 'active',
        lastActivity: Date.now()
      };
      setSessions(prev => [newSession, ...prev]);
      setSelectedSessionId(newSession.id);
      setActiveTab(Tab.Baiting);
    } else {
      setActiveTab(Tab.Dashboard);
    }
  };

  const updateSessionMessages = (sessionId: string, messages: ChatMessage[]) => {
