          <TabButton active={activeTab === Tab.VideoScanner} onClick={() => setActiveTab(Tab.VideoScanner)} label="Video Forensic" />
          <TabButton active={activeTab === Tab.Dashboard} onClick={() => setActiveTab(Tab.Dashboard)} label="Intel Log" />
          <TabButton active={activeTab === Tab.Baiting} onClick={() => setActiveTab(Tab.Baiting)} label={`Honeypot${sessions.length > 0 ? ` (${sessions.length})` : ''}`} />
          <TabButton active={activeTab === Tab.ApiDocs} onClick={() => setActiveTab(Tab.ApiDocs)} label="API" />
