import React, { useState, useEffect, useRef } from 'react';
import { analyzeMessage, analyzeVideoFrame } from '../services/geminiService';
import { ScamAnalysis, VideoAnalysis } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
}

enum IntakeMode {
  Text = 'TEXT',
  Media = 'MEDIA'
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete }) => {
  const [mode, setMode] = useState<IntakeMode>(IntakeMode.Text);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [urlInput, setUrlInput] = useState('');

  const recognitionRef = useRef<any>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'en-IN';

      recognition.onresult = (event: any) => {
        let finalTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) finalTranscript += event.results[i][0].transcript;
        }
        setInput(prev => prev + finalTranscript);
      };

      recognition.onend = () => setIsListening(false);
      recognition.onerror = () => setIsListening(false);
      recognitionRef.current = recognition;
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) return alert("Speech recognition not supported.");
    if (isListening) recognitionRef.current.stop();
    else { setIsListening(true); recognitionRef.current.start(); }
  };

  const extractFrameFromVideo = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.src = URL.createObjectURL(file);
      video.muted = true;
      video.play();

      video.onloadeddata = () => {
        video.currentTime = 1; // Seek to 1s to get a good frame
      };

      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(video, 0, 0);
        const base64 = canvas.toDataURL('image/jpeg').split(',')[1];
        URL.revokeObjectURL(video.src);
        resolve(base64);
      };

      video.onerror = reject;
    });
  };

  const handleAnalyze = async () => {
    setLoading(true);
    try {
      if (mode === IntakeMode.Text) {
        if (!input.trim()) return;
        const result = await analyzeMessage(input);
        onAnalysisComplete(input, result);
        setInput('');
      } else {
        // Media Analysis
        if (videoFile) {
          const frame = await extractFrameFromVideo(videoFile);
          const visualResult = await analyzeVideoFrame(frame);

          // Map VideoAnalysis to a unified ScamAnalysis for the dashboard/honeypot
          const mappedResult: ScamAnalysis = {
            isScam: visualResult.isFraudulent,
            confidence: visualResult.anomalyScore,
            scamType: visualResult.isFraudulent ? "Video/Deepfake Fraud" : "Clean Media",
            threatLevel: visualResult.isFraudulent ? 'High' : 'Low',
            summary: `Video Forensic Analysis: ${visualResult.forensicNotes}`,
            extractedInfo: { upiIds: [], bankDetails: [], phoneNumbers: [], links: [] },
            suggestedBaitResponse: visualResult.isFraudulent ? "Maintain visual recording. Ask for their employee ID and badge verification." : "Media feed appears authentic."
          };

          onAnalysisComplete(`[VIDEO EVIDENCE: ${videoFile.name}]`, mappedResult);
          setVideoFile(null);
        } else if (urlInput.trim()) {
          const result = await analyzeMessage(`Analyze this suspicious link: ${urlInput}`);
          onAnalysisComplete(`[URL SCAN: ${urlInput}]`, result);
          setUrlInput('');
        }
      }
    } catch (error) {
      console.error("Analysis failed", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 shadow-2xl relative overflow-hidden">
      {/* Background Cyber-decor */}
      <div className="absolute top-0 right-0 p-2 opacity-10 pointer-events-none">
        <svg className="w-24 h-24" fill="currentColor" viewBox="0 0 24 24">
          <path d="M12 2L4.5 20.29l.71.71L12 18l6.79 3 .71-.71L12 2z" />
        </svg>
      </div>

      <div className="flex items-center justify-between mb-6">
        <div className="flex bg-slate-900/50 p-1 rounded-xl border border-slate-700">
          <button 
            onClick={() => setMode(IntakeMode.Text)}
            className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${mode === IntakeMode.Text ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}
          >
            Text Signals
          </button>
          <button 
            onClick={() => setMode(IntakeMode.Media)}
            className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${mode === IntakeMode.Media ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}
          >
            Media Evidence
          </button>
        </div>

        {mode === IntakeMode.Text && (
          <button
            onClick={toggleListening}
            className={`p-2 rounded-full transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'bg-slate-700 text-slate-300 hover:bg-slate-600'}`}
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" />
            </svg>
          </button>
        )}
      </div>

      <div className="min-h-[160px]">
        {mode === IntakeMode.Text ? (
          <textarea
            className="w-full h-40 bg-slate-900/80 text-slate-200 p-4 rounded-xl border border-slate-700 focus:ring-1 focus:ring-blue-500 outline-none transition-all placeholder-slate-600 resize-none font-medium"
            placeholder={isListening ? "Listening... System calibrating voice-to-text intake." : "Paste suspected phishing SMS, email body, or chat transcript..."}
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />
        ) : (
          <div className="space-y-4 animate-in fade-in duration-300">
            <div className="relative group">
              <input 
                type="file" 
                accept="video/*,image/*"
                onChange={(e) => setVideoFile(e.target.files?.[0] || null)}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
              />
              <div className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center transition-all ${videoFile ? 'border-blue-500 bg-blue-500/5' : 'border-slate-700 bg-slate-900/50 group-hover:border-slate-500'}`}>
                <svg className={`w-8 h-8 mb-2 ${videoFile ? 'text-blue-400' : 'text-slate-600'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                </svg>
                <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter">
                  {videoFile ? videoFile.name : 'Drop Video File for Forensic Extraction'}
                </span>
                <span className="text-[10px] text-slate-600 mt-1 uppercase tracking-widest">MP4, MOV, WEBM SUPPORTED</span>
              </div>
            </div>

            <div className="relative">
              <input 
                type="text" 
                placeholder="Or paste suspicious video link / URL..."
                value={urlInput}
                onChange={(e) => setUrlInput(e.target.value)}
                className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 text-xs text-slate-200 outline-none focus:ring-1 focus:ring-blue-500"
              />
              <div className="absolute right-3 top-3">
                <svg className="w-4 h-4 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.823a4 4 0 015.656 0l4 4a4 4 0 01-5.656 5.656l-1.103-1.103" />
                </svg>
              </div>
            </div>
          </div>
        )}
      </div>

      <button
        onClick={handleAnalyze}
        disabled={loading || (mode === IntakeMode.Text ? !input.trim() : (!videoFile && !urlInput.trim()))}
        className={`mt-6 w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center transition-all ${
          loading 
          ? 'bg-slate-700 text-slate-400 cursor-wait' 
          : 'bg-blue-600 hover:bg-blue-500 text-white shadow-xl shadow-blue-900/30 active:scale-95'
        }`}
      >
        {loading ? (
          <>
            <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin mr-3"></div>
            Decrypting Forensics...
          </>
        ) : 'Execute Intelligence Scan'}
      </button>

      <div className="mt-4 flex justify-center items-center space-x-4 opacity-30">
        <div className="h-px bg-slate-700 flex-1"></div>
        <span className="text-[8px] font-mono tracking-widest uppercase">Protocol Alpha-7</span>
        <div className="h-px bg-slate-700 flex-1"></div>
      </div>
    </div>
  );
};

export default ScamAnalyzer;

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { ScamAnalysis, VideoAnalysis } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const SCAM_ANALYSIS_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    isScam: { type: Type.BOOLEAN, description: "Whether the message is a scam." },
    confidence: { type: Type.NUMBER, description: "Confidence score from 0 to 1." },
    scamType: { type: Type.STRING, description: "Type of scam (e.g., Phishing, Digital Arrest, Job Scam)." },
    threatLevel: { type: Type.STRING, enum: ["Low", "Medium", "High", "Critical"] },
    summary: { type: Type.STRING, description: "Scam Intelligence Report including threat patterns and recommended forensic actions." },
    extractedInfo: {
      type: Type.OBJECT,
      properties: {
        upiIds: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Extracted financial endpoints: UPI IDs." },
        bankDetails: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Extracted financial endpoints: Bank Accounts/IFSC." },
        phoneNumbers: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Extracted technical debt: Phone numbers." },
        links: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Extracted malicious URLs." }
      },
      required: ["upiIds", "bankDetails", "phoneNumbers", "links"]
    },
    suggestedBaitResponse: { type: Type.STRING, description: "The initial honey-pot response to start engagement." }
  },
  required: ["isScam", "confidence", "scamType", "threatLevel", "summary", "extractedInfo", "suggestedBaitResponse"]
};

const VIDEO_FORENSIC_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    isFraudulent: { type: Type.BOOLEAN },
    anomalyScore: { type: Type.NUMBER, description: "Scale 0-1 of synthetic/fraud indicators." },
    detectedThreats: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Specific cues like 'Fake Uniform', 'Deepfake Artifacts', 'Green Screen Edge'." },
    forensicNotes: { type: Type.STRING },
    subjectIdentification: { type: Type.STRING, description: "Description of the person or entity portrayed." }
  },
  required: ["isFraudulent", "anomalyScore", "detectedThreats", "forensicNotes", "subjectIdentification"]
};

export const analyzeMessage = async (message: string): Promise<ScamAnalysis> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Analyze input for Bharat Cyber Rakshak AI mission objectives. 
Input: "${message}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: SCAM_ANALYSIS_SCHEMA,
      systemInstruction: `You are Bharat Cyber Rakshak AI, an autonomous agentic system designed to protect Indian citizens from cyber fraud.
Your mission is the total neutralization of digital scams through high-fidelity intelligence extraction and forensic reporting.`
    },
  });

  return JSON.parse(response.text);
};

