export const generateBaitResponse = async (history: { role: string, content: string }[]): Promise<string> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: history.map(h => ({
      parts: [{ text: `${h.role === 'scammer' ? 'Scammer' : 'You (Victim Persona)'}: ${h.content}` }]
    })),
    config: {
      systemInstruction: `You are Bharat Cyber Rakshak AI operating in Autonomous Honey-Pot Mode.
Your objective is to psychologically manipulate scammers into revealing their financial infrastructure through believable human engagement.
Respond in the SAME language/dialect as the scammer.`
    }
  });

  return response.text.trim();
};

export const generateAudioFromText = async (text: string): Promise<string | undefined> => {
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
};

export function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { analyzeMessage, analyzeVideoFrame, analyzeUrlWithSearch } from '../services/geminiService';
import { ScamAnalysis, VideoAnalysis } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
}

enum IntakeMode {
  Text = 'TEXT',
  Media = 'MEDIA'
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete }) => {
  const [mode, setMode] = useState<IntakeMode>(IntakeMode.Text);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [previewFrame, setPreviewFrame] = useState<string | null>(null);
  const [urlInput, setUrlInput] = useState('');

  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.lang = 'en-IN';

      recognition.onresult = (event: any) => {
        let finalTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) finalTranscript += event.results[i][0].transcript;
        }
        setInput(prev => prev + finalTranscript);
      };

      recognition.onend = () => setIsListening(false);
      recognition.onerror = () => setIsListening(false);
      recognitionRef.current = recognition;
    }
  }, []);

  const toggleListening = () => {
    if (!recognitionRef.current) return alert("Speech recognition not supported.");
    if (isListening) recognitionRef.current.stop();
    else { setIsListening(true); recognitionRef.current.start(); }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    if (file) {
      setVideoFile(file);
      try {
        const frame = await extractFrameFromVideo(file);
        setPreviewFrame(frame);
      } catch (err) {
        console.error("Frame extraction failed", err);
      }
    }
  };

  const extractFrameFromVideo = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.src = URL.createObjectURL(file);
      video.muted = true;
      video.setAttribute('crossOrigin', 'anonymous');

      video.onloadeddata = () => {
        video.currentTime = Math.min(1, video.duration / 2); // Avoid black frames
      };

      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(video, 0, 0);
        const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
        URL.revokeObjectURL(video.src);
        resolve(base64);
      };

      video.onerror = (e) => reject(e);
      video.load();
    });
  };

  const handleAnalyze = async () => {
    setLoading(true);
    try {
      if (mode === IntakeMode.Text) {
        if (!input.trim()) return;
        const result = await analyzeMessage(input);
        onAnalysisComplete(input, result);
        setInput('');
      } else {
        // Media Analysis
        if (videoFile && previewFrame) {
          const visualResult = await analyzeVideoFrame(previewFrame);

          const mappedResult: ScamAnalysis = {
            isScam: visualResult.isFraudulent,
            confidence: visualResult.anomalyScore,
            scamType: visualResult.isFraudulent ? "Video/Deepfake Fraud" : "Clean Media",
            threatLevel: visualResult.isFraudulent ? 'High' : 'Low',
            summary: `Video Forensic Analysis: ${visualResult.forensicNotes}`,
            extractedInfo: { upiIds: [], bankDetails: [], phoneNumbers: [], links: [] },
            suggestedBaitResponse: visualResult.isFraudulent ? "Question the caller's credentials. Ask for official written documentation via certified mail." : "Media feed appears authentic."
          };

          onAnalysisComplete(`[VIDEO EVIDENCE: ${videoFile.name}]`, mappedResult);
          setVideoFile(null);
          setPreviewFrame(null);
        } else if (urlInput.trim()) {
          const result = await analyzeUrlWithSearch(urlInput);
          onAnalysisComplete(`[URL SCAN: ${urlInput}]`, result);
          setUrlInput('');
        }
      }
    } catch (error) {
      console.error("Analysis failed", error);
      alert("Intelligence synthesis failed. System retry recommended.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 shadow-2xl relative overflow-hidden">
      {/* Background Cyber-decor */}
      <div className="absolute top-0 right-0 p-2 opacity-10 pointer-events-none">
        <svg className="w-24 h-24" fill="currentColor" viewBox="0 0 24 24">
          <path d="M12 2L4.5 20.29l.71.71L12 18l6.79 3 .71-.71L12 2z" />
        </svg>
      </div>

      <div className="flex items-center justify-between mb-6">
        <div className="flex bg-slate-900/50 p-1 rounded-xl border border-slate-700">
          <button 
            onClick={() => setMode(IntakeMode.Text)}
            className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${mode === IntakeMode.Text ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}
          >
            Text Signals
          </button>
          <button 
            onClick={() => setMode(IntakeMode.Media)}
            className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${mode === IntakeMode.Media ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}
          >
            Video / URL Evidence
          </button>
        </div>

        {mode === IntakeMode.Text && (
          <button
            onClick={toggleListening}
            className={`p-2 rounded-full transition-all ${isListening ? 'bg-red-600 text-white animate-pulse' : 'bg-slate-700 text-slate-300 hover:bg-slate-600'}`}
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" />
            </svg>
          </button>
        )}
      </div>

      <div className="min-h-[180px]">
        {mode === IntakeMode.Text ? (
          <textarea
            className="w-full h-40 bg-slate-900/80 text-slate-200 p-4 rounded-xl border border-slate-700 focus:ring-1 focus:ring-blue-500 outline-none transition-all placeholder-slate-600 resize-none font-medium"
            placeholder={isListening ? "Listening... System calibrating voice-to-text intake." : "Paste suspected phishing SMS, WhatsApp logs, or call transcripts..."}
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />
        ) : (
          <div className="space-y-5 animate-in fade-in duration-300">
            <div className="relative group">
              <input 
                type="file" 
                accept="video/*"
                onChange={handleFileChange}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20"
              />
              <div className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center transition-all ${videoFile ? 'border-blue-500 bg-blue-500/5' : 'border-slate-700 bg-slate-900/50 group-hover:border-slate-500'}`}>
                {previewFrame ? (
                  <div className="relative w-32 h-20 mb-3 rounded-lg overflow-hidden border border-blue-500/50 shadow-[0_0_15px_rgba(59,130,246,0.2)]">
                    <img src={`data:image/jpeg;base64,${previewFrame}`} alt="Forensic Frame" className="w-full h-full object-cover" />
                    <div className="absolute inset-0 bg-blue-500/10 flex items-center justify-center">
                       <span className="text-[8px] font-black text-white bg-blue-600 px-1 py-0.5 rounded">FRAME_EXTRACTED</span>
                    </div>
                  </div>
                ) : (
                  <svg className={`w-8 h-8 mb-2 ${videoFile ? 'text-blue-400' : 'text-slate-600'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                  </svg>
                )}
                <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter text-center">
                  {videoFile ? videoFile.name : 'Upload Fraudulent Video for Forensic Scan'}
                </span>
                <span className="text-[9px] text-slate-600 mt-1 uppercase tracking-widest font-mono">AUTOMATIC DEEPFAKE DETECTION ACTIVE</span>
              </div>
            </div>

            <div className="flex items-center space-x-4">
              <div className="h-px bg-slate-700 flex-1"></div>
              <span className="text-[9px] font-black text-slate-600 uppercase tracking-widest">OR</span>
              <div className="h-px bg-slate-700 flex-1"></div>
            </div>

            <div className="relative">
              <input 
                type="text" 
                placeholder="Paste suspicious website or video URL..."
                value={urlInput}
                onChange={(e) => setUrlInput(e.target.value)}
                className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 text-xs text-slate-200 outline-none focus:ring-1 focus:ring-blue-500 pr-10"
              />
              <div className="absolute right-3 top-3">
                <svg className="w-4 h-4 text-blue-500/50" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
            </div>
          </div>
        )}
      </div>

      <button
        onClick={handleAnalyze}
        disabled={loading || (mode === IntakeMode.Text ? !input.trim() : (!videoFile && !urlInput.trim()))}
        className={`mt-6 w-full py-4 rounded-xl font-black text-xs uppercase tracking-[0.2em] flex items-center justify-center transition-all ${
          loading 
          ? 'bg-slate-700 text-slate-400 cursor-wait' 
          : 'bg-blue-600 hover:bg-blue-500 text-white shadow-xl shadow-blue-900/30 active:scale-95'
        }`}
      >
        {loading ? (
          <>
            <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin mr-3"></div>
            Synthesizing Intelligence...
          </>
        ) : (
          <>
            <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />
            </svg>
            Execute Forensic Protocol
          </>
        )}
      </button>

      <div className="mt-4 flex justify-between items-center px-1">
        <span className="text-[8px] font-mono tracking-widest uppercase text-slate-600">INTEL_NODE: BH-RAKSHAK_01</span>
        <span className="text-[8px] font-mono tracking-widest uppercase text-slate-600">STATUS: READY</span>
      </div>
    </div>
  );
};

export default ScamAnalyzer;

export interface ExtractedItem<T> {
  value: T;
  confidence: number; // 0-100
}

export interface ExtractedInfo {
  upiIds: ExtractedItem<string>[];
  bankDetails: ExtractedItem<string>[];
  phoneNumbers: ExtractedItem<string>[];
  links: ExtractedItem<string>[];
  cryptoWallets: ExtractedItem<string>[];
  fakeIdentities: ExtractedItem<string>[];
}

export interface ScammerFingerprint {
  primaryHandle: string;
  primaryPhone: string;
  primaryLink: string;
  category: string;
}

export interface ScamAnalysis {
  isScam: boolean;
  confidence: number; // overall scam probability 0-1
  scamType: string;
  channel: 'text' | 'call' | 'video' | 'qr' | 'app' | 'social' | 'screen-share';
  threatLevel: 'Low' | 'Medium' | 'High' | 'Critical';
  summary: string;
  extractedInfo: ExtractedInfo;
  fingerprint: ScammerFingerprint;
  recommendedActions: string[];
  suggestedBaitResponse: string;
}

export interface VideoAnalysis {
  isFraudulent: boolean;
  anomalyScore: number;
  detectedThreats: string[];
  forensicNotes: string;
  subjectIdentification: string;
}

export interface ChatMessage {
  role: 'user' | 'bot' | 'scammer';
  content: string;
  timestamp: number;
}

export interface IntelligenceLog extends ScamAnalysis {
  id: string;
  originalMessage: string;
  timestamp: number;
}

export interface HoneypotSession {
  id: string;
  targetAlias: string;
  analysis: ScamAnalysis;
  messages: ChatMessage[];
  status: 'active' | 'baiting' | 'extracted';
  lastActivity: number;
}

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { ScamAnalysis, VideoAnalysis } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const EXTRACTED_ITEM_SCHEMA = (itemType: Type) => ({
  type: Type.OBJECT,
  properties: {
    value: { type: itemType },
    confidence: { type: Type.NUMBER, description: "Confidence score from 0 to 100." }
  },
  required: ["value", "confidence"]
});

const SCAM_ANALYSIS_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    isScam: { type: Type.BOOLEAN },
    confidence: { type: Type.NUMBER },
    scamType: { type: Type.STRING },
    channel: { type: Type.STRING, enum: ['text', 'call', 'video', 'qr', 'app', 'social', 'screen-share'] },
    threatLevel: { type: Type.STRING, enum: ["Low", "Medium", "High", "Critical"] },
    summary: { type: Type.STRING },
    extractedInfo: {
      type: Type.OBJECT,
      properties: {
        upiIds: { type: Type.ARRAY, items: EXTRACTED_ITEM_SCHEMA(Type.STRING) },
        bankDetails: { type: Type.ARRAY, items: EXTRACTED_ITEM_SCHEMA(Type.STRING) },
        phoneNumbers: { type: Type.ARRAY, items: EXTRACTED_ITEM_SCHEMA(Type.STRING) },
        links: { type: Type.ARRAY, items: EXTRACTED_ITEM_SCHEMA(Type.STRING) },
        cryptoWallets: { type: Type.ARRAY, items: EXTRACTED_ITEM_SCHEMA(Type.STRING) },
        fakeIdentities: { type: Type.ARRAY, items: EXTRACTED_ITEM_SCHEMA(Type.STRING) }
      },
      required: ["upiIds", "bankDetails", "phoneNumbers", "links", "cryptoWallets", "fakeIdentities"]
    },
    fingerprint: {
      type: Type.OBJECT,
      properties: {
        primaryHandle: { type: Type.STRING },
        primaryPhone: { type: Type.STRING },
        primaryLink: { type: Type.STRING },
        category: { type: Type.STRING }
      },
      required: ["primaryHandle", "primaryPhone", "primaryLink", "category"]
    },
    recommendedActions: { type: Type.ARRAY, items: { type: Type.STRING } },
    suggestedBaitResponse: { type: Type.STRING }
  },
  required: ["isScam", "confidence", "scamType", "channel", "threatLevel", "summary", "extractedInfo", "fingerprint", "recommendedActions", "suggestedBaitResponse"]
};

const MISSION_DIRECTIVE = `You are Bharat Cyber Rakshak AI — an autonomous, agentic cyber-fraud defense system.
Your mission: Detect, engage, and dismantle scam networks across Text, Voice, Video, QR, APK, and Social Media.
FORENSIC RULES: 
- NEVER invent or hallucinate financial data.
- ONLY extract what is explicitly provided.
- Assign 0-100 confidence based on clarity.
- Prioritize high-threat patterns: QR scams, SIM-swap, Remote Access (AnyDesk/TeamViewer), and Digital Arrest impersonation.`;

export const analyzeMessage = async (message: string): Promise<ScamAnalysis> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `MISSION INTAKE: Analyze input for forensic markers. 
Input: "${message}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: SCAM_ANALYSIS_SCHEMA,
      systemInstruction: MISSION_DIRECTIVE
    },
  });

  return JSON.parse(response.text);
};

