import React, { useState, useEffect, useRef } from 'react';
import { generateBaitResponse, analyzeMessage, generateAudioFromText, decodeBase64, decodeAudioData } from '../services/geminiService';
import { ChatMessage, ExtractedInfo } from '../types';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [currentIntel, setCurrentIntel] = useState<ExtractedInfo | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [initialMessages, isTyping, isSpeaking]);

  const playVoiceResponse = async (text: string) => {
    try {
      setIsSpeaking(true);
      const base64Audio = await generateAudioFromText(text);

      if (base64Audio) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }

        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);

        source.onended = () => {
          setIsSpeaking(false);
        };

        source.start(0);
      } else {
        setIsSpeaking(false);
      }
    } catch (e) {
      console.error("Voice synthesis failed", e);
      setIsSpeaking(false);
    }
  };

  const runBaitCycle = async (currentMessages: ChatMessage[]) => {
    setIsTyping(true);
    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const baitText = await generateBaitResponse(history);

      const updatedMessages: ChatMessage[] = [...currentMessages, { role: 'bot', content: baitText, timestamp: Date.now() }];
      onMessagesUpdate(updatedMessages);

      await playVoiceResponse(baitText);
    } catch (e) {
      console.error(e);
    } finally {
      setIsTyping(false);
    }
  };

  useEffect(() => {
    if (initialMessages.length === 1 && initialMessages[0].role === 'scammer') {
      const timer = setTimeout(() => runBaitCycle(initialMessages), 1500);
      return () => clearTimeout(timer);
    }
  }, []);

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim()) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);

    analyzeMessage(reply).then(analysis => {
      if (analysis.isScam) {
        setCurrentIntel(prev => {
          const merged = { ...analysis.extractedInfo };
          onIntelExtracted(merged);
          return merged;
        });
      }
    });

    setTimeout(() => runBaitCycle(updatedMessages), 1000);
  };

  return (
    <div className="bg-slate-800 rounded-xl border border-slate-700 flex flex-col h-full overflow-hidden shadow-2xl cyber-card">
      <div className="p-4 bg-slate-900 border-b border-slate-700 flex items-center justify-between">
        <div className="flex items-center space-x-2">
          <div className="relative">
            <div className={`w-2 h-2 rounded-full bg-red-500 ${isSpeaking ? 'animate-ping' : 'animate-pulse'}`}></div>
          </div>
          <span className="font-bold text-slate-200 text-sm uppercase tracking-widest">Undercover Engagement</span>
        </div>
        <div className="flex items-center space-x-3">
          {isSpeaking && <AudioWaveform />}
          <span className="text-[9px] text-slate-500 font-mono tracking-widest">{sessionId}</span>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Chat Area */}
        <div className="flex-1 flex flex-col overflow-hidden border-r border-slate-700">
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-900/30">
            {initialMessages.map((m, idx) => (
              <div key={idx} className={`flex ${m.role === 'scammer' ? 'justify-start' : 'justify-end'}`}>
                <div className={`max-w-[85%] rounded-2xl px-4 py-3 text-xs transition-all duration-300 ${
                  m.role === 'scammer' 
                  ? 'bg-slate-700 text-slate-200 rounded-tl-none border border-slate-600' 
                  : 'bg-blue-600 text-white rounded-tr-none shadow-lg shadow-blue-900/20'
                }`}>
                  <div className="flex items-center justify-between mb-1 opacity-50 text-[9px] font-black uppercase tracking-tighter">
                    <span>{m.role === 'scammer' ? 'Target Entity' : 'Rakshak AI (Persona)'}</span>
                    <span>{new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  </div>
                  <div className="leading-relaxed">{m.content}</div>
                </div>
              </div>
            ))}
            {isTyping && <TypingIndicator />}
          </div>

          <div className="p-4 bg-slate-900 border-t border-slate-700">
            <form onSubmit={(e) => {
              e.preventDefault();
              const target = e.target as any;
              handleManualScammerReply(target.reply.value);
              target.reply.value = '';
            }} className="flex space-x-2">
              <input 
                name="reply"
                type="text" 
                autoComplete="off"
                placeholder="Simulate scammer's next response..."
                className="flex-1 bg-slate-800 border border-slate-700 rounded-lg px-4 py-2 text-xs text-slate-200 outline-none focus:ring-1 focus:ring-blue-500 transition-all"
              />
              <button type="submit" className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all shadow-lg shadow-blue-900/30">
                Send
              </button>
            </form>
          </div>
        </div>

        {/* Real-time Intel Sidebar */}
        <div className="hidden lg:flex w-56 bg-slate-900/50 flex-col p-4 space-y-4 overflow-y-auto">
          <h3 className="text-[9px] font-black text-blue-500 uppercase tracking-widest border-b border-blue-500/20 pb-2">Extracted Intel</h3>

          <IntelGroup title="Financial" items={[
            ...(currentIntel?.upiIds || []).map(i => ({ label: 'UPI', value: i.value, conf: i.confidence })),
            ...(currentIntel?.bankDetails || []).map(i => ({ label: 'BANK', value: i.value, conf: i.confidence }))
          ]} />

          <IntelGroup title="Technical" items={[
            ...(currentIntel?.phoneNumbers || []).map(i => ({ label: 'TEL', value: i.value, conf: i.confidence })),
            ...(currentIntel?.links || []).map(i => ({ label: 'URL', value: i.value, conf: i.confidence }))
          ]} />

          <IntelGroup title="Identity" items={[
            ...(currentIntel?.fakeIdentities || []).map(i => ({ label: 'NAME', value: i.value, conf: i.confidence })),
            ...(currentIntel?.cryptoWallets || []).map(i => ({ label: 'WALLET', value: i.value, conf: i.confidence }))
          ]} />

          {!currentIntel && (
            <div className="text-[9px] text-slate-600 italic mt-10 text-center">Awaiting data revealing triggers...</div>
          )}
        </div>
      </div>
    </div>
  );
};

const IntelGroup = ({ title, items }: { title: string, items: any[] }) => {
