import React, { useState, useEffect, useRef } from 'react';
import { analyzeMessage, analyzeVideoFrame, analyzeUrlWithSearch } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
}

enum IntakeType {
  Message = 'MESSAGE',
  Transcript = 'TRANSCRIPT',
  Media = 'MEDIA'
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete }) => {
  const [activeType, setActiveType] = useState<IntakeType>(IntakeType.Message);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [previewFrame, setPreviewFrame] = useState<string | null>(null);
  const [urlInput, setUrlInput] = useState('');

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    if (file) {
      setVideoFile(file);
      try {
        const frame = await extractFrameFromVideo(file);
        setPreviewFrame(frame);
      } catch (err) {
        console.error("Frame extraction failed", err);
      }
    }
  };

  const extractFrameFromVideo = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.src = URL.createObjectURL(file);
      video.muted = true;
      video.setAttribute('crossOrigin', 'anonymous');
      video.onloadeddata = () => { video.currentTime = Math.min(1, video.duration / 2); };
      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(video, 0, 0);
        const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
        URL.revokeObjectURL(video.src);
        resolve(base64);
      };
      video.onerror = (e) => reject(e);
      video.load();
    });
  };

  const handleAnalyze = async () => {
    setLoading(true);
    try {
      if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
        if (!input.trim()) return;
        const result = await analyzeMessage(input);
        onAnalysisComplete(input, result);
        setInput('');
      } else {
        if (videoFile && previewFrame) {
          const visualResult = await analyzeVideoFrame(previewFrame);
          const mappedResult: ScamAnalysis = {
            isScam: visualResult.isFraudulent,
            confidence: visualResult.anomalyScore,
            scamType: visualResult.isFraudulent ? "Video/Deepfake Fraud" : "Clean Media",
            channel: 'video',
            threatLevel: visualResult.isFraudulent ? 'High' : 'Low',
            summary: `Video Forensic Analysis: ${visualResult.forensicNotes}`,
            extractedInfo: { upiIds: [], bankDetails: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
            fingerprint: { primaryHandle: visualResult.subjectIdentification || 'UNKNOWN', primaryPhone: '', primaryLink: '', category: visualResult.isFraudulent ? 'Deepfake' : 'Legitimate' },
            recommendedActions: visualResult.isFraudulent ? visualResult.detectedThreats : [],
            suggestedBaitResponse: visualResult.isFraudulent ? "Question the caller's credentials." : "Media feed appears authentic."
          };
          onAnalysisComplete(`[VIDEO: ${videoFile.name}]`, mappedResult);
          setVideoFile(null);
          setPreviewFrame(null);
        } else if (urlInput.trim()) {
          const result = await analyzeUrlWithSearch(urlInput);
          onAnalysisComplete(urlInput, result);
          setUrlInput('');
        }
      }
    } catch (error) {
      console.error("Analysis failed", error);
      alert("Analysis service busy. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
      {/* Large Tabs */}
      <div className="flex border-b border-slate-100 bg-slate-50/50">
        <TabButton 
          active={activeType === IntakeType.Message} 
          onClick={() => setActiveType(IntakeType.Message)} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z" /></svg>}
          label="Message / Email" 
        />
        <TabButton 
          active={activeType === IntakeType.Transcript} 
          onClick={() => setActiveType(IntakeType.Transcript)} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" /></svg>}
          label="Call Transcript" 
        />
        <TabButton 
          active={activeType === IntakeType.Media} 
          onClick={() => setActiveType(IntakeType.Media)} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>}
          label="Video / URL" 
        />
      </div>

      <div className="p-8 space-y-6">
        {activeType === IntakeType.Media ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="relative group">
              <input type="file" accept="video/*" onChange={handleFileChange} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" />
              <div className={`h-48 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all ${videoFile ? 'bg-blue-50 border-blue-400' : 'bg-slate-50 border-slate-200 group-hover:bg-slate-100'}`}>
                {previewFrame ? (
                  <img src={`data:image/jpeg;base64,${previewFrame}`} className="w-full h-full object-cover rounded-xl" />
                ) : (
                  <>
                    <div className="p-3 bg-white rounded-full shadow-sm mb-3">
                      <svg className="w-6 h-6 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                    </div>
                    <p className="text-sm font-bold text-slate-700">Upload Video</p>
                    <p className="text-xs text-slate-400">MP4, MOV supported</p>
                  </>
                )}
              </div>
            </div>
            <div className="flex flex-col justify-center space-y-3">
              <p className="text-xs font-bold text-slate-500 uppercase">Or provide a link</p>
              <input 
                type="text" 
                placeholder="Paste video or website link here..." 
                value={urlInput}
                onChange={(e) => setUrlInput(e.target.value)}
                className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
              />
            </div>
          </div>
        ) : (
          <textarea
            className="w-full h-48 p-6 bg-slate-50 border border-slate-200 rounded-2xl text-slate-700 placeholder-slate-400 focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none text-lg font-medium"
            placeholder={activeType === IntakeType.Message ? "Paste the suspicious text message or email content here..." : "Type or paste the conversation from the phone call..."}
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />
        )}

        <button
          onClick={handleAnalyze}
          disabled={loading || (activeType !== IntakeType.Media && !input.trim()) || (activeType === IntakeType.Media && !videoFile && !urlInput.trim())}
          className="w-full py-5 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 text-white rounded-2xl font-black text-xl shadow-lg shadow-blue-600/20 active:scale-[0.98] transition-all flex items-center justify-center space-x-3"
        >
          {loading ? (
            <div className="flex items-center space-x-3">
              <div className="w-5 h-5 border-3 border-white/30 border-t-white rounded-full animate-spin"></div>
              <span>Scanning...</span>
            </div>
          ) : (
            <>
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              <span>Scan for Fraud</span>
            </>
          )}
        </button>
      </div>
    </div>
  );
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex items-center justify-center py-6 px-4 space-x-3 transition-all border-b-4 ${active ? 'border-blue-600 text-blue-600 bg-white' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
