import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { decodeBase64, decodeAudioData } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAlert: (analysis: ScamAnalysis) => void;
}

const LiveShield: React.FC<Props> = ({ onAlert }) => {
  const [isActive, setIsActive] = useState(false);
  const [transcription, setTranscription] = useState<string[]>([]);
  const [lastAlert, setLastAlert] = useState<string | null>(null);
  const [threatLevel, setThreatLevel] = useState<'Low' | 'Medium' | 'High'>('Low');

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const frameIntervalRef = useRef<number | null>(null);

  const startShield = async () => {
    setIsActive(true);
    setTranscription([]);
    setLastAlert(null);
    setThreatLevel('Low');

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = outputAudioContext;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContext.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const base64 = btoa(String.fromCharCode(...new Uint8Array(int16.buffer)));
              sessionPromise.then(s => s.sendRealtimeInput({ media: { data: base64, mimeType: 'audio/pcm;rate=16000' } }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContext.destination);

            // Frame streaming
            const ctx = canvasRef.current?.getContext('2d');
            frameIntervalRef.current = window.setInterval(() => {
              if (videoRef.current && canvasRef.current && ctx) {
                canvasRef.current.width = 320;
                canvasRef.current.height = 240;
                ctx.drawImage(videoRef.current, 0, 0, 320, 240);
                const base64 = canvasRef.current.toDataURL('image/jpeg', 0.5).split(',')[1];
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: base64, mimeType: 'image/jpeg' } }));
              }
            }, 2000);
          },
          onmessage: async (msg: LiveServerMessage) => {
            if (msg.serverContent?.inputTranscription) {
              const text = msg.serverContent.inputTranscription.text;
              setTranscription(prev => [...prev.slice(-4), `Target: ${text}`]);
              checkScamTriggers(text);
            }
            if (msg.serverContent?.outputTranscription) {
              const text = msg.serverContent.outputTranscription.text;
              setTranscription(prev => [...prev.slice(-4), `AI Advice: ${text}`]);
            }
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: `You are Bharat Cyber Rakshak AI. Monitor this live audio/video feed for scam indicators. 
          Focus on:
          1. Digital Arrest threats (CBI, Customs, Police impersonation).
          2. Pressure tactics for OTPs or Bank logins.
          3. Deepfake artifacts or unnatural movement.
          Provide short, quiet advice only if a scam is highly likely.`
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error("Shield activation failed", err);
      setIsActive(false);
    }
  };

  const checkScamTriggers = (text: string) => {
    const triggers = ['otp', 'bank login', 'police', 'customs', 'arrest', 'urgent', 'payment', 'upi', 'account frozen'];
    const found = triggers.filter(t => text.toLowerCase().includes(t));
    if (found.length > 0) {
      setThreatLevel('High');
      setLastAlert(`DETECTED SCAM MARKERS: ${found.join(', ').toUpperCase()}`);
    }
  };

  const stopShield = () => {
    if (sessionRef.current) sessionRef.current.close();
    if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
    setIsActive(false);
  };

  useEffect(() => {
    return () => stopShield();
  }, []);

  return (
    <div className="bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden">
      <div className={`px-8 py-6 flex items-center justify-between border-b border-slate-100 ${isActive ? 'bg-blue-600 text-white' : 'bg-slate-50 text-slate-400'}`}>
        <div className="flex items-center space-x-4">
          <div className={`p-3 rounded-2xl ${isActive ? 'bg-blue-500 animate-pulse' : 'bg-slate-200'}`}>
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
          </div>
          <div>
            <h3 className="text-2xl font-black uppercase tracking-tight">Live Protection Shield</h3>
            <p className="text-sm font-bold opacity-70 uppercase tracking-widest">{isActive ? 'Monitoring Audio & Video in Real-Time' : 'System Standby'}</p>
          </div>
        </div>
        {isActive && (
          <div className="flex items-center space-x-2 bg-blue-700 px-4 py-2 rounded-xl border border-blue-400">
             <div className="w-3 h-3 bg-white rounded-full animate-ping"></div>
             <span className="text-xs font-black uppercase tracking-widest">Active Guard</span>
          </div>
        )}
      </div>

      <div className="p-8 grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="aspect-video bg-slate-900 rounded-3xl overflow-hidden relative shadow-inner">
             <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover grayscale opacity-40 mix-blend-screen" />
             <canvas ref={canvasRef} className="hidden" />

             {isActive && (
               <div className="absolute inset-0 pointer-events-none flex flex-col justify-between p-6">
                 <div className="flex justify-between items-start">
                    <div className="text-[10px] font-black text-blue-400 uppercase tracking-[0.2em] bg-black/40 px-2 py-1 rounded">Forensic Feed Activated</div>
                    <div className="text-[10px] font-black text-white uppercase tracking-widest bg-blue-500 px-2 py-1 rounded">24 FPS SYNC</div>
                 </div>
                 <div className="space-y-2">
                    {transcription.map((line, i) => (
                      <div key={i} className="text-[11px] font-bold text-white bg-black/50 backdrop-blur-md px-3 py-1.5 rounded-lg w-fit animate-in slide-in-from-left-2">{line}</div>
                    ))}
                 </div>
               </div>
             )}

             {!isActive && (
               <div className="absolute inset-0 flex items-center justify-center">
                 <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">Camera Feed Offline</p>
               </div>
             )}
          </div>
        </div>

        <div className="flex flex-col space-y-6">
          <div className={`flex-1 p-6 rounded-3xl border-2 transition-all duration-500 flex flex-col items-center justify-center text-center space-y-4 ${
            threatLevel === 'High' ? 'bg-red-50 border-red-200' : 'bg-slate-50 border-slate-100'
          }`}>
            {threatLevel === 'High' ? (
              <>
                <div className="w-16 h-16 bg-red-600 rounded-full flex items-center justify-center shadow-lg shadow-red-500/30 animate-bounce">
                  <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                </div>
                <h4 className="text-2xl font-black text-red-600 uppercase tracking-tighter">Danger: Scam Detected</h4>
                <p className="text-sm font-bold text-red-700/60 max-w-xs">{lastAlert}</p>
                <div className="pt-4 flex space-x-3">
                  <button className="px-6 py-2 bg-red-600 text-white rounded-xl text-xs font-black uppercase tracking-widest hover:bg-red-700">Record Evidence</button>
                  <button onClick={() => setThreatLevel('Low')} className="px-6 py-2 bg-white text-red-600 border border-red-200 rounded-xl text-xs font-black uppercase tracking-widest">Clear Alert</button>
                </div>
              </>
            ) : (
              <>
                <div className={`w-16 h-16 rounded-full flex items-center justify-center transition-all ${isActive ? 'bg-blue-600' : 'bg-slate-200'}`}>
                  <svg className={`w-10 h-10 ${isActive ? 'text-white' : 'text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                </div>
                <h4 className="text-lg font-black text-slate-800 uppercase tracking-tight">{isActive ? 'Scanning Call Integrity...' : 'Live Guard Ready'}</h4>
                <p className="text-sm font-medium text-slate-500 max-w-xs">System will flash red and vibrate if suspicious triggers are heard.</p>
              </>
            )}
          </div>

          <button
            onClick={isActive ? stopShield : startShield}
            className={`w-full py-5 rounded-2xl font-black text-xl shadow-xl transition-all active:scale-[0.98] flex items-center justify-center space-x-3 ${
              isActive 
              ? 'bg-white border-2 border-red-600 text-red-600 hover:bg-red-50' 
              : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-600/20'
            }`}
          >
            {isActive ? (
              <>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                <span>Stop Protection</span>
              </>
            ) : (
              <>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                <span>Start Protection</span>
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

