          </div>
        </div>

        <div className="flex flex-col space-y-6">
          <div className={`flex-1 p-8 rounded-3xl border-2 transition-all duration-500 flex flex-col items-center justify-center text-center space-y-6 shadow-sm ${
            threatLevel === 'High' ? 'bg-red-50 border-red-200' : 'bg-slate-50 border-slate-100'
