          };
          onAnalysisComplete(`[VIDEO: ${videoFile.name}]`, mappedResult);
          setVideoFile(null);
          setPreviewFrame(null);
        } else if (urlInput.trim()) {
          const result = await analyzeUrlWithSearch(urlInput);
          onAnalysisComplete(urlInput, result);
          setUrlInput('');
        }
      }
