        )}

        <button
          onClick={handleAnalyze}
          disabled={loading || (activeType !== IntakeType.Media && !input.trim()) || (activeType === IntakeType.Media && !videoFile && !urlInput.trim())}
          className="w-full py-5 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 text-white rounded-2xl font-black text-xl shadow-lg shadow-blue-600/20 active:scale-[0.98] transition-all flex items-center justify-center space-x-3"
        >
