/**
 * Masks sensitive identifiers showing only the first and last few characters.
 * Example: "9876543210@ybl" -> "9876****@ybl" or "98****bl"
 */
export const maskValue = (value: string, type: 'UPI' | 'PHONE' | 'BANK' | 'URL' | 'WALLET' | 'NAME' = 'UPI'): string => {
  if (!value || value.length < 6) return value;

  if (type === 'URL') return value; // URLs are generally kept for verification unless they contain tokens

  if (type === 'UPI' && value.includes('@')) {
    const [user, domain] = value.split('@');
    const maskedUser = user.length > 4 
      ? `${user.substring(0, 3)}****${user.substring(user.length - 2)}` 
      : `${user[0]}****${user[user.length - 1]}`;
    return `${maskedUser}@${domain}`;
  }

  const startLen = value.length > 10 ? 4 : 2;
  const endLen = value.length > 10 ? 4 : 2;

  return `${value.substring(0, startLen)}****${value.substring(value.length - endLen)}`;
};

