          <div className="text-[10px] text-white truncate font-bold">{item.value}</div>
          <div className="w-full bg-slate-900 h-0.5 mt-1">
            <div className="bg-blue-600 h-full" style={{ width: `${item.conf}%` }}></div>
          </div>
        </div>
      ))}
    </div>
