    message: string;
    details: string;
    isEngaging?: boolean;
  } | null>(null);

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis) => {
    const logId = Math.random().toString(36).substr(2, 9);
    const newLog: IntelligenceLog = {
      ...analysis,
      id: logId,
      originalMessage: message,
      timestamp: Date.now(),
      messages: analysis.isScam && analysis.threatLevel !== 'Low' ? [{
        role: 'scammer',
        content: message.startsWith('[VIDEO') ? "Visual forensic identification successful." : message,
        timestamp: Date.now()
      }] : []
    };

    setLogs(prev => [newLog, ...prev]);
    setLatestAnalysis({ message, analysis });

    // Global Safety Alert update
    if (analysis.threatLevel !== 'Low') {
      setActiveAlert({
        level: analysis.threatLevel as 'Medium' | 'High' | 'Critical',
        message: analysis.safetyAlert,
        details: analysis.channel === 'video' ? "Media forensics active. Identifying source subject..." : "Autonomous honeypot active. Engaging source...",
