export function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { analyzeMessage, analyzeVideoFrame, analyzeUrlWithSearch } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
}

enum IntakeType {
  Message = 'MESSAGE',
  Transcript = 'TRANSCRIPT',
  Media = 'MEDIA'
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete }) => {
  const [activeType, setActiveType] = useState<IntakeType>(IntakeType.Message);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [videoSrc, setVideoSrc] = useState<string | null>(null);
  const [previewFrame, setPreviewFrame] = useState<string | null>(null);
  const [urlInput, setUrlInput] = useState('');
  const [urlError, setUrlError] = useState<string | null>(null);

  const videoPreviewRef = useRef<HTMLVideoElement>(null);

  // Clean up object URL when component unmounts or video changes
  useEffect(() => {
    return () => {
      if (videoSrc && videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc);
    };
  }, [videoSrc]);

  const isVideoUrl = (url: string) => {
    const videoExtensions = ['.mp4', '.webm', '.ogg', '.mov'];
    const lowerUrl = url.toLowerCase();
    return videoExtensions.some(ext => lowerUrl.includes(ext)) || 
           lowerUrl.includes('youtube.com') || 
           lowerUrl.includes('youtu.be') || 
           lowerUrl.includes('vimeo.com');
  };

  const isDirectVideoLink = (url: string) => {
    const videoExtensions = ['.mp4', '.webm', '.ogg', '.mov'];
    const lowerUrl = url.toLowerCase();
    return videoExtensions.some(ext => lowerUrl.endsWith(ext) || lowerUrl.includes(ext + '?'));
  };

  const validateUrl = (url: string) => {
    const pattern = new RegExp('^(https?:\\/\\/)?'+ // protocol
      '((([a-z\\d]([a-z\\d-]*[a-z\\d])*)\\.)+[a-z]{2,}|'+ // domain name
      '((\\d{1,3}\\.){3}\\d{1,3}))'+ // OR ip (v4) address
      '(\\:\\d+)?(\\/[-a-z\\d%_.~+]*)*'+ // port and path
      '(\\?[;&a-z\\d%_.~+=-]*)?'+ // query string
      '(\\#[-a-z\\d_]*)?$','i'); // fragment locator
    return !!pattern.test(url);
  };

  // When URL input changes, check if it's a direct video and try to preview it
  useEffect(() => {
    if (urlInput && validateUrl(urlInput) && isDirectVideoLink(urlInput)) {
      setVideoSrc(urlInput);
      setVideoFile(null); // URL takes priority over local file if both somehow exist
    }
  }, [urlInput]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    if (file) {
      if (videoSrc && videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc);
      const newSrc = URL.createObjectURL(file);
      setVideoSrc(newSrc);
      setVideoFile(file);
      setUrlInput(''); // File takes priority
      try {
        const frame = await extractFrameFromVideo(file);
        setPreviewFrame(frame);
      } catch (err) {
        console.error("Frame extraction failed", err);
      }
    }
  };

  const extractFrameFromVideo = (file: File | string): Promise<string> => {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.src = typeof file === 'string' ? file : URL.createObjectURL(file);
      video.muted = true;
      video.setAttribute('crossOrigin', 'anonymous');
      video.onloadeddata = () => { video.currentTime = Math.min(0.5, video.duration / 2); };
      video.onseeked = () => {
        try {
          const canvas = document.createElement('canvas');
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(video, 0, 0);
          const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
          if (typeof file !== 'string') URL.revokeObjectURL(video.src);
          resolve(base64);
        } catch (e) {
          reject(e); // Likely CORS issue for URL video
        }
      };
      video.onerror = (e) => reject(e);
      video.load();
    });
  };

  const handleAnalyze = async () => {
    setUrlError(null);
    const isUrl = activeType === IntakeType.Media && urlInput.trim().length > 0;

    if (isUrl && !validateUrl(urlInput)) {
      setUrlError("Please enter a valid URL (e.g., https://example.com)");
      return;
    }

    setLoading(true);
    try {
      if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
        if (!input.trim()) return;
        const result = await analyzeMessage(input);
        onAnalysisComplete(input, result);
        setInput('');
      } else {
        // Media Analysis Flow
        const isVideoContent = videoFile || (urlInput && isVideoUrl(urlInput));

        // Attempt Visual Forensics if we have a frame (either from file or direct link)
        let visualAnalysis: any = null;
        let currentFrame = previewFrame;

        // If it's a direct URL and we don't have a frame yet, try to get one
        if (!currentFrame && urlInput && isDirectVideoLink(urlInput)) {
          try {
            currentFrame = await extractFrameFromVideo(urlInput);
          } catch (e) {
            console.debug("Visual frame capture skipped (CORS/Format restrictions)");
          }
        }

        if (currentFrame) {
          visualAnalysis = await analyzeVideoFrame(currentFrame);
        }

        if (visualAnalysis) {
          const mappedResult: ScamAnalysis = {
            isScam: visualAnalysis.isFraudulent,
            confidence: visualAnalysis.anomalyScore / 100,
            scamType: visualAnalysis.isFraudulent ? "Video/Deepfake Identification" : "Legitimate Media",
            channel: 'video',
            threatLevel: visualAnalysis.isFraudulent ? 'High' : 'Low',
            summary: visualAnalysis.forensicNotes,
            safetyAlert: visualAnalysis.isFraudulent 
              ? "⚠️ High-risk visual fraud detected. Abnormalities found in textures/metadata." 
              : "Media appears safe. No immediate deepfake markers found.",
            extractedInfo: { upiIds: [], bankDetails: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
            fingerprint: { primaryHandle: visualAnalysis.subjectIdentification || 'Unknown Subject', primaryPhone: '', primaryLink: urlInput || '', category: 'Visual Fraud' },
            recommendedActions: visualAnalysis.detectedThreats,
            suggestedBaitResponse: ""
          };
          onAnalysisComplete(urlInput || `[VIDEO: ${videoFile?.name}]`, mappedResult);
        } else if (urlInput.trim()) {
          // Fallback or Primary Network Analysis for URL
          const result = await analyzeUrlWithSearch(urlInput, !!isVideoContent);
          onAnalysisComplete(urlInput, result);
        }

        // Reset state
        setVideoFile(null);
        setPreviewFrame(null);
        setVideoSrc(null);
        setUrlInput('');
      }
    } catch (error) {
      console.error("Analysis failed", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden">
      <div className="flex border-b border-slate-100 bg-slate-50/50">
        <TabButton 
          active={activeType === IntakeType.Message} 
          onClick={() => setActiveType(IntakeType.Message)} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z" /></svg>}
          label="Text / SMS" 
        />
        <TabButton 
          active={activeType === IntakeType.Transcript} 
          onClick={() => setActiveType(IntakeType.Transcript)} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" /></svg>}
          label="Voice Forensic" 
        />
        <TabButton 
          active={activeType === IntakeType.Media} 
          onClick={() => setActiveType(IntakeType.Media)} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>}
          label="Media / URL" 
        />
      </div>

      <div className="p-8 space-y-6">
        {activeType === IntakeType.Media ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="relative group">
              <input 
                type="file" 
                accept="video/*" 
                onChange={handleFileChange} 
                className={`absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20 ${videoSrc ? 'hidden' : 'block'}`} 
              />
              <div className={`h-64 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all overflow-hidden ${videoSrc ? 'bg-blue-50 border-blue-400' : 'bg-slate-50 border-slate-200 group-hover:bg-slate-100'}`}>
                {videoSrc ? (
                  <div className="relative w-full h-full flex flex-col">
                    <video 
                      ref={videoPreviewRef}
                      src={videoSrc} 
                      className="w-full h-full object-contain bg-black" 
                      controls
                    />
                    <button 
                      onClick={() => { setVideoFile(null); setVideoSrc(null); setPreviewFrame(null); setUrlInput(''); }}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 text-white rounded-full hover:bg-black/80 transition-all z-30 shadow-lg"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                    <div className="absolute top-2 left-2 pointer-events-none">
                      <div className="bg-blue-600/90 px-3 py-1 rounded-full text-[9px] font-black text-white uppercase tracking-widest shadow-sm border border-white/20">Forensic Preview</div>
                    </div>
                  </div>
                ) : (
                  <>
                    <div className="p-3 bg-white rounded-xl shadow-sm mb-3 text-slate-400 border border-slate-100">
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                    </div>
                    <p className="text-sm font-bold text-slate-700">Scan Media File</p>
                    <p className="text-[10px] text-slate-400 uppercase tracking-widest">Drag & drop or click to upload</p>
                  </>
                )}
              </div>
            </div>
            <div className="flex flex-col justify-center space-y-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Web Intelligence Scan</label>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="Paste URL (Social, YouTube, or direct link)..." 
                    value={urlInput}
                    onChange={(e) => { setUrlInput(e.target.value); setUrlError(null); }}
                    className={`w-full p-4 bg-slate-50 border ${urlError ? 'border-red-400' : 'border-slate-200'} rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium`}
                  />
                  {urlError && <p className="text-[10px] text-red-500 mt-1 font-bold">{urlError}</p>}
                </div>
              </div>
              <p className="text-[11px] text-slate-500 leading-snug font-medium italic">
                {urlInput && isVideoUrl(urlInput) 
                  ? "✓ Video platform detected. Initiating deepfake source verification." 
                  : "AI will map domain reputation and cross-check global threat databases."}
              </p>
            </div>
          </div>
        ) : (
          <textarea
            className="w-full h-48 p-6 bg-slate-50 border border-slate-200 rounded-2xl text-slate-700 placeholder-slate-400 focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none text-lg font-medium shadow-inner"
            placeholder={activeType === IntakeType.Message ? "Paste suspicious message or email body..." : "Paste call transcript text..."}
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />
        )}

        <button
          onClick={handleAnalyze}
          disabled={loading || (activeType !== IntakeType.Media && !input.trim()) || (activeType === IntakeType.Media && !videoSrc && !urlInput.trim())}
          className="w-full py-5 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-100 disabled:text-slate-300 text-white rounded-2xl font-black text-xl shadow-xl shadow-blue-600/30 active:scale-[0.98] transition-all flex items-center justify-center space-x-3"
        >
          {loading ? (
            <>
              <div className="w-5 h-5 border-3 border-white/30 border-t-white rounded-full animate-spin"></div>
              <span>Analyzing Potential Threats...</span>
            </>
          ) : (
            <>
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
              <span>Initiate Cyber Rakshak Scan</span>
            </>
          )}
        </button>
      </div>
    </div>
  );
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex flex-col md:flex-row items-center justify-center py-5 px-4 space-y-1 md:space-y-0 md:space-x-3 transition-all border-b-4 ${active ? 'border-blue-600 text-blue-600 bg-white' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
