const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Simulated Threat Intelligence Feed
const THREAT_FEED: ThreatMatch[] = [
  { indicator: "9876543210@ybl", type: 'UPI', source: 'CERT-In Bulletin', severity: 'Critical' },
  { indicator: "http://claim-your-prize-now.in", type: 'URL', source: 'Bank Fraud List', severity: 'High' },
