        links: { type: Type.ARRAY, items: EXTRACTED_ITEM_SCHEMA(Type.STRING) },
        cryptoWallets: { type: Type.ARRAY, items: EXTRACTED_ITEM_SCHEMA(Type.STRING) },
        fakeIdentities: { type: Type.ARRAY, items: EXTRACTED_ITEM_SCHEMA(Type.STRING) }
      },
      required: ["upiIds", "bankDetails", "phoneNumbers", "links", "cryptoWallets", "fakeIdentities"]
    },
    fingerprint: {
      type: Type.OBJECT,
      properties: {
        primaryHandle: { type: Type.STRING },
        primaryPhone: { type: Type.STRING },
        primaryLink: { type: Type.STRING },
        category: { type: Type.STRING }
      },
      required: ["primaryHandle", "primaryPhone", "primaryLink", "category"]
    },
    recommendedActions: { type: Type.ARRAY, items: { type: Type.STRING } },
    suggestedBaitResponse: { type: Type.STRING }
  },
  required: ["isScam", "confidence", "scamType", "channel", "threatLevel", "summary", "safetyAlert", "extractedInfo", "fingerprint", "recommendedActions", "suggestedBaitResponse"]
};

const MISSION_DIRECTIVE = `You are Bharat Cyber Rakshak AI — an autonomous cyber-fraud defense system.

THREAT INTELLIGENCE CROSS-CHECK:
Access real-time Threat Feed: ${JSON.stringify(THREAT_FEED)}.
If matches found, prioritize Critical/High threat level.

USER PROTECTION PROTOCOL:
Generate safety alerts in simple language for non-technical citizens.
Reassure the user that the system is currently engaging and mapping the source.

MEDIA INTELLIGENCE:
When analyzing URLs, check if the content relates to:
1. Deepfake videos of politicians or celebrities.
2. Lottery scams hosted on video platforms.
3. Fake "Digital Arrest" notices.
Use Search grounding to verify the reputation of the URL source and any viral scam reports related to it.`;

export const analyzeMessage = async (message: string): Promise<ScamAnalysis> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `INTAKE: Analyze input for markers. Check against Threat Feed. 
Input: "${message}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: SCAM_ANALYSIS_SCHEMA,
      systemInstruction: MISSION_DIRECTIVE
    },
  });

  const analysis = JSON.parse(response.text);

  // Local threat feed matching for redundancy
  const matches = THREAT_FEED.filter(tf => message.toLowerCase().includes(tf.indicator.toLowerCase()));
  if (matches.length > 0) {
    analysis.threatLevel = 'Critical';
    analysis.threatMatches = matches;
    analysis.safetyAlert = `⚠️ KNOWN THREAT DETECTED. ${analysis.safetyAlert}`;
  }

  return analysis;
};

