    return videoExtensions.some(ext => lowerUrl.endsWith(ext) || lowerUrl.includes(ext + '?'));
  };

  const validateUrl = (url: string) => {
    const pattern = new RegExp('^(https?:\\/\\/)?'+ // protocol
      '((([a-z\\d]([a-z\\d-]*[a-z\\d])*)\\.)+[a-z]{2,}|'+ // domain name
      '((\\d{1,3}\\.){3}\\d{1,3}))'+ // OR ip (v4) address
      '(\\:\\d+)?(\\/[-a-z\\d%_.~+]*)*'+ // port and path
      '(\\?[;&a-z\\d%_.~+=-]*)?'+ // query string
      '(\\#[-a-z\\d_]*)?$','i'); // fragment locator
    return !!pattern.test(url);
  };

  // Real-time Debounce Effect for Text Inputs
  useEffect(() => {
    if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
      if (input.trim().length > 10) {
        if (debounceTimerRef.current) window.clearTimeout(debounceTimerRef.current);
        setIsLive(true);
        debounceTimerRef.current = window.setTimeout(() => {
          handleAnalyze();
        }, 800);
      }
    }
  }, [input]);

  // Real-time Debounce Effect for URL
  useEffect(() => {
    if (urlInput && validateUrl(urlInput)) {
      if (debounceTimerRef.current) window.clearTimeout(debounceTimerRef.current);
      setIsLive(true);
      debounceTimerRef.current = window.setTimeout(() => {
        handleAnalyze();
      }, 800);

      if (isDirectVideoLink(urlInput)) {
        setVideoSrc(urlInput);
        setVideoFile(null);
      }
    }
  }, [urlInput]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    if (!file) return;

    if (activeType === IntakeType.Media) {
      if (videoSrc && videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc);
      const newSrc = URL.createObjectURL(file);
      setVideoSrc(newSrc);
      setVideoFile(file);
      setUrlInput('');
      try {
        const frame = await extractFrameFromVideo(file);
        setPreviewFrame(frame);
        // Immediate Trigger for Video Analysis
        handleAnalyzeWithData({ videoFile: file, previewFrame: frame });
      } catch (err) {
        console.error("Frame extraction failed", err);
      }
    } else if (activeType === IntakeType.Audio) {
      if (audioSrc && audioSrc.startsWith('blob:')) URL.revokeObjectURL(audioSrc);
      const newSrc = URL.createObjectURL(file);
      setAudioSrc(newSrc);
      setAudioFile(file);
      // Immediate Trigger for Audio Analysis
      handleAnalyzeWithData({ audioFile: file });
    }
  };

  const extractFrameFromVideo = (file: File | string): Promise<string> => {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.src = typeof file === 'string' ? file : URL.createObjectURL(file);
      video.muted = true;
      video.setAttribute('crossOrigin', 'anonymous');
      video.onloadeddata = () => { video.currentTime = Math.min(0.5, video.duration / 2); };
      video.onseeked = () => {
        try {
          const canvas = document.createElement('canvas');
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(video, 0, 0);
          const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
          if (typeof file !== 'string') URL.revokeObjectURL(video.src);
          resolve(base64);
        } catch (e) {
          reject(e);
        }
      };
      video.onerror = (e) => reject(e);
      video.load();
    });
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const url = URL.createObjectURL(audioBlob);
        const file = new File([audioBlob], "recorded_audio.webm", { type: 'audio/webm' });
        setAudioSrc(url);
        setAudioFile(file);
        stream.getTracks().forEach(t => t.stop());
        // Immediate Trigger for Recorded Audio
        handleAnalyzeWithData({ audioFile: file });
      };

      mediaRecorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    } catch (err) {
      console.error("Microphone access denied", err);
      alert("Microphone access is required for recording.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const blobToBase64 = (file: File | Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        const base64String = (reader.result as string).split(',')[1];
        resolve(base64String);
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  // Internal Analyze function that supports passed data overrides for immediate file triggers
  const handleAnalyzeWithData = async (overrides: { 
    videoFile?: File, 
    previewFrame?: string, 
    audioFile?: File 
  } = {}) => {
    const currentVideoFile = overrides.videoFile || videoFile;
    const currentPreviewFrame = overrides.previewFrame || previewFrame;
    const currentAudioFile = overrides.audioFile || audioFile;

    setLoading(true);
    setIsLive(true);
    try {
      if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
        if (!input.trim()) return;
        const result = await analyzeMessage(input);
        onAnalysisComplete(input, result);
      } else if (activeType === IntakeType.Audio) {
        if (!currentAudioFile) return;
        const base64 = await blobToBase64(currentAudioFile);
        const result = await analyzeAudio(base64, currentAudioFile.type || 'audio/webm');
        onAnalysisComplete(`[AUDIO_FORENSICS: ${currentAudioFile.name}]`, result);
      } else {
        const isVideoContent = currentVideoFile || (urlInput && isVideoUrl(urlInput));
        let visualAnalysis: any = null;
        let currentFrame = currentPreviewFrame;

        if (!currentFrame && urlInput && isDirectVideoLink(urlInput)) {
          try {
            currentFrame = await extractFrameFromVideo(urlInput);
          } catch (e) {
            console.debug("Visual frame capture skipped (CORS/Format restrictions)");
          }
        }

        if (currentFrame) {
          visualAnalysis = await analyzeVideoFrame(currentFrame);
        }

        if (visualAnalysis) {
          const mappedResult: ScamAnalysis = {
            isScam: visualAnalysis.isFraudulent,
            confidence: visualAnalysis.anomalyScore / 100,
            scamType: visualAnalysis.isFraudulent ? "Video/Deepfake Identification" : "Legitimate Media",
            channel: 'video',
            threatLevel: visualAnalysis.isFraudulent ? 'High' : 'Low',
            summary: visualAnalysis.forensicNotes,
            safetyAlert: visualAnalysis.isFraudulent 
              ? "⚠️ High-risk visual fraud detected. Abnormalities found in textures/metadata." 
              : "Media appears safe. No immediate deepfake markers found.",
            extractedInfo: { upiIds: [], bankDetails: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
            fingerprint: { primaryHandle: visualAnalysis.subjectIdentification || 'Unknown Subject', primaryPhone: '', primaryLink: urlInput || '', category: 'Visual Fraud' },
            recommendedActions: visualAnalysis.detectedThreats,
            suggestedBaitResponse: ""
          };
          onAnalysisComplete(urlInput || `[VIDEO: ${currentVideoFile?.name}]`, mappedResult);
        } else if (urlInput.trim()) {
          if (validateUrl(urlInput)) {
            const result = await analyzeUrlWithSearch(urlInput, !!isVideoContent);
            onAnalysisComplete(urlInput, result);
          }
        }
      }
    } catch (error) {
      console.error("Analysis failed", error);
    } finally {
      setLoading(false);
      setIsLive(false);
    }
  };

  const handleAnalyze = () => handleAnalyzeWithData();

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden relative">
      {/* Live Indicator */}
      {isLive && (
        <div className="absolute top-4 right-4 flex items-center space-x-2 z-[10] animate-in fade-in duration-300">
          <div className="w-2 h-2 bg-blue-600 rounded-full animate-pulse shadow-[0_0_8px_blue]" />
          <span className="text-[10px] font-black uppercase text-blue-600 tracking-widest">Live Auto-Scan Active</span>
        </div>
      )}

      <div className="flex border-b border-slate-100 bg-slate-50/50 overflow-x-auto no-scrollbar">
        <TabButton 
          active={activeType === IntakeType.Message} 
          onClick={() => { setActiveType(IntakeType.Message); setInput(''); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z" /></svg>}
          label="Text" 
        />
        <TabButton 
          active={activeType === IntakeType.Transcript} 
          onClick={() => { setActiveType(IntakeType.Transcript); setInput(''); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" /></svg>}
          label="Voice Forensic" 
        />
        <TabButton 
          active={activeType === IntakeType.Media} 
          onClick={() => setActiveType(IntakeType.Media)} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>}
          label="Media / URL" 
        />
        <TabButton 
          active={activeType === IntakeType.Audio} 
          onClick={() => setActiveType(IntakeType.Audio)} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19V6l12 7-12 6z" /></svg>}
          label="Audio Scan" 
        />
      </div>

      <div className="p-8 space-y-6">
        {activeType === IntakeType.Message || activeType === IntakeType.Transcript ? (
          <div className="relative group">
            <textarea
              className="w-full h-48 p-6 bg-slate-50 border border-slate-200 rounded-2xl text-slate-700 placeholder-slate-400 focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none text-lg font-medium shadow-inner"
              placeholder={activeType === IntakeType.Message ? "Paste suspicious message or email body..." : "Paste call transcript text..."}
              value={input}
              onChange={(e) => setInput(e.target.value)}
            />
            {input.length > 0 && !loading && (
              <div className="absolute bottom-4 right-4 text-[9px] font-bold text-slate-400 uppercase tracking-tighter">AI will scan as you type</div>
            )}
          </div>
        ) : activeType === IntakeType.Audio ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="flex flex-col space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Live Recording</label>
              <div className={`flex-1 h-32 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all ${isRecording ? 'bg-red-50 border-red-400' : 'bg-slate-50 border-slate-200'}`}>
                {isRecording ? (
                  <div className="flex flex-col items-center space-y-2">
                    <div className="flex items-center space-x-2">
                      <div className="w-3 h-3 bg-red-600 rounded-full animate-ping" />
                      <span className="text-lg font-black font-mono text-red-600">{formatTime(recordingTime)}</span>
                    </div>
                    <button onClick={stopRecording} className="px-4 py-2 bg-red-600 text-white rounded-lg text-xs font-bold uppercase tracking-widest">Stop Recording</button>
                  </div>
                ) : (
                  <button onClick={startRecording} className="flex flex-col items-center space-y-2 text-slate-400 hover:text-blue-600 transition-colors">
                    <div className="p-3 bg-white rounded-xl shadow-sm border border-slate-100">
                       <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" /></svg>
                    </div>
                    <span className="text-xs font-bold">Record Voice Sample</span>
                  </button>
                )}
              </div>
            </div>
            <div className="flex flex-col space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Audio File Upload</label>
              <div className="relative group flex-1 h-32">
                <input type="file" accept="audio/*" onChange={handleFileChange} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" />
                <div className={`h-full border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all ${audioSrc ? 'bg-blue-50 border-blue-400' : 'bg-slate-50 border-slate-200 group-hover:bg-slate-100'}`}>
                   {audioSrc ? (
                     <div className="p-4 flex flex-col items-center space-y-2 w-full">
                        <audio src={audioSrc} controls className="w-full h-8" />
                        <span className="text-[10px] font-bold text-blue-600 truncate max-w-full px-4">{audioFile?.name}</span>
                     </div>
                   ) : (
                     <>
                        <div className="p-3 bg-white rounded-xl shadow-sm mb-2 text-slate-400 border border-slate-100">
                          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19V6l12 7-12 6z" /></svg>
                        </div>
                        <p className="text-xs font-bold text-slate-700">Upload Sample</p>
                     </>
                   )}
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="relative group">
              <input 
                type="file" 
                accept="video/*" 
                onChange={handleFileChange} 
                className={`absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20 ${videoSrc ? 'hidden' : 'block'}`} 
              />
              <div className={`h-64 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all overflow-hidden ${videoSrc ? 'bg-blue-50 border-blue-400' : 'bg-slate-50 border-slate-200 group-hover:bg-slate-100'}`}>
                {videoSrc ? (
                  <div className="relative w-full h-full flex flex-col">
                    <video 
                      ref={videoPreviewRef}
                      src={videoSrc} 
                      className="w-full h-full object-contain bg-black" 
                      controls
                    />
                    <button 
                      onClick={() => { setVideoFile(null); setVideoSrc(null); setPreviewFrame(null); setUrlInput(''); }}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 text-white rounded-full hover:bg-black/80 transition-all z-30 shadow-lg"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                    <div className="absolute top-2 left-2 pointer-events-none">
                      <div className="bg-blue-600/90 px-3 py-1 rounded-full text-[9px] font-black text-white uppercase tracking-widest shadow-sm border border-white/20">Forensic Preview</div>
                    </div>
                  </div>
                ) : (
                  <>
                    <div className="p-3 bg-white rounded-xl shadow-sm mb-3 text-slate-400 border border-slate-100">
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                    </div>
                    <p className="text-sm font-bold text-slate-700">Scan Media File</p>
                    <p className="text-[10px] text-slate-400 uppercase tracking-widest">Drag & drop or click to upload</p>
                  </>
                )}
              </div>
            </div>
            <div className="flex flex-col justify-center space-y-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Web Intelligence Scan</label>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="Paste URL (Social, YouTube, or direct link)..." 
                    value={urlInput}
                    onChange={(e) => { setUrlInput(e.target.value); setUrlError(null); }}
                    className={`w-full p-4 bg-slate-50 border ${urlError ? 'border-red-400' : 'border-slate-200'} rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium`}
                  />
                  {urlError && <p className="text-[10px] text-red-500 mt-1 font-bold">{urlError}</p>}
                </div>
              </div>
              <p className="text-[11px] text-slate-500 leading-snug font-medium italic">
                {urlInput && isVideoUrl(urlInput) 
                  ? "✓ Video platform detected. Initiating deepfake source verification." 
                  : "AI will map domain reputation and cross-check global threat databases."}
              </p>
            </div>
          </div>
        )}

        <div className="w-full flex flex-col space-y-2">
          <button
            onClick={handleAnalyze}
            disabled={loading || isRecording || (activeType === IntakeType.Audio && !audioFile) || (activeType !== IntakeType.Media && activeType !== IntakeType.Audio && !input.trim()) || (activeType === IntakeType.Media && !videoSrc && !urlInput.trim())}
            className={`w-full py-5 rounded-2xl font-black text-xl shadow-xl transition-all flex items-center justify-center space-x-3 ${
              loading 
              ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
              : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-600/30 active:scale-[0.98]'
            }`}
          >
            {loading ? (
              <>
                <div className="w-5 h-5 border-3 border-slate-400/30 border-t-slate-400 rounded-full animate-spin"></div>
                <span className="uppercase tracking-widest text-xs">AI Forensic synthesis in progress...</span>
              </>
            ) : (
              <>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                <span>Re-Analyze Vector</span>
              </>
            )}
          </button>
          {!loading && (activeType === IntakeType.Message || activeType === IntakeType.Transcript || urlInput) && (
            <p className="text-center text-[9px] font-bold text-slate-400 uppercase tracking-widest animate-pulse">Analysis completes automatically when you stop typing</p>
          )}
        </div>
      </div>
    </div>
  );
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex flex-col md:flex-row items-center justify-center py-5 px-4 space-y-1 md:space-y-0 md:space-x-3 transition-all border-b-4 ${active ? 'border-blue-600 text-blue-600 bg-white' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
  >
    <div className={`p-2 rounded-lg transition-colors ${active ? 'bg-blue-50' : 'bg-transparent'}`}>{icon}</div>
    <span className="font-bold text-xs md:text-sm tracking-tight whitespace-nowrap">{label}</span>
  </button>
);

export default ScamAnalyzer;

import React, { useState, useEffect, useRef } from 'react';
import { analyzeMessage, analyzeVideoFrame, analyzeUrlWithSearch, analyzeAudio } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
}

enum IntakeType {
  Message = 'MESSAGE',
  Transcript = 'TRANSCRIPT',
  Media = 'MEDIA',
  Audio = 'AUDIO'
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete }) => {
  const [activeType, setActiveType] = useState<IntakeType>(IntakeType.Message);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isLive, setIsLive] = useState(false);

  // Video State
  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [videoSrc, setVideoSrc] = useState<string | null>(null);
  const [previewFrame, setPreviewFrame] = useState<string | null>(null);
  const videoPreviewRef = useRef<HTMLVideoElement>(null);

  // Audio State
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [audioSrc, setAudioSrc] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  // URL State
  const [urlInput, setUrlInput] = useState('');
  const [urlError, setUrlError] = useState<string | null>(null);

  // Debounce Ref
  const debounceTimerRef = useRef<number | null>(null);

  // Clean up object URLs
  useEffect(() => {
    return () => {
      if (videoSrc && videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc);
      if (audioSrc && audioSrc.startsWith('blob:')) URL.revokeObjectURL(audioSrc);
    };
  }, [videoSrc, audioSrc]);

  const isVideoUrl = (url: string) => {
    const videoExtensions = ['.mp4', '.webm', '.ogg', '.mov'];
    const lowerUrl = url.toLowerCase();
    return videoExtensions.some(ext => lowerUrl.includes(ext)) || 
           lowerUrl.includes('youtube.com') || 
           lowerUrl.includes('youtu.be') || 
           lowerUrl.includes('vimeo.com');
  };

  const isDirectVideoLink = (url: string) => {
    const videoExtensions = ['.mp4', '.webm', '.ogg', '.mov'];
    const lowerUrl = url.toLowerCase();
    return videoExtensions.some(ext => lowerUrl.endsWith(ext) || lowerUrl.includes(ext + '?'));
  };

  const validateUrl = (url: string) => {
    const pattern = new RegExp('^(https?:\\/\\/)?'+ // protocol
      '((([a-z\\d]([a-z\\d-]*[a-z\\d])*)\\.)+[a-z]{2,}|'+ // domain name
      '((\\d{1,3}\\.){3}\\d{1,3}))'+ // OR ip (v4) address
      '(\\:\\d+)?(\\/[-a-z\\d%_.~+]*)*'+ // port and path
      '(\\?[;&a-z\\d%_.~+=-]*)?'+ // query string
      '(\\#[-a-z\\d_]*)?$','i'); // fragment locator
    return !!pattern.test(url);
  };

  // Real-time Debounce Effect for Text Inputs
  useEffect(() => {
    if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
      if (input.trim().length > 10) {
        if (debounceTimerRef.current) window.clearTimeout(debounceTimerRef.current);
        setIsLive(true);
        debounceTimerRef.current = window.setTimeout(() => {
          handleAnalyze();
        }, 800);
      }
    }
  }, [input]);

  // Real-time Debounce Effect for URL
  useEffect(() => {
    if (urlInput && validateUrl(urlInput)) {
      if (debounceTimerRef.current) window.clearTimeout(debounceTimerRef.current);
      setIsLive(true);
      debounceTimerRef.current = window.setTimeout(() => {
        handleAnalyze();
      }, 800);

      if (isDirectVideoLink(urlInput)) {
        setVideoSrc(urlInput);
        setVideoFile(null);
      }
    }
  }, [urlInput]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    if (!file) return;

    if (activeType === IntakeType.Media) {
      if (videoSrc && videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc);
      const newSrc = URL.createObjectURL(file);
      setVideoSrc(newSrc);
      setVideoFile(file);
      setUrlInput('');
      try {
        const frame = await extractFrameFromVideo(file);
        setPreviewFrame(frame);
        handleAnalyzeWithData({ videoFile: file, previewFrame: frame });
      } catch (err) {
        console.error("Frame extraction failed", err);
      }
    } else if (activeType === IntakeType.Audio) {
      if (audioSrc && audioSrc.startsWith('blob:')) URL.revokeObjectURL(audioSrc);
      const newSrc = URL.createObjectURL(file);
      setAudioSrc(newSrc);
      setAudioFile(file);
      handleAnalyzeWithData({ audioFile: file });
    }
  };

  const extractFrameFromVideo = (file: File | string): Promise<string> => {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.src = typeof file === 'string' ? file : URL.createObjectURL(file);
      video.muted = true;
      video.setAttribute('crossOrigin', 'anonymous');
      video.onloadeddata = () => { video.currentTime = Math.min(0.5, video.duration / 2); };
      video.onseeked = () => {
        try {
          const canvas = document.createElement('canvas');
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(video, 0, 0);
          const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
          if (typeof file !== 'string') URL.revokeObjectURL(video.src);
          resolve(base64);
        } catch (e) {
          reject(e);
        }
      };
      video.onerror = (e) => reject(e);
      video.load();
    });
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const url = URL.createObjectURL(audioBlob);
        const file = new File([audioBlob], "recorded_audio.webm", { type: 'audio/webm' });
        setAudioSrc(url);
        setAudioFile(file);
        stream.getTracks().forEach(t => t.stop());
        handleAnalyzeWithData({ audioFile: file });
      };

      mediaRecorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    } catch (err) {
      console.error("Microphone access denied", err);
      alert("Microphone access is required for recording.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const blobToBase64 = (file: File | Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        const base64String = (reader.result as string).split(',')[1];
        resolve(base64String);
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const handleAnalyzeWithData = async (overrides: { 
    videoFile?: File, 
    previewFrame?: string, 
    audioFile?: File 
  } = {}) => {
    const currentVideoFile = overrides.videoFile || videoFile;
    const currentPreviewFrame = overrides.previewFrame || previewFrame;
    const currentAudioFile = overrides.audioFile || audioFile;

    setLoading(true);
    setIsLive(true);
    try {
      if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
        if (!input.trim()) return;
        const result = await analyzeMessage(input);
        onAnalysisComplete(input, result);
      } else if (activeType === IntakeType.Audio) {
        if (!currentAudioFile) return;
        const base64 = await blobToBase64(currentAudioFile);
        const result = await analyzeAudio(base64, currentAudioFile.type || 'audio/webm');
        onAnalysisComplete(`[AUDIO_FORENSICS: ${currentAudioFile.name}]`, result);
      } else {
        const isVideoContent = currentVideoFile || (urlInput && isVideoUrl(urlInput));
        let visualAnalysis: any = null;
        let currentFrame = currentPreviewFrame;

        if (!currentFrame && urlInput && isDirectVideoLink(urlInput)) {
          try {
            currentFrame = await extractFrameFromVideo(urlInput);
          } catch (e) {
            console.debug("Visual frame capture skipped (CORS/Format restrictions)");
          }
        }

        if (currentFrame) {
          visualAnalysis = await analyzeVideoFrame(currentFrame);
        }

        if (visualAnalysis) {
          const mappedResult: ScamAnalysis = {
            isScam: visualAnalysis.isFraudulent,
            confidence: visualAnalysis.anomalyScore / 100,
            scamType: visualAnalysis.isFraudulent ? "Video/Deepfake Identification" : "Legitimate Media",
            channel: 'video',
            threatLevel: visualAnalysis.isFraudulent ? 'High' : 'Low',
            summary: visualAnalysis.forensicNotes,
            safetyAlert: visualAnalysis.isFraudulent 
              ? "⚠️ High-risk visual fraud detected. Abnormalities found in textures/metadata." 
              : "Media appears safe. No immediate deepfake markers found.",
            extractedInfo: { upiIds: [], bankDetails: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
            fingerprint: { primaryHandle: visualAnalysis.subjectIdentification || 'Unknown Subject', primaryPhone: '', primaryLink: urlInput || '', category: 'Visual Fraud' },
            recommendedActions: visualAnalysis.detectedThreats,
            suggestedBaitResponse: ""
          };
          onAnalysisComplete(urlInput || `[VIDEO: ${currentVideoFile?.name}]`, mappedResult);
        } else if (urlInput.trim()) {
          if (validateUrl(urlInput)) {
            const result = await analyzeUrlWithSearch(urlInput, !!isVideoContent);
            onAnalysisComplete(urlInput, result);
          }
        }
      }
    } catch (error) {
      console.error("Analysis failed", error);
    } finally {
      setLoading(false);
      setIsLive(false);
    }
  };

  const handleAnalyze = () => handleAnalyzeWithData();

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden relative">
      {/* Live Indicator */}
      {isLive && (
        <div className="absolute top-4 right-4 flex items-center space-x-2 z-[10] animate-in fade-in duration-300">
          <div className="w-2 h-2 bg-blue-600 rounded-full animate-pulse shadow-[0_0_8px_blue]" />
          <span className="text-[10px] font-black uppercase text-blue-600 tracking-widest">Live Auto-Scan Active</span>
        </div>
      )}

      <div className="flex border-b border-slate-100 bg-slate-50/50 overflow-x-auto no-scrollbar">
        <TabButton 
          active={activeType === IntakeType.Message} 
          onClick={() => { setActiveType(IntakeType.Message); setInput(''); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z" /></svg>}
          label="Text" 
        />
        <TabButton 
          active={activeType === IntakeType.Transcript} 
          onClick={() => { setActiveType(IntakeType.Transcript); setInput(''); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" /></svg>}
          label="Voice Forensic" 
        />
        <TabButton 
          active={activeType === IntakeType.Media} 
          onClick={() => setActiveType(IntakeType.Media)} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>}
          label="Media / URL" 
        />
        <TabButton 
          active={activeType === IntakeType.Audio} 
          onClick={() => setActiveType(IntakeType.Audio)} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>}
          label="Audio Scan" 
        />
      </div>

      <div className="p-8 space-y-6">
        {activeType === IntakeType.Message || activeType === IntakeType.Transcript ? (
          <div className="relative group">
            <textarea
              className="w-full h-48 p-6 bg-slate-50 border border-slate-200 rounded-2xl text-slate-700 placeholder-slate-400 focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none text-lg font-medium shadow-inner"
              placeholder={activeType === IntakeType.Message ? "Paste suspicious message or email body..." : "Paste call transcript text..."}
              value={input}
              onChange={(e) => setInput(e.target.value)}
            />
            {input.length > 0 && !loading && (
              <div className="absolute bottom-4 right-4 text-[9px] font-bold text-slate-400 uppercase tracking-tighter">AI will scan as you type</div>
            )}
          </div>
        ) : activeType === IntakeType.Audio ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="flex flex-col space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Live Forensic Recording</label>
              <div className={`flex-1 h-32 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all relative overflow-hidden ${isRecording ? 'bg-red-50 border-red-400' : 'bg-slate-50 border-slate-200'}`}>
                {isRecording && (
                   <div className="absolute inset-x-0 bottom-0 h-1 bg-red-100">
                      <div className="h-full bg-red-500 animate-[shimmer_2s_infinite] origin-left"></div>
                   </div>
                )}
                {isRecording ? (
                  <div className="flex flex-col items-center space-y-3">
                    <div className="flex items-center space-x-3">
                      <div className="flex space-x-1 items-center h-4">
                         {[1,2,3,4,5].map(i => (
                           <div key={i} className="w-1 bg-red-600 rounded-full animate-[bounce_0.6s_infinite]" style={{ height: `${Math.random() * 100}%`, animationDelay: `${i * 0.1}s` }}></div>
                         ))}
                      </div>
                      <span className="text-xl font-black font-mono text-red-600">{formatTime(recordingTime)}</span>
                    </div>
                    <button onClick={stopRecording} className="px-6 py-2 bg-red-600 hover:bg-red-700 text-white rounded-full text-xs font-black uppercase tracking-widest shadow-lg shadow-red-600/20 transition-all active:scale-95">Stop & Analyze</button>
                  </div>
                ) : (
                  <button onClick={startRecording} className="flex flex-col items-center space-y-2 text-slate-400 hover:text-blue-600 transition-all group">
                    <div className="p-4 bg-white rounded-2xl shadow-sm border border-slate-100 group-hover:scale-110 transition-transform">
                       <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" /></svg>
                    </div>
                    <span className="text-xs font-black uppercase tracking-widest">Start Voice Intercept</span>
                  </button>
                )}
              </div>
            </div>
            <div className="flex flex-col space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Call Recording Upload</label>
              <div className="relative group flex-1 h-32">
                <input type="file" accept="audio/*" onChange={handleFileChange} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" />
                <div className={`h-full border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all ${audioSrc ? 'bg-blue-50 border-blue-400' : 'bg-slate-50 border-slate-200 group-hover:bg-slate-100'}`}>
                   {audioSrc ? (
                     <div className="p-4 flex flex-col items-center space-y-3 w-full">
                        <audio src={audioSrc} controls className="w-full h-10 custom-audio-player" />
                        <div className="flex items-center space-x-2">
                           <svg className="w-3 h-3 text-blue-600" fill="currentColor" viewBox="0 0 20 20"><path d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" /></svg>
                           <span className="text-[10px] font-black text-blue-600 truncate max-w-[150px] uppercase tracking-tighter">{audioFile?.name}</span>
                        </div>
                     </div>
                   ) : (
                     <>
                        <div className="p-3 bg-white rounded-xl shadow-sm mb-2 text-slate-400 border border-slate-100">
                          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                        </div>
                        <p className="text-xs font-black uppercase text-slate-500 tracking-widest">Select Audio Log</p>
                     </>
                   )}
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="relative group">
              <input 
                type="file" 
                accept="video/*" 
                onChange={handleFileChange} 
                className={`absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20 ${videoSrc ? 'hidden' : 'block'}`} 
              />
              <div className={`h-64 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all overflow-hidden ${videoSrc ? 'bg-blue-50 border-blue-400' : 'bg-slate-50 border-slate-200 group-hover:bg-slate-100'}`}>
                {videoSrc ? (
                  <div className="relative w-full h-full flex flex-col">
                    <video 
                      ref={videoPreviewRef}
                      src={videoSrc} 
                      className="w-full h-full object-contain bg-black" 
                      controls
                    />
                    <button 
                      onClick={() => { setVideoFile(null); setVideoSrc(null); setPreviewFrame(null); setUrlInput(''); }}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 text-white rounded-full hover:bg-black/80 transition-all z-30 shadow-lg"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                    <div className="absolute top-2 left-2 pointer-events-none">
                      <div className="bg-blue-600/90 px-3 py-1 rounded-full text-[9px] font-black text-white uppercase tracking-widest shadow-sm border border-white/20">Forensic Preview</div>
                    </div>
                  </div>
                ) : (
                  <>
                    <div className="p-3 bg-white rounded-xl shadow-sm mb-3 text-slate-400 border border-slate-100">
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                    </div>
                    <p className="text-sm font-bold text-slate-700">Scan Media File</p>
                    <p className="text-[10px] text-slate-400 uppercase tracking-widest">Drag & drop or click to upload</p>
                  </>
                )}
              </div>
            </div>
            <div className="flex flex-col justify-center space-y-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Web Intelligence Scan</label>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="Paste URL (Social, YouTube, or direct link)..." 
                    value={urlInput}
                    onChange={(e) => { setUrlInput(e.target.value); setUrlError(null); }}
                    className={`w-full p-4 bg-slate-50 border ${urlError ? 'border-red-400' : 'border-slate-200'} rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all font-medium`}
                  />
                  {urlError && <p className="text-[10px] text-red-500 mt-1 font-bold">{urlError}</p>}
                </div>
              </div>
              <p className="text-[11px] text-slate-500 leading-snug font-medium italic">
                {urlInput && isVideoUrl(urlInput) 
                  ? "✓ Video platform detected. Initiating deepfake source verification." 
                  : "AI will map domain reputation and cross-check global threat databases."}
              </p>
            </div>
          </div>
        )}

        <div className="w-full flex flex-col space-y-2">
          <button
            onClick={handleAnalyze}
            disabled={loading || isRecording || (activeType === IntakeType.Audio && !audioFile) || (activeType !== IntakeType.Media && activeType !== IntakeType.Audio && !input.trim()) || (activeType === IntakeType.Media && !videoSrc && !urlInput.trim())}
            className={`w-full py-5 rounded-2xl font-black text-xl shadow-xl transition-all flex items-center justify-center space-x-3 ${
              loading 
              ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
              : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-600/30 active:scale-[0.98]'
            }`}
          >
            {loading ? (
              <>
                <div className="w-5 h-5 border-3 border-slate-400/30 border-t-slate-400 rounded-full animate-spin"></div>
                <span className="uppercase tracking-widest text-xs">AI Forensic synthesis in progress...</span>
              </>
            ) : (
              <>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                <span>Re-Analyze Vector</span>
              </>
            )}
          </button>
          {!loading && !isRecording && (activeType === IntakeType.Message || activeType === IntakeType.Transcript || urlInput) && (
            <p className="text-center text-[9px] font-bold text-slate-400 uppercase tracking-widest animate-pulse">Analysis completes automatically when you stop typing</p>
          )}
        </div>
      </div>
    </div>
  );
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex flex-col md:flex-row items-center justify-center py-5 px-4 space-y-1 md:space-y-0 md:space-x-3 transition-all border-b-4 ${active ? 'border-blue-600 text-blue-600 bg-white' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
  >
    <div className={`p-2 rounded-lg transition-colors ${active ? 'bg-blue-50' : 'bg-transparent'}`}>{icon}</div>
    <span className="font-bold text-xs md:text-sm tracking-tight whitespace-nowrap uppercase tracking-tighter">{label}</span>
  </button>
);

export default ScamAnalyzer;

import React, { useState, useEffect, useRef } from 'react';
import { analyzeMessage, analyzeVideoFrame, analyzeUrlWithSearch, analyzeAudio } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
}

enum IntakeType {
  Message = 'MESSAGE',
  Transcript = 'TRANSCRIPT',
  Media = 'MEDIA',
  Audio = 'AUDIO'
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete }) => {
  const [activeType, setActiveType] = useState<IntakeType>(IntakeType.Message);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isLive, setIsLive] = useState(false);

  // Video State
  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [videoSrc, setVideoSrc] = useState<string | null>(null);
  const [previewFrame, setPreviewFrame] = useState<string | null>(null);
  const videoPreviewRef = useRef<HTMLVideoElement>(null);

  // Audio State
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [audioSrc, setAudioSrc] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  // URL State
  const [urlInput, setUrlInput] = useState('');
  const [urlError, setUrlError] = useState<string | null>(null);

  // Debounce Ref
  const debounceTimerRef = useRef<number | null>(null);

  // Clean up object URLs
  useEffect(() => {
    return () => {
      if (videoSrc && videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc);
      if (audioSrc && audioSrc.startsWith('blob:')) URL.revokeObjectURL(audioSrc);
    };
  }, [videoSrc, audioSrc]);

  const isVideoUrl = (url: string) => {
    const videoExtensions = ['.mp4', '.webm', '.ogg', '.mov'];
    const lowerUrl = url.toLowerCase();
    return videoExtensions.some(ext => lowerUrl.includes(ext)) || 
           lowerUrl.includes('youtube.com') || 
           lowerUrl.includes('youtu.be') || 
           lowerUrl.includes('vimeo.com');
  };

  const isDirectVideoLink = (url: string) => {
    const videoExtensions = ['.mp4', '.webm', '.ogg', '.mov'];
    const lowerUrl = url.toLowerCase();
    return videoExtensions.some(ext => lowerUrl.endsWith(ext) || lowerUrl.includes(ext + '?'));
  };

  const validateUrl = (url: string) => {
    if (!url) return false;
    // Enhanced URL Regex for more robust validation
    const pattern = new RegExp(
      '^' +
      '(?:(?:https?|ftp):\\/\\/)?' + // protocol
      '(?:\\S+(?::\\S*)?@)?' + // user:pass authentication
      '(?:' +
        '(?!(?:10|127)(?:\\.\\d{1,3}){3})' +
        '(?!(?:169\\.254|192\\.168)(?:\\.\\d{1,3}){2})' +
        '(?!172\\.(?:1[6-9]|2\\d|3[0-1])(?:\\.\\d{1,3}){2})' +
        '(?:[1-9]\\d?|1\\d\\d|2[01]\\d|22[0-3])' +
        '(?:\\.(?:1?\\d{1,2}|2[0-4]\\d|25[0-5])){2}' +
        '(?:\\.(?:[1-9]\\d?|1\\d\\d|2[0-4]\\d|25[0-4]))' +
      '|' +
        '(?:(?:[a-z\\u00a1-\\uffff0-9]-*)*[a-z\\u00a1-\\uffff0-9]+)' +
        '(?:\\.(?:[a-z\\u00a1-\\uffff0-9]-*)*[a-z\\u00a1-\\uffff0-9]+)*' +
        '(?:\\.(?:[a-z\\u00a1-\\uffff]{2,}))' +
      ')' +
      '(?::\\d{2,5})?' + // port
      '(?:[/?#]\\S*)?' + // path
      '$', 'i'
    );
    return !!pattern.test(url);
  };

  // Real-time Debounce Effect for Text Inputs
  useEffect(() => {
    if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
      if (input.trim().length > 10) {
        if (debounceTimerRef.current) window.clearTimeout(debounceTimerRef.current);
        setIsLive(true);
        debounceTimerRef.current = window.setTimeout(() => {
          handleAnalyze();
        }, 800);
      }
    }
  }, [input]);

  // Real-time Debounce Effect for URL
  useEffect(() => {
    if (urlInput) {
      if (debounceTimerRef.current) window.clearTimeout(debounceTimerRef.current);

      const isValid = validateUrl(urlInput);

      if (isValid) {
        setUrlError(null);
        setIsLive(true);
        debounceTimerRef.current = window.setTimeout(() => {
          handleAnalyze();
        }, 800);

        if (isDirectVideoLink(urlInput)) {
          setVideoSrc(urlInput);
          setVideoFile(null);
        }
      } else if (urlInput.length > 8) {
        // Only show error if they've typed a significant amount
        setUrlError("Please enter a complete and valid URL (e.g., https://example.com)");
        setIsLive(false);
      }
    } else {
      setUrlError(null);
      setIsLive(false);
    }
  }, [urlInput]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    if (!file) return;

    if (activeType === IntakeType.Media) {
      if (videoSrc && videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc);
      const newSrc = URL.createObjectURL(file);
      setVideoSrc(newSrc);
      setVideoFile(file);
      setUrlInput('');
      setUrlError(null);
      try {
        const frame = await extractFrameFromVideo(file);
        setPreviewFrame(frame);
        handleAnalyzeWithData({ videoFile: file, previewFrame: frame });
      } catch (err) {
        console.error("Frame extraction failed", err);
      }
    } else if (activeType === IntakeType.Audio) {
      if (audioSrc && audioSrc.startsWith('blob:')) URL.revokeObjectURL(audioSrc);
      const newSrc = URL.createObjectURL(file);
      setAudioSrc(newSrc);
      setAudioFile(file);
      handleAnalyzeWithData({ audioFile: file });
    }
  };

  const extractFrameFromVideo = (file: File | string): Promise<string> => {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.src = typeof file === 'string' ? file : URL.createObjectURL(file);
      video.muted = true;
      video.setAttribute('crossOrigin', 'anonymous');
      video.onloadeddata = () => { video.currentTime = Math.min(0.5, video.duration / 2); };
      video.onseeked = () => {
        try {
          const canvas = document.createElement('canvas');
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(video, 0, 0);
          const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
          if (typeof file !== 'string') URL.revokeObjectURL(video.src);
          resolve(base64);
        } catch (e) {
          reject(e);
        }
      };
      video.onerror = (e) => reject(e);
      video.load();
    });
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const url = URL.createObjectURL(audioBlob);
        const file = new File([audioBlob], "recorded_audio.webm", { type: 'audio/webm' });
        setAudioSrc(url);
        setAudioFile(file);
        stream.getTracks().forEach(t => t.stop());
        handleAnalyzeWithData({ audioFile: file });
      };

      mediaRecorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    } catch (err) {
      console.error("Microphone access denied", err);
      alert("Microphone access is required for recording.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const blobToBase64 = (file: File | Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => {
        const base64String = (reader.result as string).split(',')[1];
        resolve(base64String);
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const handleAnalyzeWithData = async (overrides: { 
    videoFile?: File, 
    previewFrame?: string, 
    audioFile?: File 
  } = {}) => {
    const currentVideoFile = overrides.videoFile || videoFile;
    const currentPreviewFrame = overrides.previewFrame || previewFrame;
    const currentAudioFile = overrides.audioFile || audioFile;

    setLoading(true);
    setIsLive(true);
    try {
      if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
        if (!input.trim()) return;
        const result = await analyzeMessage(input);
        onAnalysisComplete(input, result);
      } else if (activeType === IntakeType.Audio) {
        if (!currentAudioFile) return;
        const base64 = await blobToBase64(currentAudioFile);
        const result = await analyzeAudio(base64, currentAudioFile.type || 'audio/webm');
        onAnalysisComplete(`[AUDIO_FORENSICS: ${currentAudioFile.name}]`, result);
      } else {
        const isVideoContent = currentVideoFile || (urlInput && isVideoUrl(urlInput));
        let visualAnalysis: any = null;
        let currentFrame = currentPreviewFrame;

        if (urlInput.trim() && !validateUrl(urlInput)) {
          setUrlError("Invalid URL format. Please correct it to proceed.");
          setLoading(false);
          setIsLive(false);
          return;
        }

        if (!currentFrame && urlInput && isDirectVideoLink(urlInput)) {
          try {
            currentFrame = await extractFrameFromVideo(urlInput);
          } catch (e) {
            console.debug("Visual frame capture skipped (CORS/Format restrictions)");
          }
        }

        if (currentFrame) {
          visualAnalysis = await analyzeVideoFrame(currentFrame);
        }

        if (visualAnalysis) {
          const mappedResult: ScamAnalysis = {
            isScam: visualAnalysis.isFraudulent,
            confidence: visualAnalysis.anomalyScore / 100,
            scamType: visualAnalysis.isFraudulent ? "Video/Deepfake Identification" : "Legitimate Media",
            channel: 'video',
            threatLevel: visualAnalysis.isFraudulent ? 'High' : 'Low',
            summary: visualAnalysis.forensicNotes,
            safetyAlert: visualAnalysis.isFraudulent 
              ? "⚠️ High-risk visual fraud detected. Abnormalities found in textures/metadata." 
              : "Media appears safe. No immediate deepfake markers found.",
            extractedInfo: { upiIds: [], bankDetails: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
            fingerprint: { primaryHandle: visualAnalysis.subjectIdentification || 'Unknown Subject', primaryPhone: '', primaryLink: urlInput || '', category: 'Visual Fraud' },
            recommendedActions: visualAnalysis.detectedThreats,
            suggestedBaitResponse: ""
          };
          onAnalysisComplete(urlInput || `[VIDEO: ${currentVideoFile?.name}]`, mappedResult);
        } else if (urlInput.trim()) {
          const result = await analyzeUrlWithSearch(urlInput, !!isVideoContent);
          onAnalysisComplete(urlInput, result);
        }
      }
    } catch (error) {
      console.error("Analysis failed", error);
    } finally {
      setLoading(false);
      setIsLive(false);
    }
  };

  const handleAnalyze = () => handleAnalyzeWithData();

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden relative">
      {/* Live Indicator */}
      {isLive && (
        <div className="absolute top-4 right-4 flex items-center space-x-2 z-[10] animate-in fade-in duration-300">
          <div className="w-2 h-2 bg-blue-600 rounded-full animate-pulse shadow-[0_0_8px_blue]" />
          <span className="text-[10px] font-black uppercase text-blue-600 tracking-widest">Live Auto-Scan Active</span>
        </div>
      )}

      <div className="flex border-b border-slate-100 bg-slate-50/50 overflow-x-auto no-scrollbar">
        <TabButton 
          active={activeType === IntakeType.Message} 
          onClick={() => { setActiveType(IntakeType.Message); setInput(''); setUrlError(null); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z" /></svg>}
          label="Text" 
        />
        <TabButton 
          active={activeType === IntakeType.Transcript} 
          onClick={() => { setActiveType(IntakeType.Transcript); setInput(''); setUrlError(null); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" /></svg>}
          label="Voice Forensic" 
        />
        <TabButton 
          active={activeType === IntakeType.Media} 
          onClick={() => { setActiveType(IntakeType.Media); setUrlError(null); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>}
          label="Media / URL" 
        />
        <TabButton 
          active={activeType === IntakeType.Audio} 
          onClick={() => { setActiveType(IntakeType.Audio); setUrlError(null); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>}
          label="Audio Scan" 
        />
      </div>

      <div className="p-8 space-y-6">
        {activeType === IntakeType.Message || activeType === IntakeType.Transcript ? (
          <div className="relative group">
            <textarea
              className="w-full h-48 p-6 bg-slate-50 border border-slate-200 rounded-2xl text-slate-700 placeholder-slate-400 focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none text-lg font-medium shadow-inner"
              placeholder={activeType === IntakeType.Message ? "Paste suspicious message or email body..." : "Paste call transcript text..."}
              value={input}
              onChange={(e) => setInput(e.target.value)}
            />
            {input.length > 0 && !loading && (
              <div className="absolute bottom-4 right-4 text-[9px] font-bold text-slate-400 uppercase tracking-tighter">AI will scan as you type</div>
            )}
          </div>
        ) : activeType === IntakeType.Audio ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="flex flex-col space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Live Forensic Recording</label>
              <div className={`flex-1 h-32 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all relative overflow-hidden ${isRecording ? 'bg-red-50 border-red-400' : 'bg-slate-50 border-slate-200'}`}>
                {isRecording && (
                   <div className="absolute inset-x-0 bottom-0 h-1 bg-red-100">
                      <div className="h-full bg-red-500 animate-[shimmer_2s_infinite] origin-left"></div>
                   </div>
                )}
                {isRecording ? (
                  <div className="flex flex-col items-center space-y-3">
                    <div className="flex items-center space-x-3">
                      <div className="flex space-x-1 items-center h-4">
                         {[1,2,3,4,5].map(i => (
                           <div key={i} className="w-1 bg-red-600 rounded-full animate-[bounce_0.6s_infinite]" style={{ height: `${Math.random() * 100}%`, animationDelay: `${i * 0.1}s` }}></div>
                         ))}
                      </div>
                      <span className="text-xl font-black font-mono text-red-600">{formatTime(recordingTime)}</span>
                    </div>
                    <button onClick={stopRecording} className="px-6 py-2 bg-red-600 hover:bg-red-700 text-white rounded-full text-xs font-black uppercase tracking-widest shadow-lg shadow-red-600/20 transition-all active:scale-95">Stop & Analyze</button>
                  </div>
                ) : (
                  <button onClick={startRecording} className="flex flex-col items-center space-y-2 text-slate-400 hover:text-blue-600 transition-all group">
                    <div className="p-4 bg-white rounded-2xl shadow-sm border border-slate-100 group-hover:scale-110 transition-transform">
                       <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" /></svg>
                    </div>
                    <span className="text-xs font-black uppercase tracking-widest">Start Voice Intercept</span>
                  </button>
                )}
              </div>
            </div>
            <div className="flex flex-col space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Call Recording Upload</label>
              <div className="relative group flex-1 h-32">
                <input type="file" accept="audio/*" onChange={handleFileChange} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" />
                <div className={`h-full border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all ${audioSrc ? 'bg-blue-50 border-blue-400' : 'bg-slate-50 border-slate-200 group-hover:bg-slate-100'}`}>
                   {audioSrc ? (
                     <div className="p-4 flex flex-col items-center space-y-3 w-full">
                        <audio src={audioSrc} controls className="w-full h-10 custom-audio-player" />
                        <div className="flex items-center space-x-2">
                           <svg className="w-3 h-3 text-blue-600" fill="currentColor" viewBox="0 0 20 20"><path d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" /></svg>
                           <span className="text-[10px] font-black text-blue-600 truncate max-w-[150px] uppercase tracking-tighter">{audioFile?.name}</span>
                        </div>
                     </div>
                   ) : (
                     <>
                        <div className="p-3 bg-white rounded-xl shadow-sm mb-2 text-slate-400 border border-slate-100">
                          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                        </div>
                        <p className="text-xs font-black uppercase text-slate-500 tracking-widest">Select Audio Log</p>
                     </>
                   )}
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="relative group">
              <input 
                type="file" 
                accept="video/*" 
                onChange={handleFileChange} 
                className={`absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20 ${videoSrc ? 'hidden' : 'block'}`} 
              />
              <div className={`h-64 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all overflow-hidden ${videoSrc ? 'bg-blue-50 border-blue-400' : 'bg-slate-50 border-slate-200 group-hover:bg-slate-100'}`}>
                {videoSrc ? (
                  <div className="relative w-full h-full flex flex-col">
                    <video 
                      ref={videoPreviewRef}
                      src={videoSrc} 
                      className="w-full h-full object-contain bg-black" 
                      controls
                    />
                    <button 
                      onClick={() => { setVideoFile(null); setVideoSrc(null); setPreviewFrame(null); setUrlInput(''); setUrlError(null); }}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 text-white rounded-full hover:bg-black/80 transition-all z-30 shadow-lg"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                    <div className="absolute top-2 left-2 pointer-events-none">
                      <div className="bg-blue-600/90 px-3 py-1 rounded-full text-[9px] font-black text-white uppercase tracking-widest shadow-sm border border-white/20">Forensic Preview</div>
                    </div>
                  </div>
                ) : (
                  <>
                    <div className="p-3 bg-white rounded-xl shadow-sm mb-3 text-slate-400 border border-slate-100">
                      <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                    </div>
                    <p className="text-sm font-bold text-slate-700">Scan Media File</p>
                    <p className="text-[10px] text-slate-400 uppercase tracking-widest">Drag & drop or click to upload</p>
                  </>
                )}
              </div>
            </div>
            <div className="flex flex-col justify-center space-y-4">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Web Intelligence Scan</label>
                <div className="relative">
                  <input 
                    type="text" 
                    placeholder="Paste URL (Social, YouTube, or direct link)..." 
                    value={urlInput}
                    onChange={(e) => { setUrlInput(e.target.value); }}
                    className={`w-full p-4 bg-slate-50 border ${urlError ? 'border-red-400 focus:ring-red-500' : 'border-slate-200 focus:ring-blue-500'} rounded-xl text-sm outline-none transition-all font-medium`}
                  />
                  {urlError && (
                    <div className="mt-2 flex items-center space-x-1 animate-in slide-in-from-top-1 duration-200">
                      <svg className="w-3 h-3 text-red-500" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" /></svg>
                      <p className="text-[10px] text-red-500 font-bold uppercase tracking-tight">{urlError}</p>
                    </div>
                  )}
                </div>
              </div>
              <p className="text-[11px] text-slate-500 leading-snug font-medium italic">
                {urlInput && isVideoUrl(urlInput) 
                  ? "✓ Video platform detected. Initiating deepfake source verification." 
                  : "AI will map domain reputation and cross-check global threat databases."}
              </p>
            </div>
          </div>
        )}

        <div className="w-full flex flex-col space-y-2">
          <button
            onClick={handleAnalyze}
            disabled={loading || isRecording || (activeType === IntakeType.Audio && !audioFile) || (activeType !== IntakeType.Media && activeType !== IntakeType.Audio && !input.trim()) || (activeType === IntakeType.Media && !videoSrc && !urlInput.trim()) || (!!urlError && activeType === IntakeType.Media)}
            className={`w-full py-5 rounded-2xl font-black text-xl shadow-xl transition-all flex items-center justify-center space-x-3 ${
              loading 
              ? 'bg-slate-100 text-slate-400 cursor-not-allowed' 
              : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-600/30 active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed'
            }`}
          >
            {loading ? (
              <>
                <div className="w-5 h-5 border-3 border-slate-400/30 border-t-slate-400 rounded-full animate-spin"></div>
                <span className="uppercase tracking-widest text-xs">AI Forensic synthesis in progress...</span>
              </>
            ) : (
              <>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                <span>Re-Analyze Vector</span>
              </>
            )}
          </button>
          {!loading && !isRecording && (activeType === IntakeType.Message || activeType === IntakeType.Transcript || (urlInput && !urlError)) && (
            <p className="text-center text-[9px] font-bold text-slate-400 uppercase tracking-widest animate-pulse">Analysis completes automatically when you stop typing</p>
          )}
        </div>
      </div>
    </div>
  );
};

const TabButton = ({ active, onClick, icon, label }: { active: boolean, onClick: () => void, icon: React.ReactNode, label: string }) => (
  <button 
    onClick={onClick}
    className={`flex-1 flex flex-col md:flex-row items-center justify-center py-5 px-4 space-y-1 md:space-y-0 md:space-x-3 transition-all border-b-4 ${active ? 'border-blue-600 text-blue-600 bg-white' : 'border-transparent text-slate-400 hover:text-slate-600'}`}
  >
    <div className={`p-2 rounded-lg transition-colors ${active ? 'bg-blue-50' : 'bg-transparent'}`}>{icon}</div>
    <span className="font-bold text-xs md:text-sm tracking-tight whitespace-nowrap uppercase tracking-tighter">{label}</span>
  </button>
);

export default ScamAnalyzer;

import React, { useState, useRef } from 'react';
import { ScamAnalysis } from '../types';
import { maskValue } from '../utils/masking';
import { generateAudioFromText, decodeBase64, decodeAudioData } from '../services/geminiService';

interface Props {
  analysis: ScamAnalysis;
  onClose: () => void;
}

const ResultPanel: React.FC<Props> = ({ analysis, onClose }) => {
  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const isHighRisk = analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical';
  const isMedRisk = analysis.threatLevel === 'Medium';

  const riskColor = isHighRisk ? 'text-red-600 bg-red-50' : isMedRisk ? 'text-orange-600 bg-orange-50' : 'text-green-600 bg-green-50';
  const riskBorder = isHighRisk ? 'border-red-200' : isMedRisk ? 'border-orange-200' : 'border-green-200';
  const riskLabel = isHighRisk ? 'High Risk Scam' : isMedRisk ? 'Suspicious / Caution' : 'Safe / Low Risk';

  const stopAudio = () => {
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.stop();
      } catch (e) {
        // Source might already be stopped
      }
      currentSourceRef.current = null;
    }
    setIsSpeaking(false);
  };

  const handlePlayBriefing = async () => {
    if (isSpeaking) {
