            </svg>
          </div>
          <div>
            <h3 className="text-2xl font-black uppercase tracking-tight">{riskLabel}</h3>
            <p className="text-sm font-bold opacity-80">{analysis.scamType}</p>
          </div>
        </div>
        <button onClick={onClose} className="p-2 hover:bg-black/5 rounded-full transition-all">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
        </button>
      </div>

      <div className="p-8 space-y-8">
        {/* User Safety Alert - Most Important Section */}
        <div className={`p-6 rounded-2xl border ${isHighRisk ? 'bg-red-600/5 border-red-100' : isMedRisk ? 'bg-orange-500/5 border-orange-100' : 'bg-green-500/5 border-green-100'}`}>
          <div className="flex justify-between items-start mb-3">
            <h4 className={`text-xs font-black uppercase tracking-widest flex items-center ${isHighRisk ? 'text-red-600' : isMedRisk ? 'text-orange-600' : 'text-green-600'}`}>
              <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
              Citizen Safety Briefing
