                  <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M9.383 3.076A1 1 0 0110 4v12a1 1 0 01-1.707.707L4.586 13H2a1 1 0 01-1-1V8a1 1 0 011-1h2.586l3.647-3.647a1 1 0 011.15-.277zM13.193 3.028a1 1 0 011.106.894A8.002 8.002 0 0115 10c0 1.673-.513 3.224-1.393 4.506a1 1 0 11-1.643-1.138A6.002 6.002 0 0013 10c0-1.186-.344-2.292-.934-3.226a1 1 0 011.127-1.746zM16.75 1.5a1 1 0 01.657 1.751A11.954 11.954 0 0119 10a11.954 11.954 0 01-1.593 6.749 1 1 0 11-1.713-1.038A9.954 9.954 0 0017 10c0-2.316-.788-4.445-2.112-6.136a1 1 0 011.862-1.364z" /></svg>
                  <span>Listen to Briefing</span>
