              {isHighRisk && (
                <li className="flex items-start space-x-3 text-sm text-red-400 font-bold border-t border-slate-800 pt-3">
                  <span className="w-1.5 h-1.5 rounded-full bg-red-500 mt-1.5 shrink-0 animate-pulse" />
