                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Visual Forensic Markers</h4>
                <div className="grid grid-cols-2 gap-3">
                  <ForensicMarker label="Lip-Sync Match" status="Forensic Pending" />
                  <ForensicMarker label="Skin Texture" status="Scanning..." />
                  <ForensicMarker label="Blink Frequency" status="Scanning..." />
                  <ForensicMarker label="Metadata Integrity" status="Compromised" />
                </div>
              </section>
            )}

            <section>
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3">AI Intelligence Summary</h4>
              <p className="text-slate-600 text-sm leading-relaxed font-medium">{analysis.summary}</p>
            </section>

            <section>
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-3">Recovered Forensic Data</h4>
              <div className="flex flex-wrap gap-2">
                {analysis.extractedInfo.upiIds.length > 0 && analysis.extractedInfo.upiIds.map((u, i) => (
                  <div key={i} className="px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-[10px] font-bold text-slate-600 font-mono">UPI: {maskValue(u.value, 'UPI')}</div>
                ))}
                {analysis.extractedInfo.links.length > 0 && analysis.extractedInfo.links.map((l, i) => (
                  <div key={i} className="px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-[10px] font-bold text-slate-600 font-mono">URL: {maskValue(l.value, 'URL')}</div>
                ))}
                {analysis.extractedInfo.phoneNumbers.length > 0 && analysis.extractedInfo.phoneNumbers.map((p, i) => (
                  <div key={i} className="px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-xl text-[10px] font-bold text-slate-600 font-mono">PHN: {maskValue(p.value, 'PHONE')}</div>
                ))}
              </div>
            </section>
          </div>

          <div className="bg-slate-900 text-white p-6 rounded-3xl border border-slate-800 space-y-5 shadow-inner">
            <h4 className="text-sm font-black flex items-center uppercase tracking-tight text-blue-400">
              <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              Immediate Protection Plan
            </h4>
            <ul className="space-y-3">
              {analysis.recommendedActions.map((action, i) => (
                <li key={i} className="flex items-start space-x-3 text-sm text-slate-300 font-medium">
                  <span className="w-1.5 h-1.5 rounded-full bg-blue-500 mt-1.5 shrink-0" />
                  <span>{action}</span>
                </li>
              ))}
            </ul>
            <div className="pt-4">
              <a href="https://www.cybercrime.gov.in" target="_blank" rel="noopener noreferrer" className="block w-full py-4 bg-blue-600 text-white text-center rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-blue-700 transition-all shadow-lg shadow-blue-900/40">
                Report to Authorities →
              </a>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const ForensicMarker = ({ label, status }: { label: string, status: string }) => (
  <div className="bg-white p-2 rounded-lg border border-slate-200 flex flex-col">
    <span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">{label}</span>
    <span className={`text-[10px] font-bold ${status === 'Natural' || status === 'Normal' || status === 'None' || status === 'Low Prob' ? 'text-green-600' : 'text-red-600'}`}>{status}</span>
  </div>
);

export default ResultPanel;

import React, { useState, useEffect, useRef } from 'react';
import { analyzeMessage, analyzeVideoFrame, analyzeUrlWithSearch, analyzeAudio } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
  onAnalysisStart: () => void;
  onClear: () => void;
}

enum IntakeType {
  Message = 'MESSAGE',
  Transcript = 'TRANSCRIPT',
  Media = 'MEDIA',
  Audio = 'AUDIO'
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete, onAnalysisStart, onClear }) => {
  const [activeType, setActiveType] = useState<IntakeType>(IntakeType.Message);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isLive, setIsLive] = useState(false);

  // Video State
  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [videoSrc, setVideoSrc] = useState<string | null>(null);
  const [previewFrame, setPreviewFrame] = useState<string | null>(null);
  const videoPreviewRef = useRef<HTMLVideoElement>(null);

  // Audio State
  const [audioFile, setAudioFile] = useState<File | null>(null);
  const [audioSrc, setAudioSrc] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const timerRef = useRef<number | null>(null);

  // URL State
  const [urlInput, setUrlInput] = useState('');
  const [urlError, setUrlError] = useState<string | null>(null);
  const [isListeningUrl, setIsListeningUrl] = useState(false);

  // Real-time tracking to prevent race conditions
  const debounceTimerRef = useRef<number | null>(null);
  const currentRequestIdRef = useRef<number>(0);

  // Clean up object URLs
  useEffect(() => {
    return () => {
      if (videoSrc && videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc);
      if (audioSrc && audioSrc.startsWith('blob:')) URL.revokeObjectURL(audioSrc);
    };
  }, [videoSrc, audioSrc]);

  const isVideoUrl = (url: string) => {
    const videoExtensions = ['.mp4', '.webm', '.ogg', '.mov'];
    const lowerUrl = url.toLowerCase();
    return videoExtensions.some(ext => lowerUrl.includes(ext)) || 
           lowerUrl.includes('youtube.com') || 
           lowerUrl.includes('youtu.be') || 
           lowerUrl.includes('vimeo.com');
  };

  const isDirectVideoLink = (url: string) => {
    const videoExtensions = ['.mp4', '.webm', '.ogg', '.mov'];
    const lowerUrl = url.toLowerCase();
    return videoExtensions.some(ext => lowerUrl.endsWith(ext) || lowerUrl.includes(ext + '?'));
  };

  const validateUrl = (url: string) => {
    if (!url) return false;
    const pattern = new RegExp(
      '^' +
      '(?:(?:https?|ftp):\\/\\/)?' + 
      '(?:\\S+(?::\\S*)?@)?' + 
      '(?:' +
        '(?!(?:10|127)(?:\\.\\d{1,3}){3})' +
        '(?!(?:169\\.254|192\\.168)(?:\\.\\d{1,3}){2})' +
        '(?!172\\.(?:1[6-9]|2\\d|3[0-1])(?:\\.\\d{1,3}){2})' +
        '(?:[1-9]\\d?|1\\d\\d|2[01]\\d|22[0-3])' +
        '(?:\\.(?:1?\\d{1,2}|2[0-4]\\d|25[0-5])){2}' +
        '(?:\\.(?:[1-9]\\d?|1\\d\\d|2[0-4]\\d|25[0-4]))' +
      '|' +
        '(?:(?:[a-z\\u00a1-\\uffff0-9]-*)*[a-z\\u00a1-\\uffff0-9]+)' +
        '(?:\\.(?:[a-z\\u00a1-\\uffff0-9]-*)*[a-z\\u00a1-\\uffff0-9]+)*' +
        '(?:\\.(?:[a-z\\u00a1-\\uffff]{2,}))' +
      ')' +
      '(?::\\d{2,5})?' + 
      '(?:[/?#]\\S*)?' + 
      '$', 'i'
    );
    return !!pattern.test(url);
  };

  // Real-time triggers for Text
  useEffect(() => {
    if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
      if (input.trim().length > 10) {
        // Auto-switch to Media tab if it looks like a URL
        if (validateUrl(input.trim()) && isVideoUrl(input.trim())) {
          setActiveType(IntakeType.Media);
          setUrlInput(input.trim());
          setInput('');
          return;
        }

        if (debounceTimerRef.current) window.clearTimeout(debounceTimerRef.current);
        setIsLive(true);
        debounceTimerRef.current = window.setTimeout(() => {
          handleAnalyze();
        }, 800);
      } else if (input.trim().length === 0) {
        onClear();
        setIsLive(false);
      }
    }
  }, [input]);

  // Real-time triggers for URL
  useEffect(() => {
    if (urlInput) {
      if (debounceTimerRef.current) window.clearTimeout(debounceTimerRef.current);
      const isValid = validateUrl(urlInput);
      if (isValid) {
        setUrlError(null);
        setIsLive(true);
        debounceTimerRef.current = window.setTimeout(() => {
          handleAnalyze();
        }, 800);
        if (isDirectVideoLink(urlInput)) {
          setVideoSrc(urlInput);
          setVideoFile(null);
        }
      } else if (urlInput.length > 8) {
        setUrlError("Please enter a complete and valid URL (e.g., https://example.com)");
        setIsLive(false);
      }
    } else {
      setUrlError(null);
      setIsLive(false);
      onClear();
    }
  }, [urlInput]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0] || null;
    if (!file) return;

    if (activeType === IntakeType.Media) {
      if (videoSrc && videoSrc.startsWith('blob:')) URL.revokeObjectURL(videoSrc);
      const newSrc = URL.createObjectURL(file);
      setVideoSrc(newSrc);
      setVideoFile(file);
      setUrlInput('');
      setUrlError(null);
      try {
        const frame = await extractFrameFromVideo(file);
        setPreviewFrame(frame);
        handleAnalyzeWithData({ videoFile: file, previewFrame: frame });
      } catch (err) {
        console.error("Frame extraction failed", err);
      }
    } else if (activeType === IntakeType.Audio) {
      if (audioSrc && audioSrc.startsWith('blob:')) URL.revokeObjectURL(audioSrc);
      const newSrc = URL.createObjectURL(file);
      setAudioSrc(newSrc);
      setAudioFile(file);
      handleAnalyzeWithData({ audioFile: file });
    }
  };

  const extractFrameFromVideo = (file: File | string): Promise<string> => {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.src = typeof file === 'string' ? file : URL.createObjectURL(file);
      video.muted = true;
      video.setAttribute('crossOrigin', 'anonymous');
      video.onloadeddata = () => { video.currentTime = Math.min(0.5, video.duration / 2); };
      video.onseeked = () => {
        try {
          const canvas = document.createElement('canvas');
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(video, 0, 0);
          const base64 = canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
          if (typeof file !== 'string') URL.revokeObjectURL(video.src);
          resolve(base64);
        } catch (e) {
          reject(e);
        }
      };
      video.onerror = (e) => reject(e);
      video.load();
    });
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (event) => audioChunksRef.current.push(event.data);
      mediaRecorder.onstop = () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        const url = URL.createObjectURL(audioBlob);
        const file = new File([audioBlob], "recorded_audio.webm", { type: 'audio/webm' });
        setAudioSrc(url);
        setAudioFile(file);
        stream.getTracks().forEach(t => t.stop());
        handleAnalyzeWithData({ audioFile: file });
      };
      mediaRecorder.start();
      setIsRecording(true);
      setRecordingTime(0);
      timerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000);
    } catch (err) {
      console.error("Microphone access denied", err);
      alert("Microphone access is required for recording.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      if (timerRef.current) clearInterval(timerRef.current);
    }
  };

  const toggleUrlVoiceInput = () => {
    if (isListeningUrl) {
      setIsListeningUrl(false);
      return;
    }
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Voice input is not supported in this browser.");
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.lang = 'en-US';
    recognition.interimResults = false;
    recognition.onstart = () => setIsListeningUrl(true);
    recognition.onend = () => setIsListeningUrl(false);
    recognition.onerror = () => setIsListeningUrl(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      const formattedUrl = transcript.toLowerCase().replace(/\s+dot\s+/g, '.').replace(/\s+/g, '');
      setUrlInput(formattedUrl);
    };
    recognition.start();
  };

  const blobToBase64 = (file: File | Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve((reader.result as string).split(',')[1]);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  };

  const handleAnalyzeWithData = async (overrides: { 
    videoFile?: File, 
    previewFrame?: string, 
    audioFile?: File 
  } = {}) => {
    const requestId = ++currentRequestIdRef.current;
    const currentVideoFile = overrides.videoFile || videoFile;
    const currentPreviewFrame = overrides.previewFrame || previewFrame;
    const currentAudioFile = overrides.audioFile || audioFile;

    setLoading(true);
    onAnalysisStart();
    try {
      let result: ScamAnalysis;
      let identifier = "";

      if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
        if (!input.trim()) return;
        result = await analyzeMessage(input);
        identifier = input;
      } else if (activeType === IntakeType.Audio) {
        if (!currentAudioFile) return;
        const base64 = await blobToBase64(currentAudioFile);
        result = await analyzeAudio(base64, currentAudioFile.type || 'audio/webm');
        identifier = `[AUDIO_FORENSICS: ${currentAudioFile.name}]`;
      } else {
        const isVideoContent = currentVideoFile || (urlInput && isVideoUrl(urlInput));
        let currentFrame = currentPreviewFrame;

        if (urlInput.trim() && !validateUrl(urlInput)) {
          setUrlError("Invalid URL format.");
          return;
        }

        if (!currentFrame && urlInput && isDirectVideoLink(urlInput)) {
          try { currentFrame = await extractFrameFromVideo(urlInput); } catch (e) {}
        }

        if (currentFrame) {
          const visualAnalysis = await analyzeVideoFrame(currentFrame);
          result = {
            isScam: visualAnalysis.isFraudulent,
            confidence: visualAnalysis.anomalyScore / 100,
            scamType: visualAnalysis.isFraudulent ? "Video/Deepfake Identification" : "Legitimate Media",
            channel: 'video',
            threatLevel: visualAnalysis.isFraudulent ? 'High' : 'Low',
            summary: visualAnalysis.forensicNotes,
            safetyAlert: visualAnalysis.isFraudulent 
              ? "⚠️ High-risk visual fraud detected. Abnormalities found in textures/metadata." 
              : "Media appears safe. No immediate deepfake markers found.",
            extractedInfo: { upiIds: [], bankDetails: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
            fingerprint: { primaryHandle: visualAnalysis.subjectIdentification || 'Unknown Subject', primaryPhone: '', primaryLink: urlInput || '', category: 'Visual Fraud' },
            recommendedActions: visualAnalysis.detectedThreats,
            suggestedBaitResponse: ""
          };
          identifier = urlInput || `[VIDEO: ${currentVideoFile?.name}]`;
        } else if (urlInput.trim()) {
          result = await analyzeUrlWithSearch(urlInput, !!isVideoContent);
          identifier = urlInput;
        } else {
          return;
        }
      }

      // Only update if this is still the latest request
      if (requestId === currentRequestIdRef.current) {
        onAnalysisComplete(identifier, result);
      }
    } catch (error) {
      console.error("Analysis failed", error);
    } finally {
      if (requestId === currentRequestIdRef.current) {
        setLoading(false);
      }
    }
  };

  const handleAnalyze = () => handleAnalyzeWithData();

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden relative">
      {isLive && (
        <div className="absolute top-4 right-4 flex items-center space-x-2 z-[10] animate-in fade-in duration-300">
          <div className="w-2 h-2 bg-blue-600 rounded-full animate-pulse shadow-[0_0_8px_blue]" />
          <span className="text-[10px] font-black uppercase text-blue-600 tracking-widest">Live Auto-Scan Active</span>
        </div>
      )}

      <div className="flex border-b border-slate-100 bg-slate-50/50 overflow-x-auto no-scrollbar">
        <TabButton 
          active={activeType === IntakeType.Message} 
          onClick={() => { setActiveType(IntakeType.Message); setInput(''); setUrlError(null); onClear(); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 8h10M7 12h4m1 8l-4-4H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-3l-4 4z" /></svg>}
          label="Text" 
        />
        <TabButton 
          active={activeType === IntakeType.Transcript} 
          onClick={() => { setActiveType(IntakeType.Transcript); setInput(''); setUrlError(null); onClear(); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" /></svg>}
          label="Voice Forensic" 
        />
        <TabButton 
          active={activeType === IntakeType.Media} 
          onClick={() => { setActiveType(IntakeType.Media); setUrlError(null); onClear(); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>}
          label="Media / URL" 
        />
        <TabButton 
          active={activeType === IntakeType.Audio} 
          onClick={() => { setActiveType(IntakeType.Audio); setUrlError(null); onClear(); }} 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>}
          label="Audio Scan" 
        />
      </div>

      <div className="p-8 space-y-6">
        {activeType === IntakeType.Message || activeType === IntakeType.Transcript ? (
          <div className="relative group">
            <textarea
              className="w-full h-48 p-6 bg-slate-50 border border-slate-200 rounded-2xl text-slate-700 placeholder-slate-400 focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none text-lg font-medium shadow-inner"
              placeholder={activeType === IntakeType.Message ? "Paste suspicious message or email body..." : "Paste call transcript text..."}
              value={input}
              onChange={(e) => setInput(e.target.value)}
            />
            {input.length > 0 && !loading && (
              <div className="absolute bottom-4 right-4 text-[9px] font-bold text-slate-400 uppercase tracking-tighter">AI will scan as you type</div>
            )}
          </div>
        ) : activeType === IntakeType.Audio ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="flex flex-col space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Live Forensic Recording</label>
              <div className={`flex-1 h-32 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all relative overflow-hidden ${isRecording ? 'bg-red-50 border-red-400' : 'bg-slate-50 border-slate-200'}`}>
                {isRecording && (
                   <div className="absolute inset-0 flex items-center justify-center opacity-30 pointer-events-none">
                      <div className="flex items-end space-x-1 h-12">
                         {[...Array(12)].map((_, i) => (
                           <div key={i} className="w-1.5 bg-red-600 rounded-full animate-[bounce_1s_infinite]" style={{ animationDelay: `${i * 0.1}s`, height: `${20 + Math.random() * 80}%` }}></div>
                         ))}
                      </div>
                   </div>
                )}
                {isRecording ? (
                  <div className="flex flex-col items-center space-y-3 relative z-10">
                    <div className="flex items-center space-x-3 text-xl font-black font-mono text-red-600 tracking-tighter">
                       <span className="w-2 h-2 bg-red-600 rounded-full animate-ping"></span>
                       {formatTime(recordingTime)}
                    </div>
                    <button onClick={stopRecording} className="px-6 py-2 bg-red-600 hover:bg-red-700 text-white rounded-full text-xs font-black uppercase tracking-widest shadow-lg shadow-red-600/20 transition-all active:scale-95">Stop & Extract</button>
                  </div>
                ) : (
                  <button onClick={startRecording} className="flex flex-col items-center space-y-2 text-slate-400 hover:text-blue-600 transition-all group">
                    <div className="p-4 bg-white rounded-2xl shadow-sm border border-slate-100 group-hover:scale-110 transition-transform">
                       <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-20a3 3 0 00-3 3v10a3 3 0 006 0V3a3 3 0 00-3-3z" /></svg>
                    </div>
                    <span className="text-xs font-black uppercase tracking-widest">Start Voice Intercept</span>
                  </button>
                )}
              </div>
            </div>
            <div className="flex flex-col space-y-4">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Call Recording Upload</label>
              <div className="relative group flex-1 h-32">
                <input type="file" accept="audio/*" onChange={handleFileChange} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20" />
                <div className={`h-full border-2 border-dashed rounded-2xl flex flex-col items-center justify-center transition-all ${audioSrc ? 'bg-blue-50 border-blue-400' : 'bg-slate-50 border-slate-200 group-hover:bg-slate-100'}`}>
                   {audioSrc ? (
                     <div className="p-4 flex flex-col items-center space-y-3 w-full text-blue-600">
                        <audio src={audioSrc} controls className="w-full h-10" />
                        <span className="text-[10px] font-black uppercase tracking-tighter truncate max-w-xs">{audioFile?.name}</span>
                     </div>
                   ) : (
                     <>
                        <div className="p-3 bg-white rounded-xl shadow-sm mb-2 text-slate-400 border border-slate-100">
                          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
                        </div>
                        <p className="text-xs font-black uppercase text-slate-500 tracking-widest">Select Audio Log</p>
                     </>
                   )}
                </div>
              </div>
            </div>
          </div>
