export interface ExtractedItem<T> {
  value: T;
  confidence: number; // 0-100
}

export interface ExtractedInfo {
  upiIds: ExtractedItem<string>[];
  bankDetails: ExtractedItem<string>[];
  phoneNumbers: ExtractedItem<string>[];
  links: ExtractedItem<string>[];
  cryptoWallets: ExtractedItem<string>[];
  fakeIdentities: ExtractedItem<string>[];
}

export interface ThreatMatch {
  indicator: string;
  type: 'UPI' | 'URL' | 'PHONE' | 'APP';
  source: string;
  severity: 'High' | 'Critical';
}

export interface ScammerFingerprint {
  primaryHandle: string;
  primaryPhone: string;
  primaryLink: string;
  category: string;
}

export interface AudioForensics {
  voiceNaturalnessScore: number; // 0-100 (high = human, low = synthetic)
  backgroundAnomalyLevel: number; // 0-100 (detection of call center vs home)
  detectedModulation: string[];
  cloningConfidence: number;
}

export interface ScamAnalysis {
  isScam: boolean;
  confidence: number; // overall scam probability 0-1
  scamType: string;
  channel: 'text' | 'call' | 'video' | 'audio' | 'qr' | 'app' | 'social' | 'screen-share';
  threatLevel: 'Low' | 'Medium' | 'High' | 'Critical';
  summary: string;
  safetyAlert: string; // Citizen-friendly warning message
  extractedInfo: ExtractedInfo;
  fingerprint: ScammerFingerprint;
  recommendedActions: string[];
  suggestedBaitResponse: string;
  threatMatches?: ThreatMatch[];
  audioForensics?: AudioForensics;
  liveStatusUpdate?: string; // For real-time updates like "UPI Captured"
}

export interface VideoAnalysis {
  isFraudulent: boolean;
  anomalyScore: number;
  detectedThreats: string[];
  forensicNotes: string;
  subjectIdentification: string;
}

export interface ChatMessage {
  role: 'user' | 'bot' | 'scammer';
  content: string;
  timestamp: number;
}

export interface IntelligenceLog extends ScamAnalysis {
  id: string;
  originalMessage: string;
  timestamp: number;
  messages: ChatMessage[]; // Persist honeypot history
  status: 'Active' | 'Blocked' | 'Resolved';
}

export interface HoneypotSession {
  id: string;
  targetAlias: string;
  analysis: ScamAnalysis;
  messages: ChatMessage[];
  status: 'active' | 'baiting' | 'extracted';
  lastActivity: number;
}

