              <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                {/* Recovered Indicators */}
                <section>
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Extracted Indicators (Masked)</h4>
                  <div className="space-y-3">
                    {(Object.entries(selectedCase.extractedInfo) as [string, any[]][]).map(([key, items]) => {
                      if (items.length === 0) return null;
                      return items.map((item: any, idx: number) => (
                        <div key={`${key}-${idx}`} className="flex items-center justify-between p-4 bg-white border border-slate-200 rounded-2xl hover:border-blue-400 transition-all group">
                          <div className="flex flex-col">
                            <span className="text-[9px] font-black text-blue-600 uppercase tracking-widest mb-1">{key.replace(/([A-Z])/g, ' $1')}</span>
                            <span className="text-[13px] font-bold text-slate-800 font-mono tracking-tight">{maskValue(item.value, key.toUpperCase() as any)}</span>
                          </div>
                          <div className="text-right">
                             <div className="text-[10px] font-black text-slate-400 group-hover:text-blue-500 transition-colors">{item.confidence}% CONF</div>
                          </div>
                        </div>
                      ));
                    })}
                  </div>
                </section>

                {/* Protocol Execution & Export */}
                <section>
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Evidence & Export Options</h4>
                  <div className="bg-slate-50 p-6 rounded-3xl border border-slate-200 space-y-4">
                    <button onClick={() => exportToTextForensic(selectedCase)} className="w-full flex items-center justify-between p-4 bg-white border border-slate-200 rounded-2xl hover:bg-slate-50 transition-all shadow-sm">
                      <div className="flex items-center space-x-3">
                        <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                        <span className="text-xs font-black uppercase text-slate-700">Forensic Brief (TXT)</span>
                      </div>
                      <svg className="w-4 h-4 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                    </button>
                    <button onClick={() => exportToCSV(selectedCase)} className="w-full flex items-center justify-between p-4 bg-white border border-slate-200 rounded-2xl hover:bg-slate-50 transition-all shadow-sm">
                      <div className="flex items-center space-x-3">
                        <svg className="w-5 h-5 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                        <span className="text-xs font-black uppercase text-slate-700">Tabular Dataset (CSV)</span>
                      </div>
                      <svg className="w-4 h-4 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                    </button>
                    <button onClick={() => exportToJSON(selectedCase)} className="w-full flex items-center justify-between p-4 bg-white border border-slate-200 rounded-2xl hover:bg-slate-50 transition-all shadow-sm">
                      <div className="flex items-center space-x-3">
                        <svg className="w-5 h-5 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 20l4-16m4 4l4 4-4 4M6 16l-4-4 4-4" /></svg>
                        <span className="text-xs font-black uppercase text-slate-700">Raw Intel Packet (JSON)</span>
                      </div>
                      <svg className="w-4 h-4 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                    </button>
