        ) : (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-300 p-20 space-y-6">
            <div className="w-32 h-32 bg-slate-50 rounded-full border border-slate-100 flex items-center justify-center animate-pulse">
              <svg className="w-16 h-16 text-slate-200" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
