const MetricRow = ({ label, value, target, isCount }: { label: string, value: number, target: number, isCount?: boolean }) => {
  const percent = isCount ? (value / target) * 100 : value;
  return (
    <div className="space-y-2">
      <div className="flex justify-between text-[10px] font-black uppercase">
        <span className="text-slate-500">{label}</span>
        <span className="text-slate-800">{isCount ? value.toFixed(1) : `${value.toFixed(0)}%`}</span>
      </div>
      <div className="w-full h-1.5 bg-slate-50 rounded-full overflow-hidden border border-slate-100">
        <div className={`h-full ${percent >= 90 ? 'bg-green-500' : percent >= 70 ? 'bg-blue-600' : 'bg-orange-500'}`} style={{ width: `${Math.min(percent, 100)}%` }}></div>
      </div>
    </div>
  );
};

