import React, { useState, useEffect, useRef } from 'react';
import ScamAnalyzer from './components/ScamAnalyzer';
import IntelligenceDashboard from './components/IntelligenceDashboard';
import ResultPanel from './components/ResultPanel';
import LiveShield from './components/LiveShield';
import SafetyBanner from './components/SafetyBanner';
import BaitSession from './components/BaitSession';
import CaseHistory from './components/CaseHistory';
import { ScamAnalysis, IntelligenceLog, ExtractedInfo, ChatMessage } from './types';

const App: React.FC = () => {
  const [logs, setLogs] = useState<IntelligenceLog[]>([]);
  const [latestAnalysis, setLatestAnalysis] = useState<{message: string, analysis: ScamAnalysis, sessionId: string} | null>(null);
  const [view, setView] = useState<'analyzer' | 'history' | 'intelligence'>('analyzer');
  const [liveMode, setLiveMode] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [activeAlert, setActiveAlert] = useState<{
    level: 'Medium' | 'High' | 'Critical';
    message: string;
    details: string;
    isEngaging?: boolean;
  } | null>(null);

  const currentSessionIdRef = useRef<string | null>(null);

  const generateCaseId = () => {
    const year = new Date().getFullYear();
    const rand = Math.floor(1000 + Math.random() * 9000);
    return `SCAM-${year}-${rand}`;
  };

  const findLinkedCases = (analysis: ScamAnalysis, currentLogs: IntelligenceLog[]): string[] => {
    const indicators = new Set([
      ...analysis.extractedInfo.upiIds.map(i => i.value.toLowerCase()),
      ...analysis.extractedInfo.phoneNumbers.map(i => i.value.toLowerCase()),
      ...analysis.extractedInfo.links.map(i => i.value.toLowerCase())
    ]);

    if (indicators.size === 0) return [];

    return currentLogs
      .filter(log => {
        const logIndicators = [
          ...log.extractedInfo.upiIds.map(i => i.value.toLowerCase()),
          ...log.extractedInfo.phoneNumbers.map(i => i.value.toLowerCase()),
          ...log.extractedInfo.links.map(i => i.value.toLowerCase())
        ];
        return logIndicators.some(li => indicators.has(li));
      })
      .map(log => log.id);
  };

  const handleAnalysisStart = () => {
    setIsUpdating(true);
  };

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis, isNewSession: boolean = false) => {
    setIsUpdating(false);

    if (isNewSession || !currentSessionIdRef.current) {
      currentSessionIdRef.current = generateCaseId();
    }

    const sessionId = currentSessionIdRef.current;
    const linkedIds = findLinkedCases(analysis, logs.filter(l => l.id !== sessionId));

    setLogs(prev => {
      const existingIdx = prev.findIndex(l => l.id === sessionId);
      const newLog: IntelligenceLog = {
        ...analysis,
        id: sessionId,
        originalMessage: message,
        timestamp: Date.now(),
        status: 'Active',
        linkedCaseIds: linkedIds,
        messages: analysis.isScam && analysis.threatLevel !== 'Low' 
          ? (existingIdx >= 0 ? prev[existingIdx].messages : [{
              role: 'scammer',
              content: message.startsWith('[VIDEO') ? "Scam detected via live video feed forensics." : (message.startsWith('[AUDIO') ? "Scam detected via live call interception." : message),
              timestamp: Date.now()
            }])
          : []
      };

      if (existingIdx >= 0) {
        const updated = [...prev];
        updated[existingIdx] = newLog;
        return updated;
      }
      return [newLog, ...prev];
    });

    setLatestAnalysis({ message, analysis, sessionId });

    if (analysis.threatLevel !== 'Low') {
      const isHighRisk = analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical';
      let details = "Autonomous honeypot active. We are tracing the source's network to protect others.";
      if (linkedIds.length > 0) details = `Scammer network identified (Matched ${linkedIds.length} previous cases). Tracing infrastructure...`;
      if (isHighRisk) details += " Action: Lock UPI apps temporarily. Report transfers to 1930.";

      setActiveAlert({
        level: analysis.threatLevel as 'Medium' | 'High' | 'Critical',
        message: analysis.safetyAlert,
        details: details,
        isEngaging: isHighRisk
      });
    } else {
      setActiveAlert(null);
    }
  };

  const handleUpdateCaseStatus = (id: string, status: 'Active' | 'Blocked' | 'Resolved') => {
    setLogs(prev => prev.map(l => l.id === id ? { ...l, status } : l));
  };

  const handleClear = () => {
    setLatestAnalysis(null);
    setActiveAlert(null);
    currentSessionIdRef.current = null;
  };

  const handleMessagesUpdate = (newMessages: ChatMessage[]) => {
    if (!latestAnalysis) return;
    setLogs(prev => prev.map(log => 
      log.id === latestAnalysis.sessionId 
        ? { ...log, messages: newMessages } 
        : log
    ));
  };

  const handleIntelUpdate = (info: ExtractedInfo) => {
    if (!activeAlert || !latestAnalysis) return;
    setLogs(prev => prev.map(log => 
      log.id === latestAnalysis.sessionId 
        ? { ...log, extractedInfo: { ...log.extractedInfo, ...info } } 
        : log
    ));
    setActiveAlert(prev => prev ? { ...prev, details: "Confirmed malicious handle captured. Tracking network..." } : null);
  };

  const isHighRisk = latestAnalysis?.analysis.threatLevel === 'High' || latestAnalysis?.analysis.threatLevel === 'Critical';

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-slate-900 font-sans">
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between sticky top-0 z-[60] shadow-sm">
        <div className="flex items-center space-x-3">
          <div className="bg-blue-600 p-2 rounded-xl shadow-md cursor-pointer" onClick={() => {setLiveMode(false); handleClear(); setView('analyzer');}}>
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />
            </svg>
          </div>
          <div>
            <h1 className="text-xl font-extrabold tracking-tight text-slate-800">Bharat Cyber <span className="text-blue-600">Rakshak</span></h1>
            <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest text-center">Protocol V4.8.0-ADVANCED</p>
          </div>
        </div>

        <nav className="hidden md:flex items-center space-x-1 bg-slate-100 p-1 rounded-2xl border border-slate-200">
           <NavBtn active={view === 'analyzer'} onClick={() => setView('analyzer')} label="Command" />
           <NavBtn active={view === 'history'} onClick={() => setView('history')} label="Ops Feed" />
           <NavBtn active={view === 'intelligence'} onClick={() => setView('intelligence')} label="Intelligence" />
        </nav>

        <div className="flex items-center space-x-4">
          <div className="flex items-center space-x-2">
             <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_green]"></div>
             <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest hidden sm:block">Nodes Online</span>
          </div>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main className="flex-1 container mx-auto px-4 py-8 max-w-4xl space-y-8">
        {view === 'intelligence' ? (
          <div className="animate-in fade-in duration-500">
            <IntelligenceDashboard logs={logs} />
          </div>
        ) : view === 'history' ? (
          <div className="animate-in fade-in duration-500 space-y-8">
             <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Forensic Case Feed</h2>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Global Interception Logs</p>
                </div>
             </div>
             <CaseHistory logs={logs} onUpdateStatus={handleUpdateCaseStatus} />
          </div>
        ) : liveMode ? (
          <div className="animate-in slide-in-from-right-4 duration-500">
            <button onClick={() => setLiveMode(false)} className="mb-4 text-sm font-bold text-slate-500 flex items-center hover:text-blue-600 transition-colors">
              <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
              Return to Control
            </button>
            <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_SHIELD_INTERCEPTION", analysis, true)} />
          </div>
        ) : (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="text-center space-y-4">
              <h2 className="text-4xl font-black text-slate-800 tracking-tight leading-tight">Neutralize Distributed Fraud.</h2>
              <p className="text-slate-500 max-w-lg mx-auto text-lg leading-relaxed font-medium">Bharat's sovereign AI shield. Detecting patterns, engaging threats, and tracing financial footprints in real-time.</p>
              <div className="flex flex-wrap items-center justify-center gap-4">
                <button onClick={() => setLiveMode(true)} className="group relative inline-flex items-center justify-center px-8 py-4 font-black text-white bg-blue-600 rounded-2xl shadow-xl shadow-blue-600/30 hover:bg-blue-700 transition-all active:scale-95 overflow-hidden">
                  <div className="absolute inset-0 bg-gradient-to-r from-blue-400/20 to-transparent animate-shimmer"></div>
                  <svg className="w-6 h-6 mr-3 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                  <span>Deploy Live Shield</span>
                </button>
                <button onClick={() => setView('intelligence')} className="px-8 py-4 font-black text-slate-700 bg-white border border-slate-200 rounded-2xl shadow-lg hover:bg-slate-50 transition-all active:scale-95">
                  View Analytics
                </button>
              </div>
            </div>

            <ScamAnalyzer onAnalysisComplete={handleAnalysisComplete} onAnalysisStart={handleAnalysisStart} onClear={handleClear} />

            {latestAnalysis && (
              <div className="grid grid-cols-1 gap-8 animate-in slide-in-from-bottom-4 duration-500">
                <ResultPanel analysis={latestAnalysis.analysis} onClose={handleClear} />
                {isHighRisk && (
                  <div className="h-[500px]">
                    <BaitSession 
                      sessionId={latestAnalysis.sessionId}
                      initialMessages={logs.find(l => l.id === latestAnalysis.sessionId)?.messages || []}
                      onMessagesUpdate={handleMessagesUpdate}
                      onIntelExtracted={handleIntelUpdate}
                    />
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="py-10 px-6 border-t border-slate-200 mt-20 bg-white">
         <div className="container mx-auto max-w-4xl flex flex-col md:flex-row items-center justify-between text-[10px] font-black uppercase tracking-widest text-slate-400 space-y-4 md:space-y-0">
            <div className="flex items-center space-x-4">
               <span>&copy; 2026 Bharat Cyber Rakshak AI</span>
               <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
               <span>MeitY Directive Compliance</span>
            </div>
            <div className="flex items-center space-x-6">
               <span className="text-blue-500">Live Interception: Enabled</span>
               <span>End-to-End Forensic Encryption</span>
            </div>
         </div>
      </footer>
    </div>
  );
};

