import React, { useState, useMemo } from 'react';
import { IntelligenceLog, AnalyticsSummary } from '../types';

interface Props {
  logs: IntelligenceLog[];
}

const IntelligenceDashboard: React.FC<Props> = ({ logs }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'trends' | 'network' | 'performance'>('overview');

  const analytics = useMemo((): AnalyticsSummary => {
    const totalPrevention = logs.reduce((sum, log) => sum + (log.estimatedImpact || 0), 0);

    // Identifier tracking
    const idCounts: Record<string, { val: string, type: string, count: number }> = {};
    logs.forEach(log => {
      const allIds = [
        ...log.extractedInfo.upiIds.map(i => ({ v: i.value, t: 'UPI' })),
        ...log.extractedInfo.phoneNumbers.map(i => ({ v: i.value, t: 'TEL' })),
        ...log.extractedInfo.links.map(i => ({ v: i.value, t: 'URL' }))
      ];
      allIds.forEach(id => {
        if (!idCounts[id.v]) idCounts[id.v] = { val: id.v, type: id.t, count: 0 };
        idCounts[id.v].count++;
      });
    });

    const topIdentifiers = Object.values(idCounts)
      .sort((a, b) => b.count - a.count)
      .slice(0, 10)
      .map(item => ({ value: item.val, type: item.type, count: item.count }));

    // Channel/Lang distribution
    const channels: Record<string, number> = {};
    const langs: Record<string, number> = {};
    const patterns: Record<string, { count: number, risk: string }> = {};

    logs.forEach(l => {
      channels[l.channel] = (channels[l.channel] || 0) + 1;
      if (l.language) langs[l.language] = (langs[l.language] || 0) + 1;
      patterns[l.scamType] = { 
        count: (patterns[l.scamType]?.count || 0) + 1,
        risk: l.threatLevel
      };
    });

    // Honeypot metrics
    const baitingSessions = logs.filter(l => l.messages.length > 2);
    // Fixed: Cast Object.values to any[] to fix property 'length' does not exist on type 'unknown' error
    const successfulExtractions = baitingSessions.filter(l => 
      (Object.values(l.extractedInfo) as any[]).some(arr => arr.length > 0)
    ).length;

    return {
      totalPreventionInr: totalPrevention,
      topIdentifiers,
      emergingPatterns: Object.entries(patterns).map(([k, v]) => ({ pattern: k, ...v })),
      channelDistribution: channels,
      languageDistribution: langs,
      honeypotSuccessRate: baitingSessions.length ? (successfulExtractions / baitingSessions.length) * 100 : 0
    };
  }, [logs]);

  const totalScams = logs.filter(l => l.isScam).length;

  return (
    <div className="space-y-8">
      {/* High-Level KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <StatCard 
          title="Potential Loss Prevented" 
          value={`₹${(analytics.totalPreventionInr / 100000).toFixed(2)}L`} 
          sub="INR Estimated"
          color="text-green-600" 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>}
        />
        <StatCard 
          title="Active Interventions" 
          value={totalScams} 
          sub="Honeypots Engaged"
          color="text-red-500" 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>}
        />
        <StatCard 
          title="Network Nodes" 
          value={analytics.topIdentifiers.length} 
          sub="Known Scammer Assets"
          color="text-blue-500" 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>}
        />
        <StatCard 
          title="Honeypot Success" 
          value={`${analytics.honeypotSuccessRate.toFixed(0)}%`} 
          sub="Intel Extraction Rate"
          color="text-purple-500" 
          icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86 3.86l-.477 2.387c-.037.185-.112.355-.224.502l-1.022 1.363a2 2 0 01-1.428.857H7a2 2 0 01-2-2v-3.572a2 2 0 01.572-1.414l5.428-5.428a2 2 0 011.414-.572h3.572a2 2 0 012 2v1.428a2 2 0 01-.857 1.428l-1.363 1.022a2 2 0 01-.502.224l-2.387.477a6 6 0 01-3.86-3.86l.477-2.387a2 2 0 01.547-1.022L15.428 4.572a2 2 0 011.414-.572H20a2 2 0 012 2v3.572a2 2 0 01-.572 1.414l-5.428 5.428z" /></svg>}
        />
      </div>

      {/* Tabs Navigation */}
      <div className="flex space-x-2 bg-slate-100 p-1.5 rounded-2xl w-fit">
