    const totalPrevention = logs.reduce((sum, log) => sum + (log.estimatedImpact || 0), 0);
    const idCounts: Record<string, { val: string, type: string, count: number }> = {};

    logs.forEach(log => {
      const allIds = [
        ...log.extractedInfo.upiIds.map(i => ({ v: i.value, t: 'UPI' })),
        ...log.extractedInfo.phoneNumbers.map(i => ({ v: i.value, t: 'TEL' })),
        ...log.extractedInfo.links.map(i => ({ v: i.value, t: 'URL' }))
      ];
      allIds.forEach(id => {
        const key = id.v.toLowerCase();
        if (!idCounts[key]) idCounts[key] = { val: id.v, type: id.t, count: 0 };
        idCounts[key].count++;
      });
    });

    const topIdentifiers = Object.values(idCounts)
      .sort((a, b) => b.count - a.count)
      .slice(0, 8)
      .map(item => ({ value: item.val, type: item.type, count: item.count }));

    const channels: Record<string, number> = {};
    const langs: Record<string, number> = {};
    const patterns: Record<string, { count: number, risk: string }> = {};

    logs.forEach(l => {
      channels[l.channel] = (channels[l.channel] || 0) + 1;
      if (l.language) langs[l.language] = (langs[l.language] || 0) + 1;
      patterns[l.scamType] = { 
        count: (patterns[l.scamType]?.count || 0) + 1,
        risk: l.threatLevel
      };
    });

    const baitingSessions = logs.filter(l => l.messages.length > 2);
    const successfulExtractions = baitingSessions.filter(l => 
      (Object.values(l.extractedInfo) as any[]).some(arr => arr.length > 0)
    ).length;

    return {
      totalPreventionInr: totalPrevention,
      topIdentifiers,
      emergingPatterns: Object.entries(patterns).map(([k, v]) => ({ pattern: k, ...v })),
      channelDistribution: channels,
      languageDistribution: langs,
      honeypotSuccessRate: baitingSessions.length ? (successfulExtractions / baitingSessions.length) * 100 : 0
    };
  }, [logs]);

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* High-Level Ops Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <KPIBox title="Money Prevented" value={`₹${(analytics.totalPreventionInr / 100000).toFixed(2)}L`} sub="Estimated INR Saved" color="text-green-600" />
        <KPIBox title="Closed Cases" value={logs.filter(l => l.status === 'Resolved' || l.status === 'Blocked').length} sub="Successfully Neutralized" color="text-blue-600" />
        <KPIBox title="Known Rings" value={logs.filter(l => l.linkedCaseIds.length > 0).length} sub="Infrastructure clusters" color="text-purple-600" />
        <KPIBox title="AI Success Rate" value={`${analytics.honeypotSuccessRate.toFixed(0)}%`} sub="Extraction efficiency" color="text-slate-900" />
      </div>

      {/* Internal Navigation */}
      <div className="flex space-x-2 bg-slate-100 p-1.5 rounded-2xl w-fit">
        <TabNav active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} label="Executive Brief" />
        <TabNav active={activeTab === 'trends'} onClick={() => setActiveTab('trends')} label="Channel Distribution" />
        <TabNav active={activeTab === 'network'} onClick={() => setActiveTab('network')} label="Network Clusters" />
      </div>

      {/* Content Areas */}
      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <Section title="Emerging Patterns" icon={<div className="w-2 h-2 bg-red-600 rounded-full animate-pulse mr-2" />}>
             <div className="space-y-4">
                {analytics.emergingPatterns.sort((a,b)=>b.count-a.count).slice(0, 5).map((p, i) => (
                   <div key={i} className="flex flex-col space-y-2">
                      <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest text-slate-500">
                         <span>{p.pattern}</span>
                         <span className={p.risk === 'Critical' ? 'text-red-600' : 'text-orange-600'}>{p.risk} THREAT</span>
                      </div>
                      <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden">
                         <div className="bg-slate-800 h-full" style={{ width: `${(p.count / logs.length) * 100}%` }}></div>
                      </div>
                   </div>
                ))}
             </div>
          </Section>

          <Section title="High-Value Identifiers" icon={<div className="w-2 h-2 bg-blue-600 rounded-full mr-2" />}>
             <div className="space-y-3">
                {analytics.topIdentifiers.map((id, i) => (
                  <div key={i} className="flex items-center justify-between p-3 bg-slate-50 border border-slate-100 rounded-xl">
                    <div className="flex items-center space-x-3">
                       <span className="text-[8px] font-black bg-slate-800 text-white px-1.5 py-0.5 rounded">{id.type}</span>
                       <span className="text-xs font-bold font-mono text-slate-700">{id.value}</span>
                    </div>
                    <span className="text-[10px] font-black text-slate-400">{id.count} CASES</span>
                  </div>
                ))}
             </div>
          </Section>
        </div>
      )}

      {activeTab === 'trends' && (
        <div className="bg-white rounded-3xl border border-slate-200 p-8 shadow-xl">
           <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              <div className="space-y-6">
                 <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Regional Language Split</h4>
                 <div className="space-y-4">
                    {(Object.entries(analytics.languageDistribution) as [string, number][]).sort((a,b)=>b[1]-a[1]).map(([l, c]) => (
                      <ChartBar key={l} label={l} percent={(c/logs.length)*100} color="bg-purple-600" />
                    ))}
                 </div>
              </div>
              <div className="space-y-6">
                 <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Entry Vector distribution</h4>
                 <div className="space-y-4">
                    {(Object.entries(analytics.channelDistribution) as [string, number][]).sort((a,b)=>b[1]-a[1]).map(([l, c]) => (
                      <ChartBar key={l} label={l} percent={(c/logs.length)*100} color="bg-blue-600" />
                    ))}
                 </div>
              </div>
           </div>
        </div>
      )}

      {activeTab === 'network' && (
        <div className="bg-white rounded-3xl border border-slate-200 p-10 shadow-xl min-h-[400px] flex flex-col items-center justify-center text-center">
           {logs.some(l => l.linkedCaseIds.length > 0) ? (
             <div className="w-full space-y-8">
                <div className="text-center space-y-2">
                   <h3 className="text-lg font-black uppercase tracking-tight text-slate-800">Scammer Infrastructure Mapping</h3>
                   <p className="text-xs text-slate-500 font-medium">Relationships identified through matching financial and contact indicators.</p>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                   {logs.filter(l => l.linkedCaseIds.length > 0).slice(0, 6).map(log => (
                     <div key={log.id} className="p-4 bg-blue-50/50 border border-blue-200 rounded-2xl space-y-3">
                        <div className="text-[9px] font-black text-blue-600 uppercase">Ring Cluster: {log.id}</div>
                        <div className="flex flex-wrap gap-1">
                           {log.linkedCaseIds.map(cid => (
                             <span key={cid} className="px-2 py-0.5 bg-white border border-blue-100 rounded text-[8px] font-bold text-slate-500">{cid}</span>
                           ))}
                        </div>
                     </div>
                   ))}
                </div>
             </div>
           ) : (
             <div className="space-y-4">
                <div className="w-16 h-16 bg-slate-50 rounded-full border border-slate-100 flex items-center justify-center mx-auto opacity-50">
                  <svg className="w-8 h-8 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.826L7.04 9.356" /></svg>
                </div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Cross-vector cluster map empty</p>
             </div>
           )}
        </div>
      )}
    </div>
  );
};

