export const analyzeMessage = async (message: string): Promise<ScamAnalysis> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Analyze input: "${message}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: SCAM_ANALYSIS_SCHEMA,
      systemInstruction: MISSION_DIRECTIVE
    },
  });
  const analysis = JSON.parse(response.text);
  const matches = THREAT_FEED.filter(tf => message.toLowerCase().includes(tf.indicator.toLowerCase()));
  if (matches.length > 0) {
    analysis.threatLevel = 'Critical';
    analysis.threatMatches = matches;
  }
  return analysis;
};

