                    <svg className="w-4 h-4 text-slate-300 group-hover:text-blue-600 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" /></svg>
                 </div>
              </div>
           ))}
           {analytics.scamRings.length === 0 && (
              <div className="col-span-full py-20 text-center space-y-4">
                 <div className="w-16 h-16 bg-slate-100 rounded-full mx-auto flex items-center justify-center"><svg className="w-8 h-8 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.826L7.04 9.356" /></svg></div>
                 <p className="text-xs font-black uppercase text-slate-400 tracking-widest">Network clustering initializing...</p>
              </div>
           )}
        </div>
      )}

      {activeTab === 'waves' && (
