                <section>
                   <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Actionable Evidence Export</h4>
                   <div className="bg-slate-50 p-6 rounded-3xl border border-slate-200 space-y-4">
