export function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

export async function decodeAudioData(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  return buffer;
}

import React, { useState, useMemo } from 'react';
import { IntelligenceLog, AnalyticsSummary, ScamRing, EmergingWave } from '../types';

interface Props {
  logs: IntelligenceLog[];
}

const IntelligenceDashboard: React.FC<Props> = ({ logs }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'rings' | 'waves' | 'governance'>('overview');

  const analytics = useMemo((): AnalyticsSummary => {
    const totalPrevention = logs.reduce((sum, log) => sum + (log.estimatedImpact || 0), 0);
    const idCounts: Record<string, { val: string, type: string, count: number }> = {};

    logs.forEach(log => {
      const allIds = [
        ...log.extractedInfo.upiIds.map(i => ({ v: i.value, t: 'UPI' })),
        ...log.extractedInfo.phoneNumbers.map(i => ({ v: i.value, t: 'TEL' })),
        ...log.extractedInfo.links.map(i => ({ v: i.value, t: 'URL' }))
      ];
      allIds.forEach(id => {
        const key = id.v.toLowerCase();
        if (!idCounts[key]) idCounts[key] = { val: id.v, type: id.t, count: 0 };
        idCounts[key].count++;
      });
    });

    const topIdentifiers = Object.values(idCounts)
      .sort((a, b) => b.count - a.count)
      .slice(0, 10)
      .map(item => ({ value: item.val, type: item.type, count: item.count }));

    const rings: Record<string, ScamRing> = {};
    logs.forEach(l => {
      if (l.ringId) {
        if (!rings[l.ringId]) {
          rings[l.ringId] = { id: l.ringId, name: `Ring Cluster ${l.ringId.split('-')[1]}`, centralIdentifiers: [], caseCount: 0, totalPreventedInr: 0, riskTrend: 'Stable', isInternational: false };
        }
        rings[l.ringId].caseCount++;
        rings[l.ringId].totalPreventedInr += (l.estimatedImpact || 0);
        if (l.isInternational) rings[l.ringId].isInternational = true;
      }
    });

    const waves: Record<string, EmergingWave> = {};
    logs.filter(l => l.timestamp > Date.now() - 86400000).forEach(l => {
      if (!waves[l.scamType]) waves[l.scamType] = { pattern: l.scamType, firstSeen: l.timestamp, count: 0, velocity: 0, riskLevel: (l.threatLevel === 'Low' ? 'Medium' : l.threatLevel) as any };
      waves[l.scamType].count++;
    });

    const baitingSessions = logs.filter(l => l.messages.length > 2);
    const successfulExtractions = baitingSessions.filter(l => (Object.values(l.extractedInfo) as any[]).some(arr => arr.length > 0)).length;

    const compliancePassCount = logs.filter(l => Object.values(l.governance.ethicsChecklist).every(v => v === true)).length;

    return {
      totalPreventionInr: totalPrevention,
      topIdentifiers,
      emergingWaves: Object.values(waves).sort((a,b) => b.count - a.count),
      scamRings: Object.values(rings),
      channelDistribution: logs.reduce((acc: any, l) => { acc[l.channel] = (acc[l.channel] || 0) + 1; return acc; }, {}),
      languageDistribution: logs.reduce((acc: any, l) => { if (l.language) acc[l.language] = (acc[l.language] || 0) + 1; return acc; }, {}),
      honeypotSuccessRate: baitingSessions.length ? (successfulExtractions / baitingSessions.length) * 100 : 0,
      governanceMetrics: {
        avgPrivacyScore: logs.length ? logs.reduce((a,b)=>a+b.governance.privacyScore,0)/logs.length : 100,
        reviewPendingCount: logs.filter(l => l.governance.legalStanding === 'Probable Cause').length,
        complianceRate: logs.length ? (compliancePassCount / logs.length) * 100 : 100
      }
    };
  }, [logs]);

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <KPIBox title="Prevented Loss" value={`₹${(analytics.totalPreventionInr / 100000).toFixed(2)}L`} sub="Forensic Estimate" color="text-green-600" />
        <KPIBox title="Rings Mapped" value={analytics.scamRings.length} sub="Organized Infrastructure" color="text-blue-600" />
        <KPIBox title="Privacy Guard" value={`${analytics.governanceMetrics.avgPrivacyScore.toFixed(0)}%`} sub="Masking Efficiency" color="text-purple-600" />
        <KPIBox title="Compliance" value={`${analytics.governanceMetrics.complianceRate.toFixed(0)}%`} sub="Ethics Alignment" color="text-slate-900" />
      </div>

      <div className="flex space-x-2 bg-slate-100 p-1.5 rounded-2xl w-fit">
        <TabNav active={activeTab === 'overview'} onClick={() => setActiveTab('overview')} label="Briefing" />
        <TabNav active={activeTab === 'rings'} onClick={() => setActiveTab('rings')} label="Criminal Rings" />
        <TabNav active={activeTab === 'waves'} onClick={() => setActiveTab('waves')} label="Threat Waves" />
        <TabNav active={activeTab === 'governance'} onClick={() => setActiveTab('governance')} label="Governance & Ethics" />
      </div>

      {activeTab === 'governance' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in slide-in-from-bottom-4">
           <Section title="Accountability Monitor" icon={<div className="w-2 h-2 bg-blue-600 rounded-full mr-2" />}>
              <div className="space-y-6">
                 <MetricRow label="Human Review Pending" value={analytics.governanceMetrics.reviewPendingCount} sub="Awaiting institutional approval" />
                 <MetricRow label="Data Masking Score" value={analytics.governanceMetrics.avgPrivacyScore} sub="PII protection efficiency" isPercent />
                 <MetricRow label="Evidence Integrity" value={100} sub="Hashing and chaining status" isPercent />
              </div>
           </Section>

           <Section title="Fairness & Ethics Audit" icon={<div className="w-2 h-2 bg-purple-600 rounded-full mr-2" />}>
              <div className="space-y-4">
                 <div className="p-4 bg-slate-50 border border-slate-100 rounded-2xl space-y-3">
                    <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Ethics Protocol Adherence</h5>
                    <CheckItem label="No Assumed Guilt (Behavioral focus)" pass />
                    <CheckItem label="Explicit Data Provision" pass />
                    <CheckItem label="Bias Mitigation Filters" pass />
                    <CheckItem label="Verifiable Institutional Linkage" pass />
                 </div>
                 <p className="text-[10px] text-slate-400 font-medium leading-relaxed italic">System adheres to Bharat National AI Ethics Framework. Decisions are evidence-based recommendations, not autonomous enforcement.</p>
              </div>
           </Section>
        </div>
      )}

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
           <Section title="High-Risk Identifiers" icon={<div className="w-2 h-2 bg-red-600 rounded-full mr-2" />}>
              <div className="space-y-3">
                 {analytics.topIdentifiers.map((id, i) => (
                    <div key={i} className="flex items-center justify-between p-4 bg-slate-50 border border-slate-100 rounded-2xl">
                       <div className="flex items-center space-x-3">
                          <span className="text-[8px] font-black bg-slate-800 text-white px-2 py-0.5 rounded uppercase">{id.type}</span>
                          <span className="text-xs font-bold font-mono text-slate-700">{id.value}</span>
                       </div>
                       <span className="text-[10px] font-black text-slate-400 uppercase">{id.count} Cases</span>
                    </div>
                 ))}
                 {analytics.topIdentifiers.length === 0 && <p className="text-center py-10 text-slate-400 italic">Forensic mapping pending...</p>}
              </div>
           </Section>

           <Section title="Attack Vectors" icon={<div className="w-2 h-2 bg-blue-600 rounded-full mr-2" />}>
              <div className="space-y-6">
                 <div className="space-y-2">
                    <h4 className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Entry Vector distribution</h4>
                    {Object.entries(analytics.channelDistribution).sort((a:any,b:any)=>b[1]-a[1]).map(([l, c]) => (
                       <ChartBar key={l} label={l} percent={(c as any / logs.length)*100} color="bg-blue-600" />
                    ))}
                 </div>
              </div>
           </Section>
        </div>
      )}

      {activeTab === 'rings' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
           {analytics.scamRings.map(ring => (
              <div key={ring.id} className="bg-white border border-slate-200 p-6 rounded-3xl shadow-xl space-y-4 hover:border-blue-500 transition-all cursor-pointer group">
                 <div className="flex justify-between items-start">
                    <div className="space-y-1">
                       <h4 className="text-sm font-black text-slate-800 uppercase tracking-tight">{ring.name}</h4>
                       <span className="text-[9px] font-black text-blue-600 bg-blue-50 px-2 py-0.5 rounded">R-NODE: {ring.id}</span>
                    </div>
                 </div>
                 <div className="grid grid-cols-2 gap-4 border-y border-slate-100 py-4">
                    <div>
                       <div className="text-[8px] font-black text-slate-400 uppercase mb-1">Impact (INR)</div>
                       <div className="text-sm font-black text-green-600">₹{(ring.totalPreventedInr / 1000).toFixed(1)}K</div>
                    </div>
                    <div>
                       <div className="text-[8px] font-black text-slate-400 uppercase mb-1">Dossier Count</div>
                       <div className="text-sm font-black text-slate-800">{ring.caseCount}</div>
                    </div>
                 </div>
              </div>
           ))}
        </div>
      )}
    </div>
  );
};

