                {(analysis.extractedInfo.upiIds.length === 0 && analysis.extractedInfo.links.length === 0 && analysis.extractedInfo.phoneNumbers.length === 0) && (
                   <div className="text-[10px] font-bold text-slate-300 uppercase tracking-widest italic">Awaiting further extraction...</div>
