export function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

export async function decodeAudioData(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  return buffer;
}

import React, { useState, useRef } from 'react';
import { ScamAnalysis } from '../types';
import { maskValue } from '../utils/masking';
import { generateAudioFromText, decodeBase64, decodeAudioData } from '../services/geminiService';

interface Props {
  analysis: ScamAnalysis;
  onClose: () => void;
}

const ResultPanel: React.FC<Props> = ({ analysis, onClose }) => {
  const [isSpeaking, setIsSpeaking] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const isHighRisk = analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical';
  const isMedRisk = analysis.threatLevel === 'Medium';

  const riskColor = isHighRisk ? 'text-red-600 bg-red-50' : isMedRisk ? 'text-orange-600 bg-orange-50' : 'text-green-600 bg-green-50';
  const riskBorder = isHighRisk ? 'border-red-200' : isMedRisk ? 'border-orange-200' : 'border-green-200';
  const riskLabel = isHighRisk ? 'High Risk Scam' : isMedRisk ? 'Suspicious / Caution' : 'Safe / Low Risk';

  const stopAudio = () => {
    if (currentSourceRef.current) {
      try {
        currentSourceRef.current.stop();
      } catch (e) {
        // Source might already be stopped
      }
      currentSourceRef.current = null;
    }
    setIsSpeaking(false);
  };

  const handlePlayBriefing = async () => {
    if (isSpeaking) {
      stopAudio();
      return;
    }

    try {
      setIsSpeaking(true);
      const textToSpeak = `Security Alert: ${analysis.safetyAlert}. Analysis Summary: ${analysis.summary}`;
      const base64Audio = await generateAudioFromText(textToSpeak);

      if (base64Audio) {
        if (!audioContextRef.current) {
          audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
        }

        const ctx = audioContextRef.current;
        const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);

        source.onended = () => {
          setIsSpeaking(false);
          currentSourceRef.current = null;
        };

        currentSourceRef.current = source;
        source.start(0);
      } else {
        setIsSpeaking(false);
      }
    } catch (e) {
      console.error("Audio synthesis failed", e);
      setIsSpeaking(false);
    }
  };

  return (
    <div className={`bg-white rounded-3xl border-2 ${riskBorder} shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300`}>
      {/* Header with Risk Level */}
      <div className={`px-8 py-6 flex items-center justify-between ${riskColor}`}>
        <div className="flex items-center space-x-4">
          <div className={`p-3 rounded-2xl shadow-lg ${isHighRisk ? 'bg-red-600' : isMedRisk ? 'bg-orange-600' : 'bg-green-600'}`}>
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={isHighRisk ? "M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" : "M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"} />
            </svg>
          </div>
          <div>
            <h3 className="text-2xl font-black uppercase tracking-tight">{riskLabel}</h3>
            <p className="text-sm font-bold opacity-80">{analysis.scamType}</p>
          </div>
        </div>
        <button onClick={onClose} className="p-2 hover:bg-black/5 rounded-full transition-all">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
        </button>
      </div>

      <div className="p-8 space-y-8">
        {/* User Safety Alert */}
