                  <>
                    <div className="p-4 bg-white rounded-2xl shadow-sm mb-3 text-slate-400 border border-slate-100 group-hover:scale-105 transition-transform duration-300">
                      <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
                    </div>
                    <p className="text-sm font-black text-slate-800 text-center px-4 uppercase tracking-tighter">Upload or drag video file here</p>
