          </div>
        )}

        <button
          onClick={handleAnalyze}
          disabled={loading || isRecording}
          className={`w-full py-5 rounded-2xl font-black text-xl shadow-xl transition-all flex items-center justify-center space-x-3 ${loading ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-600/30'}`}
        >
          {loading ? (
            <>
              <div className="w-5 h-5 border-3 border-slate-400/30 border-t-slate-400 rounded-full animate-spin"></div>
              <span className="uppercase tracking-widest text-xs">Acoustic & Visual Synthesis...</span>
            </>
          ) : (
            <>
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
              <span>Refresh Forensic Analysis</span>
