);

export default ScamAnalyzer;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import { decodeBase64, decodeAudioData } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAlert: (analysis: ScamAnalysis) => void;
}

const LiveShield: React.FC<Props> = ({ onAlert }) => {
  const [isActive, setIsActive] = useState(false);
  const [transcription, setTranscription] = useState<string[]>([]);
  const [lastSafetyAlert, setLastSafetyAlert] = useState<string | null>(null);
  const [threatLevel, setThreatLevel] = useState<'Low' | 'Medium' | 'High'>('Low');

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const frameIntervalRef = useRef<number | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Manual encode implementation following the provided examples.
  function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  function createBlob(data: Float32Array): Blob {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = data[i] * 32768;
    }
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  }

  const startShield = async () => {
    setIsActive(true);
    setTranscription([]);
    setLastSafetyAlert(null);
    setThreatLevel('Low');
    nextStartTimeRef.current = 0;

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = outputAudioContext;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContext.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContext.destination);

            const ctx = canvasRef.current?.getContext('2d');
            frameIntervalRef.current = window.setInterval(() => {
              if (videoRef.current && canvasRef.current && ctx) {
                canvasRef.current.width = 320;
                canvasRef.current.height = 240;
                ctx.drawImage(videoRef.current, 0, 0, 320, 240);
                const base64 = canvasRef.current.toDataURL('image/jpeg', 0.5).split(',')[1];
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: base64, mimeType: 'image/jpeg' } }));
              }
            }, 2000);
          },
          onmessage: async (msg: LiveServerMessage) => {
            if (msg.serverContent?.inputTranscription) {
              const text = msg.serverContent.inputTranscription.text;
              setTranscription(prev => [...prev.slice(-4), `Suspicious: ${text}`]);
              checkScamTriggers(text);
            }
            if (msg.serverContent?.outputTranscription) {
              const text = msg.serverContent.outputTranscription.text;
              setTranscription(prev => [...prev.slice(-4), `AI Shield: ${text}`]);
            }

            const base64EncodedAudioString = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (base64EncodedAudioString && audioContextRef.current) {
              const ctx = audioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decodeBase64(base64EncodedAudioString), ctx);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
              });

              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (msg.serverContent?.interrupted) {
              for (const source of sourcesRef.current.values()) {
                source.stop();
                sourcesRef.current.delete(source);
              }
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error("LiveShield Error", e),
          onclose: (e) => console.debug("LiveShield Closed", e),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          systemInstruction: `You are Bharat Cyber Rakshak AI. Monitor this live audio/video feed for scam indicators. 

          USER PROTECTION PROTOCOL:
          If you detect a scam in progress, generate a short, non-technical Safety Alert for the citizen.
          Example: "⚠️ Warning: This is a scam call. Do not share your bank OTP or login details."

          Focus on:
          1. Digital Arrest threats (CBI, Customs, Police impersonation).
          2. Pressure tactics for OTPs or Bank logins.
          3. Deepfake artifacts or unnatural movement.

          Provide short, quiet advice ONLY if a scam is highly likely.`
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error("Shield activation failed", err);
      setIsActive(false);
    }
  };

  const checkScamTriggers = (text: string) => {
    const triggers = ['otp', 'bank login', 'police', 'customs', 'arrest', 'urgent', 'payment', 'upi', 'account frozen', 'grandson', 'relative', 'win', 'lottery', 'kyc'];
    const lowerText = text.toLowerCase();
    const found = triggers.filter(t => lowerText.includes(t));

    if (found.length > 0) {
      setThreatLevel('High');
      const safetyMsg = `⚠️ WE DETECTED A HIGH-RISK SCAM (${found[0].toUpperCase()}). Please do not send any money or share personal details. Rakshak AI is monitoring the source.`;
      setLastSafetyAlert(safetyMsg);

      // Notify parent to show global banner
      onAlert({
        isScam: true,
        confidence: 0.95,
        scamType: "Real-time Voice Fraud",
        channel: 'call',
        threatLevel: 'High',
        summary: `Live call monitoring detected the following high-risk triggers: ${found.join(', ')}.`,
        safetyAlert: safetyMsg,
        // Fix: Add missing ifscCodes property to ExtractedInfo to satisfy interface requirements.
        extractedInfo: { upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [], links: [], cryptoWallets: [], fakeIdentities: [] },
        fingerprint: { primaryHandle: 'VOICE_FEED', primaryPhone: '', primaryLink: '', category: 'Voice' },
        recommendedActions: ["Hang up immediately.", "Do not press any digits on your phone keypad.", "Lock your banking app."],
        suggestedBaitResponse: ""
      });
    }
  };

  const stopShield = () => {
    if (sessionRef.current) sessionRef.current.close();
    if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
    }
    setIsActive(false);
  };

  useEffect(() => {
    return () => stopShield();
  }, []);

  return (
    <div className="bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden">
      <div className={`px-8 py-6 flex items-center justify-between border-b border-slate-100 ${isActive ? 'bg-blue-600 text-white' : 'bg-slate-50 text-slate-400'}`}>
        <div className="flex items-center space-x-4">
          <div className={`p-3 rounded-2xl ${isActive ? 'bg-blue-500 animate-pulse' : 'bg-slate-200'}`}>
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
          </div>
          <div>
            <h3 className="text-2xl font-black uppercase tracking-tight">Live Protection Shield</h3>
            <p className="text-sm font-bold opacity-70 uppercase tracking-widest">{isActive ? 'Monitoring Feed for Threats' : 'System Standby'}</p>
          </div>
        </div>
        {isActive && (
          <div className="flex items-center space-x-2 bg-blue-700 px-4 py-2 rounded-xl border border-blue-400">
             <div className="w-3 h-3 bg-white rounded-full animate-ping"></div>
             <span className="text-xs font-black uppercase tracking-widest">Active Protection</span>
          </div>
        )}
      </div>

      <div className="p-8 grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="aspect-video bg-slate-900 rounded-3xl overflow-hidden relative shadow-inner">
             <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover grayscale opacity-40 mix-blend-screen" />
             <canvas ref={canvasRef} className="hidden" />

             {isActive && (
               <div className="absolute inset-0 pointer-events-none flex flex-col justify-between p-6">
