import React, { useState, useEffect, useRef } from 'react';
import { analyzeMessage, analyzeVideoFrame, analyzeUrlWithSearch, analyzeAudio } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
  onAnalysisStart: () => void;
  onClear: () => void;
}

enum IntakeType {
  Message = 'MESSAGE',
  Transcript = 'TRANSCRIPT',
  Media = 'MEDIA',
  QR = 'QR'
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete, onAnalysisStart, onClear }) => {
  const [activeType, setActiveType] = useState<IntakeType>(IntakeType.Message);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isLive, setIsLive] = useState(false);

  // Video/QR State
  const [videoSrc, setVideoSrc] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // URL State
  const [urlInput, setUrlInput] = useState('');
  const [urlError, setUrlError] = useState<string | null>(null);

  const debounceTimerRef = useRef<number | null>(null);
  const currentRequestIdRef = useRef<number>(0);

  const validateUrl = (url: string) => {
    try { new URL(url.includes('://') ? url : 'https://' + url); return true; } catch { return false; }
  };

  useEffect(() => {
    if (activeType === IntakeType.Message && input.trim().length > 10) {
      if (debounceTimerRef.current) window.clearTimeout(debounceTimerRef.current);
      setIsLive(true);
      debounceTimerRef.current = window.setTimeout(handleAnalyze, 800);
    } else if (input.trim().length === 0) {
      onClear();
      setIsLive(false);
    }
  }, [input]);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setVideoSrc("camera_active");
      }
    } catch (err) {
      alert("Camera access required for QR Forensics");
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
      videoRef.current.srcObject = null;
      setVideoSrc(null);
    }
  };

  const captureFrame = (): string | null => {
    if (!videoRef.current || !canvasRef.current) return null;
    const canvas = canvasRef.current;
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx?.drawImage(videoRef.current, 0, 0);
    return canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
  };

  const handleAnalyze = async () => {
    const requestId = ++currentRequestIdRef.current;
    setLoading(true);
    onAnalysisStart();
    try {
      let result: ScamAnalysis;
      let identifier = "";

      if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
        result = await analyzeMessage(input);
        identifier = input;
      } else if (activeType === IntakeType.QR) {
        const frame = captureFrame();
        if (!frame) throw new Error("No frame captured");
        // We reuse video analysis for QR to extract text/links from visual
        const visual = await analyzeVideoFrame(frame);
        result = {
          isScam: visual.isFraudulent,
          confidence: visual.anomalyScore / 100,
          scamType: "QR Code Fraud",
          channel: 'qr',
          threatLevel: visual.isFraudulent ? 'High' : 'Low',
          summary: visual.forensicNotes,
          safetyAlert: visual.isFraudulent ? "⚠️ MALICIOUS QR DETECTED. DO NOT AUTHORIZE PAYMENTS." : "QR Code appears legitimate.",
          extractedInfo: { upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [], links: visual.screenText.map(t => ({ value: t, confidence: 90 })), cryptoWallets: [], fakeIdentities: [] },
          fingerprint: { primaryHandle: visual.subjectIdentification || 'QR_OBJECT', primaryPhone: '', primaryLink: '', category: 'Visual QR' },
          recommendedActions: visual.detectedThreats,
          suggestedBaitResponse: ""
        };
        identifier = "[QR_FORENSIC_CAPTURE]";
      } else {
        if (!urlInput) return;
        result = await analyzeUrlWithSearch(urlInput);
        identifier = urlInput;
      }

      if (requestId === currentRequestIdRef.current) {
        onAnalysisComplete(identifier, result);
      }
    } catch (error) {
      console.error(error);
    } finally {
      if (requestId === currentRequestIdRef.current) setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden relative">
      <div className="flex border-b border-slate-100 bg-slate-50/50">
        <TabButton active={activeType === IntakeType.Message} onClick={() => { setActiveType(IntakeType.Message); stopCamera(); }} label="Text" icon="💬" />
        <TabButton active={activeType === IntakeType.QR} onClick={() => { setActiveType(IntakeType.QR); startCamera(); }} label="QR Scan" icon="📱" />
        <TabButton active={activeType === IntakeType.Media} onClick={() => { setActiveType(IntakeType.Media); stopCamera(); }} label="Web/URL" icon="🌐" />
      </div>

      <div className="p-8 space-y-6">
        {activeType === IntakeType.Message ? (
          <textarea
            className="w-full h-40 p-6 bg-slate-50 border border-slate-200 rounded-2xl text-slate-700 focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none text-lg font-medium"
            placeholder="Paste suspicious text or SMS here..."
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />
        ) : activeType === IntakeType.QR ? (
          <div className="relative aspect-video bg-black rounded-2xl overflow-hidden border-2 border-slate-800">
             <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover grayscale opacity-60" />
             <canvas ref={canvasRef} className="hidden" />
             <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none">
                <div className="w-full h-full border-2 border-blue-500/50 relative">
                   <div className="absolute inset-0 flex items-center justify-center">
                      <div className="w-48 h-48 border-2 border-dashed border-white/20 rounded-3xl animate-pulse" />
                   </div>
                </div>
             </div>
             <div className="absolute bottom-4 left-0 right-0 text-center">
                <span className="text-[10px] font-black text-white/50 uppercase tracking-[0.3em]">Align QR Code in Center</span>
             </div>
          </div>
        ) : (
          <input 
            type="text" 
            placeholder="Enter suspicious URL for deep reputation scan..." 
            value={urlInput}
            onChange={(e) => setUrlInput(e.target.value)}
            className="w-full p-6 bg-slate-50 border border-slate-200 rounded-2xl text-lg font-bold outline-none focus:ring-2 focus:ring-blue-500"
          />
        )}

        <button
          onClick={handleAnalyze}
          disabled={loading}
          className={`w-full py-5 rounded-2xl font-black text-xl shadow-xl transition-all flex items-center justify-center space-x-3 ${loading ? 'bg-slate-100 text-slate-400' : 'bg-blue-600 text-white hover:bg-blue-700'}`}
        >
          {loading ? (
            <div className="w-5 h-5 border-3 border-slate-300 border-t-blue-600 rounded-full animate-spin"></div>
          ) : (
            <span>Execute Forensic Analysis</span>
          )}
        </button>
      </div>
    </div>
  );
};

