interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
  onAnalysisStart: () => void;
  onClear: () => void;
}

enum IntakeType {
  Message = 'MESSAGE',
  Transcript = 'TRANSCRIPT',
  Media = 'MEDIA',
  QR = 'QR'
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete, onAnalysisStart, onClear }) => {
  const [activeType, setActiveType] = useState<IntakeType>(IntakeType.Message);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isLive, setIsLive] = useState(false);

  // Video/QR State
  const [videoSrc, setVideoSrc] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // URL State
  const [urlInput, setUrlInput] = useState('');
  const [urlError, setUrlError] = useState<string | null>(null);

  const debounceTimerRef = useRef<number | null>(null);
  const currentRequestIdRef = useRef<number>(0);

  const validateUrl = (url: string) => {
    try { new URL(url.includes('://') ? url : 'https://' + url); return true; } catch { return false; }
  };

  useEffect(() => {
    if (activeType === IntakeType.Message && input.trim().length > 10) {
      if (debounceTimerRef.current) window.clearTimeout(debounceTimerRef.current);
      setIsLive(true);
      debounceTimerRef.current = window.setTimeout(handleAnalyze, 800);
    } else if (input.trim().length === 0 && activeType === IntakeType.Message) {
      onClear();
      setIsLive(false);
    }
  }, [input]);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setVideoSrc("camera_active");
      }
    } catch (err) {
      alert("Camera access required for QR Forensics");
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
      videoRef.current.srcObject = null;
      setVideoSrc(null);
    }
  };

  const captureFrame = (): string | null => {
    if (!videoRef.current || !canvasRef.current) return null;
    const canvas = canvasRef.current;
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx?.drawImage(videoRef.current, 0, 0);
    return canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (activeType === IntakeType.QR || activeType === IntakeType.Media) {
      setLoading(true);
      onAnalysisStart();
      try {
        const reader = new FileReader();
        reader.onload = async () => {
          const base64 = (reader.result as string).split(',')[1];
          const visual = await analyzeVideoFrame(base64);
          const result: ScamAnalysis = {
            isScam: visual.isFraudulent,
            confidence: visual.anomalyScore / 100,
            scamType: activeType === IntakeType.QR ? "Visual QR Forensic" : "Media Artifact Analysis",
            channel: activeType === IntakeType.QR ? 'qr' : 'video',
            threatLevel: visual.isFraudulent ? 'High' : 'Low',
            summary: visual.forensicNotes,
            safetyAlert: visual.isFraudulent ? "⚠️ MALICIOUS OBJECT DETECTED. DO NOT AUTHORIZE PAYMENTS." : "Object appears legitimate.",
            extractedInfo: { 
              upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [], 
              links: visual.screenText.map(t => ({ value: t, confidence: 90 })), 
              cryptoWallets: [], fakeIdentities: [] 
            },
            fingerprint: { primaryHandle: visual.subjectIdentification || 'SECURE_OBJECT', primaryPhone: '', primaryLink: '', category: 'Visual Intel' },
            recommendedActions: visual.detectedThreats,
            suggestedBaitResponse: ""
          };
          onAnalysisComplete(`[FILE_FORENSIC: ${file.name}]`, result);
          setLoading(false);
        };
        reader.readAsDataURL(file);
      } catch (err) {
        console.error(err);
        setLoading(false);
      }
    }
  };

  const handleAnalyze = async () => {
    const requestId = ++currentRequestIdRef.current;
    setLoading(true);
    onAnalysisStart();
    try {
      let result: ScamAnalysis;
      let identifier = "";

      if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
        result = await analyzeMessage(input);
        identifier = input;
      } else if (activeType === IntakeType.QR) {
        const frame = captureFrame();
        if (!frame) throw new Error("No frame captured");
        const visual = await analyzeVideoFrame(frame);
        result = {
          isScam: visual.isFraudulent,
          confidence: visual.anomalyScore / 100,
          scamType: "QR Code Forensic",
          channel: 'qr',
