import React, { useState, useEffect, useRef } from 'react';
import { analyzeMessage, analyzeVideoFrame, analyzeUrlWithSearch } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAnalysisComplete: (message: string, analysis: ScamAnalysis) => void;
  onAnalysisStart: () => void;
  onClear: () => void;
}

enum IntakeType {
  Message = 'MESSAGE',
  Transcript = 'TRANSCRIPT',
  Media = 'MEDIA',
  QR = 'QR'
}

const ScamAnalyzer: React.FC<Props> = ({ onAnalysisComplete, onAnalysisStart, onClear }) => {
  const [activeType, setActiveType] = useState<IntakeType>(IntakeType.Message);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isLive, setIsLive] = useState(false);

  // Video/QR State
  const [videoSrc, setVideoSrc] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // URL State
  const [urlInput, setUrlInput] = useState('');
  const [urlError, setUrlError] = useState<string | null>(null);

  const debounceTimerRef = useRef<number | null>(null);
  const currentRequestIdRef = useRef<number>(0);

  const validateUrl = (url: string) => {
    try { new URL(url.includes('://') ? url : 'https://' + url); return true; } catch { return false; }
  };

  useEffect(() => {
    if (activeType === IntakeType.Message && input.trim().length > 10) {
      if (debounceTimerRef.current) window.clearTimeout(debounceTimerRef.current);
      setIsLive(true);
      debounceTimerRef.current = window.setTimeout(handleAnalyze, 800);
    } else if (input.trim().length === 0 && activeType === IntakeType.Message) {
      onClear();
      setIsLive(false);
    }
  }, [input]);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setVideoSrc("camera_active");
      }
    } catch (err) {
      alert("Camera access required for QR Forensics");
    }
  };

  const stopCamera = () => {
    if (videoRef.current && videoRef.current.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(t => t.stop());
      videoRef.current.srcObject = null;
      setVideoSrc(null);
    }
  };

  const captureFrame = (): string | null => {
    if (!videoRef.current || !canvasRef.current) return null;
    const canvas = canvasRef.current;
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx?.drawImage(videoRef.current, 0, 0);
    return canvas.toDataURL('image/jpeg', 0.8).split(',')[1];
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (activeType === IntakeType.QR || activeType === IntakeType.Media) {
      setLoading(true);
      onAnalysisStart();
      try {
        const reader = new FileReader();
        reader.onload = async () => {
          const base64 = (reader.result as string).split(',')[1];
          const visual = await analyzeVideoFrame(base64);
          const result: ScamAnalysis = {
            isScam: visual.isFraudulent,
            confidence: visual.anomalyScore / 100,
            scamType: activeType === IntakeType.QR ? "Visual QR Forensic" : "Media Artifact Analysis",
            channel: activeType === IntakeType.QR ? 'qr' : 'video',
            threatLevel: visual.isFraudulent ? 'High' : 'Low',
            summary: visual.forensicNotes,
            safetyAlert: visual.isFraudulent ? "⚠️ MALICIOUS OBJECT DETECTED. DO NOT AUTHORIZE PAYMENTS." : "Object appears legitimate.",
            // Fix: Add missing killChainStage property to satisfy interface requirements.
            killChainStage: 'Delivery',
            extractedInfo: { 
              upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [], 
              links: visual.screenText.map(t => ({ value: t, confidence: 90 })), 
              cryptoWallets: [], fakeIdentities: [] 
            },
            fingerprint: { primaryHandle: visual.subjectIdentification || 'SECURE_OBJECT', primaryPhone: '', primaryLink: '', category: 'Visual Intel' },
            recommendedActions: visual.detectedThreats,
            suggestedBaitResponse: ""
          };
          onAnalysisComplete(`[FILE_FORENSIC: ${file.name}]`, result);
          setLoading(false);
        };
        reader.readAsDataURL(file);
      } catch (err) {
        console.error(err);
        setLoading(false);
      }
    }
  };

  const handleAnalyze = async () => {
    const requestId = ++currentRequestIdRef.current;
    setLoading(true);
    onAnalysisStart();
    try {
      let result: ScamAnalysis;
      let identifier = "";

      if (activeType === IntakeType.Message || activeType === IntakeType.Transcript) {
        result = await analyzeMessage(input);
        identifier = input;
      } else if (activeType === IntakeType.QR) {
        const frame = captureFrame();
        if (!frame) throw new Error("No frame captured");
        const visual = await analyzeVideoFrame(frame);
        result = {
          isScam: visual.isFraudulent,
          confidence: visual.anomalyScore / 100,
          scamType: "QR Code Forensic",
          channel: 'qr',
          threatLevel: visual.isFraudulent ? 'High' : 'Low',
          summary: visual.forensicNotes,
          safetyAlert: visual.isFraudulent ? "⚠️ MALICIOUS QR DETECTED. DO NOT AUTHORIZE PAYMENTS OR CLICKS." : "QR Code appears legitimate.",
          // Fix: Add missing killChainStage property to satisfy interface requirements.
          killChainStage: 'Delivery',
          extractedInfo: { 
            upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [], 
            links: visual.screenText.map(t => ({ value: t, confidence: 90 })), 
            cryptoWallets: [], fakeIdentities: [] 
          },
          fingerprint: { primaryHandle: visual.subjectIdentification || 'QR_OBJECT', primaryPhone: '', primaryLink: '', category: 'Visual QR' },
          recommendedActions: visual.detectedThreats,
          suggestedBaitResponse: ""
        };
        identifier = "[QR_LIVE_CAPTURE]";
      } else {
        if (!urlInput) return;
        result = await analyzeUrlWithSearch(urlInput);
        identifier = urlInput;
      }

      if (requestId === currentRequestIdRef.current) {
        onAnalysisComplete(identifier, result);
      }
    } catch (error) {
      console.error(error);
    } finally {
      if (requestId === currentRequestIdRef.current) setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-3xl shadow-xl border border-slate-200 overflow-hidden relative">
      {isLive && (
        <div className="absolute top-4 right-4 flex items-center space-x-2 z-10 animate-in fade-in">
          <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse shadow-[0_0_8px_cyan]" />
          <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Live Auto-Scan</span>
        </div>
      )}

      <div className="flex border-b border-slate-100 bg-slate-50/50">
        <TabButton active={activeType === IntakeType.Message} onClick={() => { setActiveType(IntakeType.Message); stopCamera(); }} label="Text/Dialect" icon="💬" />
        <TabButton active={activeType === IntakeType.QR} onClick={() => { setActiveType(IntakeType.QR); startCamera(); }} label="QR Forensic" icon="📱" />
        <TabButton active={activeType === IntakeType.Media} onClick={() => { setActiveType(IntakeType.Media); stopCamera(); }} label="Web Reputation" icon="🌐" />
      </div>

      <div className="p-8 space-y-6">
        {activeType === IntakeType.Message ? (
          <textarea
            className="w-full h-44 p-6 bg-slate-50 border border-slate-200 rounded-2xl text-slate-700 focus:ring-2 focus:ring-blue-500 outline-none transition-all resize-none text-lg font-medium shadow-inner"
            placeholder="Paste suspicious text, Hinglish messages, or dialect phrasing here..."
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />
        ) : activeType === IntakeType.QR ? (
          <div className="space-y-4">
            <div className="relative aspect-video bg-black rounded-3xl overflow-hidden border-2 border-slate-800 shadow-2xl">
               <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover grayscale opacity-60" />
               <canvas ref={canvasRef} className="hidden" />
               <div className="absolute inset-0 border-[40px] border-black/40 pointer-events-none">
                  <div className="w-full h-full border-2 border-blue-500/30 relative">
                     <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-56 h-56 border-2 border-dashed border-white/10 rounded-3xl animate-pulse" />
                     </div>
                  </div>
               </div>
               <div className="absolute top-4 left-4 bg-black/60 px-3 py-1 rounded-full border border-white/10 flex items-center">
                  <div className="w-2 h-2 bg-red-600 rounded-full animate-pulse mr-2" />
                  <span className="text-[10px] font-black text-white uppercase tracking-widest">Sovereign QR Intercept</span>
               </div>
            </div>
            <div className="flex items-center space-x-4">
               <button onClick={handleAnalyze} className="flex-1 bg-blue-600 hover:bg-blue-700 text-white font-black uppercase text-xs tracking-widest py-4 rounded-2xl shadow-lg transition-all active:scale-95">
                  Capture & Analyze QR
               </button>
               <label className="flex-1 bg-white border border-slate-200 text-slate-600 font-black uppercase text-xs tracking-widest py-4 rounded-2xl shadow-sm text-center cursor-pointer hover:bg-slate-50 transition-all">
                  Upload QR Image
                  <input type="file" accept="image/*" className="hidden" onChange={handleFileUpload} />
               </label>
            </div>
          </div>
        ) : (
          <div className="space-y-4">
            <input 
              type="text" 
              placeholder="Enter URL (e.g. claim-your-prize.in) for deep reputation scan..." 
              value={urlInput}
              onChange={(e) => setUrlInput(e.target.value)}
              className="w-full p-6 bg-slate-50 border border-slate-200 rounded-2xl text-lg font-bold outline-none focus:ring-2 focus:ring-blue-500 shadow-inner"
            />
             <label className="block w-full bg-white border border-slate-200 text-slate-600 font-black uppercase text-xs tracking-widest py-4 rounded-2xl shadow-sm text-center cursor-pointer hover:bg-slate-50 transition-all">
                Upload Media Artifact (APK/Image/Video)
                <input type="file" className="hidden" onChange={handleFileUpload} />
             </label>
          </div>
        )}

        {activeType !== IntakeType.QR && (
          <button
            onClick={handleAnalyze}
            disabled={loading || (activeType === IntakeType.Message && input.length === 0)}
            className={`w-full py-5 rounded-2xl font-black text-xl shadow-xl transition-all flex items-center justify-center space-x-3 ${loading ? 'bg-slate-100 text-slate-400' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-600/30'}`}
          >
            {loading ? (
              <div className="w-6 h-6 border-3 border-slate-300 border-t-blue-600 rounded-full animate-spin"></div>
            ) : (
              <>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
                <span>Sovereign Forensic Scan</span>
              </>
            )}
          </button>
        )}
      </div>
    </div>
  );
};

const TabButton = ({ active, onClick, label, icon }: any) => (
  <button onClick={onClick} className={`flex-1 py-5 px-4 font-black text-[10px] uppercase tracking-widest border-b-4 transition-all ${active ? 'border-blue-600 text-blue-600 bg-white' : 'border-transparent text-slate-400 hover:text-slate-600 hover:bg-slate-50'}`}>
    <span className="mr-2 text-base">{icon}</span> {label}
  </button>
);

