import { GoogleGenAI, Type, Modality } from "@google/genai";
import { ScamAnalysis, VideoAnalysis } from "../types";
import { verifyHeader } from "../utils/headerVerifier";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SCAM_ANALYSIS_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    isScam: { type: Type.BOOLEAN },
    confidence: { type: Type.NUMBER },
    scamType: { type: Type.STRING },
    language: { type: Type.STRING },
    channel: { type: Type.STRING },
    threatLevel: { type: Type.STRING },
    summary: { type: Type.STRING },
    safetyAlert: { type: Type.STRING },
    killChainStage: { type: Type.STRING, enum: ['Reconnaissance', 'Delivery', 'Exploitation', 'Actions on Objective'] },
    extractedInfo: {
      type: Type.OBJECT,
      properties: {
        upiIds: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { value: { type: Type.STRING }, confidence: { type: Type.NUMBER } } } },
        bankDetails: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { value: { type: Type.STRING }, confidence: { type: Type.NUMBER } } } },
        ifscCodes: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { value: { type: Type.STRING }, confidence: { type: Type.NUMBER } } } },
        phoneNumbers: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { value: { type: Type.STRING }, confidence: { type: Type.NUMBER } } } },
        links: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { value: { type: Type.STRING }, confidence: { type: Type.NUMBER } } } },
        cryptoWallets: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { value: { type: Type.STRING }, confidence: { type: Type.NUMBER } } } },
        fakeIdentities: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { value: { type: Type.STRING }, confidence: { type: Type.NUMBER } } } }
      },
      required: ["upiIds", "bankDetails", "ifscCodes", "phoneNumbers", "links", "cryptoWallets", "fakeIdentities"]
    },
    sourceIntelligence: {
      type: Type.OBJECT,
      properties: {
        likelyOrigin: { type: Type.STRING },
        networkDetails: { type: Type.STRING },
        institutionInference: { type: Type.STRING },
        isCrossBorder: { type: Type.BOOLEAN },
        geographicMarkers: { type: Type.ARRAY, items: { type: Type.STRING } },
        clusterId: { type: Type.STRING },
        clusterConfidence: { type: Type.NUMBER },
        signalStrength: { type: Type.NUMBER },
        sourceCategory: { type: Type.STRING, enum: ['Telecom', 'Social', 'Web', 'App', 'Institutional'] }
      },
      required: ["likelyOrigin", "networkDetails", "institutionInference", "isCrossBorder", "geographicMarkers", "clusterId", "clusterConfidence", "signalStrength", "sourceCategory"]
    },
    fingerprint: {
      type: Type.OBJECT,
      properties: {
        primaryHandle: { type: Type.STRING },
        primaryPhone: { type: Type.STRING },
        primaryLink: { type: Type.STRING },
        category: { type: Type.STRING }
      },
      required: ["primaryHandle", "primaryPhone", "primaryLink", "category"]
    },
    recommendedActions: { type: Type.ARRAY, items: { type: Type.STRING } },
    suggestedBaitResponse: { type: Type.STRING }
  },
  required: ["isScam", "confidence", "scamType", "channel", "threatLevel", "summary", "safetyAlert", "killChainStage", "extractedInfo", "sourceIntelligence", "fingerprint", "recommendedActions", "suggestedBaitResponse"]
};

const MISSION_DIRECTIVE = `You are Bharat Cyber Rakshak AI — Sovereign Intelligence Protocol.

CORE CAPABILITIES:
1. Cyber Kill Chain Mapping: Identify if the scam is at Recon (finding victims), Delivery (SMS/Link), Exploitation (Getting OTP), or Action (Money transfer).
2. Regional Cluster Inference: Map to JAMTARA, NUH, or INTERNATIONAL hubs.
3. Multilingual Dialect Awareness: Detect regional nuances (Hinglish, Telugu-English).

TASKS:
- Perform deep forensic extraction.
- Map the threat to a Cyber Kill Chain stage.
- Evaluate origin signals and institutional spoofing.`;

export const analyzeMessage = async (message: string): Promise<ScamAnalysis> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Sovereign Forensic Analysis Request: "${message}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: SCAM_ANALYSIS_SCHEMA,
      systemInstruction: MISSION_DIRECTIVE
    },
  });

  const analysis: ScamAnalysis = JSON.parse(response.text);

  // Breach Sentry Integration (Google Search)
  if (analysis.extractedInfo.phoneNumbers.length > 0) {
    const phone = analysis.extractedInfo.phoneNumbers[0].value;
    try {
      const searchRes = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Search specifically for public data leaks, data breaches, or verified scam reports associated with the phone number: ${phone}. Check if it belongs to any leaked databases from major Indian telecom or fintech breaches.`,
        config: {
          tools: [{ googleSearch: {} }]
        }
      });

      const text = searchRes.text.toLowerCase();
      analysis.breachSentry = {
        isCompromised: text.includes('leak') || text.includes('breach') || text.includes('compromised') || text.includes('exposed'),
        leakedSources: searchRes.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((c: any) => c.web?.title).filter(Boolean).slice(0, 3) || [],
        riskFactor: analysis.threatLevel === 'Critical' ? 98 : 75
      };
    } catch (e) {
      console.error("Breach search failed", e);
    }
  }

  if (analysis.sourceIntelligence) {
    analysis.sourceIntelligence.headerStatus = verifyHeader(message.split(' ')[0]);
  }

  return analysis;
};

