const App: React.FC = () => {
  const [logs, setLogs] = useState<IntelligenceLog[]>([]);
  const [latestAnalysis, setLatestAnalysis] = useState<{message: string, analysis: ScamAnalysis, sessionId: string} | null>(null);
  const [view, setView] = useState<'analyzer' | 'history' | 'intelligence' | 'command'>('analyzer');
  const [liveMode, setLiveMode] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [activeAlert, setActiveAlert] = useState<{
    level: 'Low' | 'Medium' | 'High' | 'Critical';
    message: string;
    details: string;
    isEngaging?: boolean;
  } | null>(null);

  const currentSessionIdRef = useRef<string | null>(null);

  const generateCaseId = () => `BCR-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

  const findLinkedCases = (analysis: ScamAnalysis, currentLogs: IntelligenceLog[]): string[] => {
    const indicators = new Set([
      ...analysis.extractedInfo.upiIds.map(i => i.value.toLowerCase()),
      ...analysis.extractedInfo.phoneNumbers.map(i => i.value.toLowerCase()),
      ...analysis.extractedInfo.links.map(i => i.value.toLowerCase())
    ]);
    if (indicators.size === 0) return [];
    return currentLogs.filter(log => {
      const logIndicators = [
        ...log.extractedInfo.upiIds.map(i => i.value.toLowerCase()),
        ...log.extractedInfo.phoneNumbers.map(i => i.value.toLowerCase()),
        ...log.extractedInfo.links.map(i => i.value.toLowerCase())
      ];
      return logIndicators.some(li => indicators.has(li));
    }).map(log => log.id);
  };

  const createGovernanceDossier = (analysis: ScamAnalysis): GovernanceDossier => ({
    privacyScore: analysis.extractedInfo.upiIds.length > 0 ? 92 : 100,
    evidenceIntegrityHash: `SHA256:${Math.random().toString(36).substr(2, 10).toUpperCase()}`,
    ethicsChecklist: {
      noAssumedGuilt: true,
      dataExplicitlyProvided: true,
      biasMitigationApplied: true,
      humanReviewFlagged: analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical'
    },
    legalStanding: analysis.threatLevel === 'Critical' ? 'Verified Threat' : 'Probable Cause',
    auditLog: [{ action: 'AI_DETECTION_INITIATED', timestamp: Date.now(), actor: 'Rakshak_System' }]
  });

  const createOperationalRequests = (analysis: ScamAnalysis): OperationalRequest[] => {
    if (analysis.threatLevel !== 'High' && analysis.threatLevel !== 'Critical') return [];
    const reqs: OperationalRequest[] = [];
    const pushReq = (type: any, target: string) => reqs.push({ id: `REQ-${Math.random().toString(36).substr(2, 5)}`, type, target, evidenceHash: 'PENDING', priority: 'Urgent', status: 'Pending' });
    analysis.extractedInfo.upiIds.forEach(u => u.confidence > 70 && pushReq('BANK_FREEZE', u.value));
    analysis.extractedInfo.phoneNumbers.forEach(p => p.confidence > 70 && pushReq('TELECOM_BLOCK', p.value));
    analysis.extractedInfo.links.forEach(l => l.confidence > 70 && pushReq('URL_TAKEDOWN', l.value));
    return reqs;
  };

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis, isNewSession: boolean = false) => {
    setIsUpdating(false);
    if (isNewSession || !currentSessionIdRef.current) currentSessionIdRef.current = generateCaseId();
    const sessionId = currentSessionIdRef.current;

    const linkedIds = findLinkedCases(analysis, logs.filter(l => l.id !== sessionId));
    const linkedLogs = logs.filter(l => linkedIds.includes(l.id));
    const ringId = linkedLogs[0]?.ringId || (linkedIds.length > 0 ? `RING-${Math.floor(100 + Math.random() * 900)}` : undefined);

    // Cross-Platform Correlation Check
    const isMultiPlatform = linkedLogs.some(log => log.channel !== analysis.channel);

    setLogs(prev => {
      const existingIdx = prev.findIndex(l => l.id === sessionId);
      const newLog: IntelligenceLog = {
        ...analysis,
        id: sessionId,
        originalMessage: message,
        timestamp: Date.now(),
        status: 'Open',
        linkedCaseIds: linkedIds,
        ringId: ringId,
        multiPlatformPropagation: isMultiPlatform,
        estimatedImpact: analysis.potentialImpact ? analysis.potentialImpact * analysis.confidence : 0,
        operationalRequests: existingIdx >= 0 ? prev[existingIdx].operationalRequests : createOperationalRequests(analysis),
        governance: existingIdx >= 0 ? prev[existingIdx].governance : createGovernanceDossier(analysis),
        messages: analysis.isScam && (analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical')
          ? (existingIdx >= 0 ? prev[existingIdx].messages : [{ role: 'scammer', content: message, timestamp: Date.now() }])
          : []
      };
      if (existingIdx >= 0) {
        const updated = [...prev];
        updated[existingIdx] = newLog;
        return updated;
      }
      return [newLog, ...prev];
    });

    setLatestAnalysis({ message, analysis, sessionId });

    const isHighRisk = analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical';
    if (analysis.threatLevel === 'Low') {
      setActiveAlert({ level: 'Low', message: "Scanning complete. No fraud markers detected.", details: "Content logged for cross-reference." });
    } else if (isHighRisk) {
      setActiveAlert({
        level: analysis.threatLevel as 'High' | 'Critical',
        message: analysis.safetyAlert,
        details: isMultiPlatform ? `MULTI-PLATFORM THREAT DETECTED. Linked to Criminal Cluster (${ringId}).` : linkedIds.length > 0 ? `Linked to Criminal Cluster (${ringId}).` : "Priority containment dossier generated.",
        isEngaging: true
      });
    }
  };

  const runSimulation = () => {
    // Generate synthetic logs to test posture and scale
    const syntheticLogs: IntelligenceLog[] = Array.from({ length: 15 }).map((_, i) => ({
      isScam: true,
      confidence: 0.9,
      scamType: ['KYC Update', 'Digital Arrest', 'Electricity Cutoff'][i % 3],
      channel: ['call', 'text', 'qr'][i % 3] as any,
      threatLevel: 'High',
      summary: "Synthetic simulation log for readiness testing.",
      safetyAlert: "SIMULATED THREAT",
      killChainStage: 'Exploitation',
      extractedInfo: { upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [{ value: '+919876543210', confidence: 99 }], links: [], cryptoWallets: [], fakeIdentities: [] },
      fingerprint: { primaryHandle: 'SIM', primaryPhone: '', primaryLink: '', category: 'Simulation' },
      recommendedActions: [],
      suggestedBaitResponse: "",
      potentialImpact: 50000,
      id: `SIM-${Date.now()}-${i}`,
      originalMessage: "Simulated scam message.",
      timestamp: Date.now() - (i * 60000),
      status: 'Open',
      linkedCaseIds: [],
      operationalRequests: [],
      governance: createGovernanceDossier({} as any),
      messages: []
    }));
    setLogs(prev => [...syntheticLogs, ...prev]);
    setActiveAlert({ level: 'Medium', message: "Synthetic Resilience Test Initiated.", details: "Injecting 15 cross-platform threat vectors into the Defense Grid." });
  };

  const handleUpdateCaseStatus = (id: string, status: any) => {
    setLogs(prev => prev.map(l => l.id === id ? { ...l, status, governance: { ...l.governance, auditLog: [...l.governance.auditLog, { action: `STATUS_CHANGE_${status}`, timestamp: Date.now(), actor: 'Institutional_Actor' }] } } : l));
  };

  const handleSendRequest = (caseId: string, requestId: string) => {
    setLogs(prev => prev.map(l => l.id === caseId ? {
      ...l,
      operationalRequests: l.operationalRequests.map(r => r.id === requestId ? { ...r, status: 'Sent' } : r),
      governance: { ...l.governance, auditLog: [...l.governance.auditLog, { action: 'CONTAINMENT_REQUEST_SENT', timestamp: Date.now(), actor: 'Operational_Lead' }] }
    } : l));
  };

  const handleMessagesUpdate = (newMessages: ChatMessage[]) => {
    if (!latestAnalysis) return;
    setLogs(prev => prev.map(log => log.id === latestAnalysis.sessionId ? { ...log, messages: newMessages } : log));
  };

  const handleIntelUpdate = (info: ExtractedInfo) => {
    if (!latestAnalysis) return;
    setLogs(prev => prev.map(log => log.id === latestAnalysis.sessionId ? { ...log, extractedInfo: { ...log.extractedInfo, ...info } } : log));
