export const analyzeMessage = async (message: string): Promise<ScamAnalysis> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Sovereign Forensic Analysis Request: "${message}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: SCAM_ANALYSIS_SCHEMA,
      systemInstruction: MISSION_DIRECTIVE
    },
  });

  const analysis: ScamAnalysis = JSON.parse(response.text);

  if (analysis.extractedInfo.phoneNumbers.length > 0) {
    const phone = analysis.extractedInfo.phoneNumbers[0].value;
    try {
      const searchRes = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Search for verified scam reports or PII breaches associated with: ${phone}.`,
        config: {
          tools: [{ googleSearch: {} }]
        }
      });

      const text = searchRes.text.toLowerCase();
      analysis.breachSentry = {
        isCompromised: text.includes('leak') || text.includes('breach') || text.includes('exposed'),
        leakedSources: searchRes.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((c: any) => c.web?.title).filter(Boolean).slice(0, 3) || [],
        riskFactor: analysis.threatLevel === 'Critical' ? 98 : 75
      };
    } catch (e) {
      console.error("Breach search failed", e);
    }
  }

  if (analysis.sourceIntelligence) {
    analysis.sourceIntelligence.headerStatus = verifyHeader(message.split(' ')[0]);
  }

  return analysis;
};

