};

import React, { useState, useMemo } from 'react';
import { IntelligenceLog, AnalyticsSummary, ScamRing, EmergingWave, ThreatPosture } from '../types';

interface Props {
  logs: IntelligenceLog[];
}

const IntelligenceDashboard: React.FC<Props> = ({ logs }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'rings' | 'waves' | 'governance'>('overview');

  const analytics = useMemo((): AnalyticsSummary => {
    const totalPrevention = logs.reduce((sum, log) => sum + (log.estimatedImpact || 0), 0);
    const potentialExposure = logs.filter(l => l.status === 'Open').reduce((sum, log) => sum + (log.potentialImpact || 0), 0);

    // Threat Posture Logic
    const recentLogs = logs.filter(l => l.timestamp > Date.now() - 3600000); // last 1 hour
    let threatPosture: ThreatPosture = 'Green';
    if (recentLogs.length > 10 || logs.some(l => l.threatLevel === 'Critical' && l.timestamp > Date.now() - 1800000)) {
      threatPosture = 'Red';
    } else if (recentLogs.length > 5) {
      threatPosture = 'Yellow';
    }

    const idCounts: Record<string, { val: string, type: string, count: number }> = {};
    logs.forEach(log => {
      const allIds = [
        ...log.extractedInfo.upiIds.map(i => ({ v: i.value, t: 'UPI' })),
        ...log.extractedInfo.phoneNumbers.map(i => ({ v: i.value, t: 'TEL' })),
        ...log.extractedInfo.links.map(i => ({ v: i.value, t: 'URL' }))
      ];
      allIds.forEach(id => {
        const key = id.v.toLowerCase();
        if (!idCounts[key]) idCounts[key] = { val: id.v, type: id.t, count: 0 };
        idCounts[key].count++;
      });
    });

    const topIdentifiers = Object.values(idCounts)
      .sort((a, b) => b.count - a.count)
      .slice(0, 10)
      .map(item => ({ value: item.val, type: item.type, count: item.count }));

    const rings: Record<string, ScamRing> = {};
    logs.forEach(l => {
      if (l.ringId) {
        if (!rings[l.ringId]) {
          rings[l.ringId] = { id: l.ringId, name: `Ring Cluster ${l.ringId.split('-')[1]}`, centralIdentifiers: [], caseCount: 0, totalPreventedInr: 0, riskTrend: 'Stable', isInternational: false };
        }
        rings[l.ringId].caseCount++;
        rings[l.ringId].totalPreventedInr += (l.estimatedImpact || 0);
        if (l.isInternational) rings[l.ringId].isInternational = true;
      }
    });

    const waves: Record<string, EmergingWave> = {};
    logs.filter(l => l.timestamp > Date.now() - 86400000).forEach(l => {
      if (!waves[l.scamType]) waves[l.scamType] = { pattern: l.scamType, firstSeen: l.timestamp, count: 0, velocity: 0, riskLevel: (l.threatLevel === 'Low' ? 'Medium' : l.threatLevel) as any };
      waves[l.scamType].count++;
    });

    const baitingSessions = logs.filter(l => l.messages.length > 2);
    const successfulExtractions = baitingSessions.filter(l => (Object.values(l.extractedInfo) as any[]).some(arr => arr.length > 0)).length;

    const compliancePassCount = logs.filter(l => Object.values(l.governance.ethicsChecklist).every(v => v === true)).length;

    return {
      totalPreventionInr: totalPrevention,
      potentialExposureInr: potentialExposure,
      threatPosture,
      topIdentifiers,
      emergingWaves: Object.values(waves).sort((a,b) => b.count - a.count),
      scamRings: Object.values(rings),
      channelDistribution: logs.reduce((acc: any, l) => { acc[l.channel] = (acc[l.channel] || 0) + 1; return acc; }, {}),
      languageDistribution: logs.reduce((acc: any, l) => { if (l.language) acc[l.language] = (acc[l.language] || 0) + 1; return acc; }, {}),
      honeypotSuccessRate: baitingSessions.length ? (successfulExtractions / baitingSessions.length) * 100 : 0,
      governanceMetrics: {
        avgPrivacyScore: logs.length ? logs.reduce((a,b)=>a+b.governance.privacyScore,0)/logs.length : 100,
        reviewPendingCount: logs.filter(l => l.governance.legalStanding === 'Probable Cause').length,
        complianceRate: logs.length ? (compliancePassCount / logs.length) * 100 : 100
      }
    };
  }, [logs]);

  const postureColor = {
    'Green': 'text-green-600 bg-green-50',
    'Yellow': 'text-orange-600 bg-orange-50',
    'Red': 'text-red-600 bg-red-50 border-red-200 animate-pulse'
  }[analytics.threatPosture];

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className={`p-6 rounded-3xl border shadow-xl flex flex-col justify-center ${postureColor}`}>
           <div className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-60">National Threat Posture</div>
           <div className="text-3xl font-black tracking-tighter uppercase">{analytics.threatPosture} Alert</div>
           <div className="text-[8px] font-bold uppercase mt-1 opacity-50">DEFCON Scale Calibration</div>
        </div>
        <KPIBox title="Prevented Loss" value={`₹${(analytics.totalPreventionInr / 100000).toFixed(2)}L`} sub="Cumulative Savings" color="text-blue-600" />
        <KPIBox title="Risk Exposure" value={`₹${(analytics.potentialExposureInr / 100000).toFixed(2)}L`} sub="Potential Untethered Loss" color="text-red-600" />
        <KPIBox title="Honeypot Efficacy" value={`${analytics.honeypotSuccessRate.toFixed(1)}%`} sub="Extraction Success Rate" color="text-purple-600" />
      </div>

      <div className="flex space-x-2 bg-slate-100 p-1.5 rounded-2xl w-fit">
