        <TabNav active={activeTab === 'rings'} onClick={() => setActiveTab('rings')} label="Criminal Rings" />
        <TabNav active={activeTab === 'waves'} onClick={() => setActiveTab('waves')} label="Threat Waves" />
        <TabNav active={activeTab === 'governance'} onClick={() => setActiveTab('governance')} label="Compliance Audit" />
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
           <Section title="Multi-Platform Correlation" icon={<div className="w-2 h-2 bg-red-600 rounded-full mr-2 shadow-[0_0_8px_red]" />}>
