                       <div key={log.id} className="p-4 bg-red-50 border border-red-100 rounded-2xl flex items-center justify-between">
                          <div>
                             <div className="text-[9px] font-black text-red-600 uppercase">Multi-Platform Propagation Flag</div>
                             <div className="text-xs font-bold text-slate-800">{log.scamType}</div>
                          </div>
                          <span className="text-[8px] font-black bg-red-600 text-white px-2 py-0.5 rounded">DETECTED</span>
                       </div>
                    ))
                 ) : (
                    <div className="py-10 text-center text-slate-400 italic text-xs">No multi-channel propagation detected.</div>
                 )}
              </div>
           </Section>

           <Section title="Emerging Threat Velocity" icon={<div className="w-2 h-2 bg-blue-600 rounded-full mr-2" />}>
              <div className="space-y-4">
                 {analytics.emergingWaves.slice(0, 4).map((wave, i) => (
                    <div key={i} className="flex items-center justify-between p-4 bg-slate-50 border border-slate-100 rounded-2xl">
                       <div className="flex-1">
                          <h5 className="text-xs font-black text-slate-800 uppercase tracking-tight">{wave.pattern}</h5>
                          <div className="flex items-center space-x-2 mt-1">
