export default IntelligenceDashboard;

import React, { useState, useRef } from 'react';
import ScamAnalyzer from './components/ScamAnalyzer';
import IntelligenceDashboard from './components/IntelligenceDashboard';
import ResultPanel from './components/ResultPanel';
import LiveShield from './components/LiveShield';
import SafetyBanner from './components/SafetyBanner';
import BaitSession from './components/BaitSession';
import CaseHistory from './components/CaseHistory';
import CommandCenter from './components/CommandCenter';
import { ScamAnalysis, IntelligenceLog, ExtractedInfo, ChatMessage, OperationalRequest, GovernanceDossier } from './types';

const App: React.FC = () => {
  const [logs, setLogs] = useState<IntelligenceLog[]>([]);
  const [latestAnalysis, setLatestAnalysis] = useState<{message: string, analysis: ScamAnalysis, sessionId: string} | null>(null);
  const [view, setView] = useState<'analyzer' | 'history' | 'intelligence' | 'command'>('analyzer');
  const [liveMode, setLiveMode] = useState(false);
  const [isUpdating, setIsUpdating] = useState(false);
  const [activeAlert, setActiveAlert] = useState<{
    level: 'Low' | 'Medium' | 'High' | 'Critical';
    message: string;
    details: string;
    isEngaging?: boolean;
  } | null>(null);

  const currentSessionIdRef = useRef<string | null>(null);

  const generateCaseId = () => `BCR-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

  const findLinkedCases = (analysis: ScamAnalysis, currentLogs: IntelligenceLog[]): string[] => {
    const indicators = new Set([
      ...analysis.extractedInfo.upiIds.map(i => i.value.toLowerCase()),
      ...analysis.extractedInfo.phoneNumbers.map(i => i.value.toLowerCase()),
      ...analysis.extractedInfo.links.map(i => i.value.toLowerCase())
    ]);
    if (indicators.size === 0) return [];
    return currentLogs.filter(log => {
      const logIndicators = [
        ...log.extractedInfo.upiIds.map(i => i.value.toLowerCase()),
        ...log.extractedInfo.phoneNumbers.map(i => i.value.toLowerCase()),
        ...log.extractedInfo.links.map(i => i.value.toLowerCase())
      ];
      return logIndicators.some(li => indicators.has(li));
    }).map(log => log.id);
  };

  const createGovernanceDossier = (analysis: ScamAnalysis): GovernanceDossier => ({
    privacyScore: analysis.extractedInfo.upiIds.length > 0 ? 92 : 100,
    evidenceIntegrityHash: `SHA256:${Math.random().toString(36).substr(2, 10).toUpperCase()}`,
    ethicsChecklist: {
      noAssumedGuilt: true,
      dataExplicitlyProvided: true,
      biasMitigationApplied: true,
      humanReviewFlagged: analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical'
    },
    legalStanding: analysis.threatLevel === 'Critical' ? 'Verified Threat' : 'Probable Cause',
    auditLog: [{ action: 'AI_DETECTION_INITIATED', timestamp: Date.now(), actor: 'Rakshak_System' }]
  });

  const createOperationalRequests = (analysis: ScamAnalysis): OperationalRequest[] => {
    if (analysis.threatLevel !== 'High' && analysis.threatLevel !== 'Critical') return [];
    const reqs: OperationalRequest[] = [];
    const pushReq = (type: any, target: string) => reqs.push({ id: `REQ-${Math.random().toString(36).substr(2, 5)}`, type, target, evidenceHash: 'PENDING', priority: 'Urgent', status: 'Pending' });
    analysis.extractedInfo.upiIds.forEach(u => u.confidence > 70 && pushReq('BANK_FREEZE', u.value));
    analysis.extractedInfo.phoneNumbers.forEach(p => p.confidence > 70 && pushReq('TELECOM_BLOCK', p.value));
    analysis.extractedInfo.links.forEach(l => l.confidence > 70 && pushReq('URL_TAKEDOWN', l.value));
    return reqs;
  };

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis, isNewSession: boolean = false) => {
    setIsUpdating(false);
    if (isNewSession || !currentSessionIdRef.current) currentSessionIdRef.current = generateCaseId();
    const sessionId = currentSessionIdRef.current;

    const linkedIds = findLinkedCases(analysis, logs.filter(l => l.id !== sessionId));
    const linkedLogs = logs.filter(l => linkedIds.includes(l.id));
    const ringId = linkedLogs[0]?.ringId || (linkedIds.length > 0 ? `RING-${Math.floor(100 + Math.random() * 900)}` : undefined);

    // Cross-Platform Correlation Check
    const isMultiPlatform = linkedLogs.some(log => log.channel !== analysis.channel);

    setLogs(prev => {
      const existingIdx = prev.findIndex(l => l.id === sessionId);
      const newLog: IntelligenceLog = {
        ...analysis,
        id: sessionId,
        originalMessage: message,
        timestamp: Date.now(),
        status: 'Open',
        linkedCaseIds: linkedIds,
        ringId: ringId,
        multiPlatformPropagation: isMultiPlatform,
        estimatedImpact: analysis.potentialImpact ? analysis.potentialImpact * analysis.confidence : 0,
        operationalRequests: existingIdx >= 0 ? prev[existingIdx].operationalRequests : createOperationalRequests(analysis),
        governance: existingIdx >= 0 ? prev[existingIdx].governance : createGovernanceDossier(analysis),
        messages: analysis.isScam && (analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical')
          ? (existingIdx >= 0 ? prev[existingIdx].messages : [{ role: 'scammer', content: message, timestamp: Date.now() }])
          : []
      };
      if (existingIdx >= 0) {
        const updated = [...prev];
        updated[existingIdx] = newLog;
        return updated;
      }
      return [newLog, ...prev];
    });

    setLatestAnalysis({ message, analysis, sessionId });

    const isHighRisk = analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical';
    if (analysis.threatLevel === 'Low') {
      setActiveAlert({ level: 'Low', message: "Scanning complete. No fraud markers detected.", details: "Content logged for cross-reference." });
    } else if (isHighRisk) {
      setActiveAlert({
        level: analysis.threatLevel as 'High' | 'Critical',
        message: analysis.safetyAlert,
        details: isMultiPlatform ? `MULTI-PLATFORM THREAT DETECTED. Linked to Criminal Cluster (${ringId}).` : linkedIds.length > 0 ? `Linked to Criminal Cluster (${ringId}).` : "Priority containment dossier generated.",
        isEngaging: true
      });
    }
  };

  const runSimulation = () => {
    // Generate synthetic logs to test posture and scale
    const syntheticLogs: IntelligenceLog[] = Array.from({ length: 15 }).map((_, i) => ({
      isScam: true,
      confidence: 0.9,
      scamType: ['KYC Update', 'Digital Arrest', 'Electricity Cutoff'][i % 3],
      channel: ['call', 'text', 'qr'][i % 3] as any,
      threatLevel: 'High',
      summary: "Synthetic simulation log for readiness testing.",
      safetyAlert: "SIMULATED THREAT",
      killChainStage: 'Exploitation',
      extractedInfo: { upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [{ value: '+919876543210', confidence: 99 }], links: [], cryptoWallets: [], fakeIdentities: [] },
      fingerprint: { primaryHandle: 'SIM', primaryPhone: '', primaryLink: '', category: 'Simulation' },
      recommendedActions: [],
      suggestedBaitResponse: "",
      potentialImpact: 50000,
      id: `SIM-${Date.now()}-${i}`,
      originalMessage: "Simulated scam message.",
      timestamp: Date.now() - (i * 60000),
      status: 'Open',
      linkedCaseIds: [],
      operationalRequests: [],
      governance: createGovernanceDossier({} as any),
      messages: []
    }));
    setLogs(prev => [...syntheticLogs, ...prev]);
    setActiveAlert({ level: 'Medium', message: "Synthetic Resilience Test Initiated.", details: "Injecting 15 cross-platform threat vectors into the Defense Grid." });
  };

  const handleUpdateCaseStatus = (id: string, status: any) => {
    setLogs(prev => prev.map(l => l.id === id ? { ...l, status, governance: { ...l.governance, auditLog: [...l.governance.auditLog, { action: `STATUS_CHANGE_${status}`, timestamp: Date.now(), actor: 'Institutional_Actor' }] } } : l));
  };

  const handleSendRequest = (caseId: string, requestId: string) => {
    setLogs(prev => prev.map(l => l.id === caseId ? {
      ...l,
      operationalRequests: l.operationalRequests.map(r => r.id === requestId ? { ...r, status: 'Sent' } : r),
      governance: { ...l.governance, auditLog: [...l.governance.auditLog, { action: 'CONTAINMENT_REQUEST_SENT', timestamp: Date.now(), actor: 'Operational_Lead' }] }
    } : l));
  };

  const handleMessagesUpdate = (newMessages: ChatMessage[]) => {
    if (!latestAnalysis) return;
    setLogs(prev => prev.map(log => log.id === latestAnalysis.sessionId ? { ...log, messages: newMessages } : log));
  };

  const handleIntelUpdate = (info: ExtractedInfo) => {
    if (!latestAnalysis) return;
    setLogs(prev => prev.map(log => log.id === latestAnalysis.sessionId ? { ...log, extractedInfo: { ...log.extractedInfo, ...info } } : log));
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-slate-900 font-sans">
      <header className="bg-white border-b border-slate-200 px-6 py-4 flex items-center justify-between sticky top-0 z-[60] shadow-sm">
        <div className="flex items-center space-x-3">
          <div className="bg-blue-600 p-2 rounded-xl shadow-md cursor-pointer" onClick={() => setView('analyzer')}>
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
          </div>
          <div className="hidden sm:block">
            <h1 className="text-xl font-extrabold tracking-tight text-slate-800">Bharat Cyber <span className="text-blue-600">Rakshak</span></h1>
            <p className="text-[9px] text-slate-400 font-black uppercase tracking-[0.2em]">National Governance Protocol V7.0</p>
          </div>
        </div>

        <nav className="flex items-center space-x-1 bg-slate-100 p-1 rounded-2xl border border-slate-200">
           <NavBtn active={view === 'analyzer'} onClick={() => { setView('analyzer'); setLiveMode(false); }} label="Shield" />
           <NavBtn active={view === 'command'} onClick={() => { setView('command'); setLiveMode(false); }} label="War Room" />
           <NavBtn active={view === 'history'} onClick={() => { setView('history'); setLiveMode(false); }} label="Dossiers" />
           <NavBtn active={view === 'intelligence'} onClick={() => { setView('intelligence'); setLiveMode(false); }} label="Strategic" />
        </nav>

        <div className="flex items-center space-x-4">
          <button onClick={runSimulation} className="text-[9px] font-black text-blue-600 uppercase border border-blue-100 px-3 py-1.5 rounded-lg hover:bg-blue-50 transition-all">Run Stress Simulation</button>
          <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_green]"></div>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main className="flex-1 container mx-auto px-4 py-8 max-w-6xl space-y-8">
        {view === 'intelligence' ? (
          <IntelligenceDashboard logs={logs} />
        ) : view === 'command' ? (
          <CommandCenter logs={logs} />
        ) : view === 'history' ? (
          <CaseHistory logs={logs} onUpdateStatus={handleUpdateCaseStatus} onSendRequest={handleSendRequest} />
        ) : liveMode ? (
          <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_SHIELD_INTERCEPTION", analysis, true)} />
        ) : (
          <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in duration-500">
            <div className="text-center space-y-4">
              <h2 className="text-4xl font-black text-slate-800 tracking-tight leading-tight">National Cyber Intelligence Protocol</h2>
              <p className="text-slate-500 max-w-lg mx-auto text-lg font-medium">Evidence-based fraud defense with Sovereign-grade forensics. Mapping threats across the Cyber Kill Chain.</p>
              <button onClick={() => setLiveMode(true)} className="group relative inline-flex items-center justify-center px-8 py-4 font-black text-white bg-blue-600 rounded-2xl shadow-xl shadow-blue-600/30 hover:bg-blue-700 transition-all active:scale-95 overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-r from-blue-400/20 to-transparent animate-shimmer"></div>
                <svg className="w-6 h-6 mr-3 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                <span>Deploy Live Audio/Video Shield</span>
              </button>
            </div>

            <ScamAnalyzer onAnalysisComplete={handleAnalysisComplete} onAnalysisStart={() => setIsUpdating(true)} onClear={() => setLatestAnalysis(null)} />

            {latestAnalysis && (
              <div className="grid grid-cols-1 gap-8 animate-in slide-in-from-bottom-4 duration-500">
                <ResultPanel analysis={latestAnalysis.analysis} onClose={() => setLatestAnalysis(null)} />
                {(latestAnalysis.analysis.threatLevel === 'High' || latestAnalysis.analysis.threatLevel === 'Critical') && (
                  <div className="h-[500px]">
                    <BaitSession 
                      sessionId={latestAnalysis.sessionId}
                      initialMessages={logs.find(l => l.id === latestAnalysis.sessionId)?.messages || []}
                      onMessagesUpdate={handleMessagesUpdate}
                      onIntelExtracted={handleIntelUpdate}
                    />
                  </div>
                )}
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="py-10 px-6 border-t border-slate-200 mt-20 bg-white">
         <div className="container mx-auto max-w-6xl flex flex-col md:flex-row items-center justify-between text-[10px] font-black uppercase tracking-widest text-slate-400 space-y-4 md:space-y-0">
            <div className="flex items-center space-x-4">
               <span>&copy; 2026 National Cyber Rakshak AI Network</span>
               <span className="w-1 h-1 bg-slate-300 rounded-full"></span>
               <span>Protocol V7.0 Deploy-Sovereign</span>
            </div>
            <div className="flex items-center space-x-6">
               <span className="text-blue-500">Integrity: SHA-256 Verified</span>
               <span>Forensic Sovereignty Compliance</span>
            </div>
         </div>
      </footer>
    </div>
  );
};

const NavBtn = ({ active, onClick, label }: any) => (
  <button onClick={onClick} className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${active ? 'bg-white text-blue-600 shadow-sm border border-slate-200' : 'text-slate-500 hover:text-slate-800'}`}>
    {label}
  </button>
);

export default App;

export interface ExtractedItem<T> {
  value: T;
  confidence: number; // 0-100
}

export interface ExtractedInfo {
  upiIds: ExtractedItem<string>[];
  bankDetails: ExtractedItem<string>[];
  ifscCodes: ExtractedItem<string>[];
  phoneNumbers: ExtractedItem<string>[];
  links: ExtractedItem<string>[];
  cryptoWallets: ExtractedItem<string>[];
  fakeIdentities: ExtractedItem<string>[];
}

export type HeaderStatus = 'VERIFIED_INSTITUTION' | 'SPOOFED_HEADER' | 'UNKNOWN_SENDER' | 'NOT_APPLICABLE';
export type ThreatPosture = 'Green' | 'Yellow' | 'Red';

export interface BreachSentry {
  isCompromised: boolean;
  leakedSources: string[];
  riskFactor: number;
  lastBreachDate?: string;
}

export interface SourceIntelligence {
  likelyOrigin: string; 
  networkDetails: string; 
  institutionInference: string; 
  isCrossBorder: boolean;
  geographicMarkers: string[];
  clusterId?: string; 
  clusterConfidence?: number;
  signalStrength: number; 
  headerStatus: HeaderStatus;
  sourceCategory: 'Telecom' | 'Social' | 'Web' | 'App' | 'Institutional';
  coordinates?: { lat: number, lng: number }; // For map rendering
}

export type KillChainStage = 'Reconnaissance' | 'Delivery' | 'Exploitation' | 'Actions on Objective';

export interface ScamAnalysis {
  isScam: boolean;
  confidence: number; 
  scamType: string;
  language?: string;
  channel: 'text' | 'call' | 'video' | 'audio' | 'qr' | 'app' | 'social' | 'screen-share';
  threatLevel: 'Low' | 'Medium' | 'High' | 'Critical';
  summary: string;
  safetyAlert: string;
  extractedInfo: ExtractedInfo;
  sourceIntelligence?: SourceIntelligence;
  breachSentry?: BreachSentry;
  killChainStage: KillChainStage;
  fingerprint: {
    primaryHandle: string;
    primaryPhone: string;
    primaryLink: string;
    category: string;
  };
  recommendedActions: string[];
  suggestedBaitResponse: string;
  potentialImpact?: number; 
  multiPlatformPropagation?: boolean;
  aiReasoningTrace?: string; // High-level trace of the AI's logic
}

export interface ChatMessage {
  role: string;
  content: string;
  timestamp: number;
}

export interface OperationalRequest {
  id: string;
  type: 'BANK_FREEZE' | 'TELECOM_BLOCK' | 'URL_TAKEDOWN';
  target: string;
  evidenceHash: string;
  priority: 'Urgent' | 'Standard';
  status: 'Pending' | 'Sent' | 'Executed';
}

export interface GovernanceDossier {
  privacyScore: number;
  evidenceIntegrityHash: string;
  ethicsChecklist: {
    noAssumedGuilt: boolean;
    dataExplicitlyProvided: boolean;
    biasMitigationApplied: boolean;
    humanReviewFlagged: boolean;
  };
  legalStanding: string;
  auditLog: { action: string; timestamp: number; actor: string }[];
}

export interface IntelligenceLog extends ScamAnalysis {
  id: string;
  originalMessage: string;
  timestamp: number;
  messages: ChatMessage[]; 
  status: 'Open' | 'Investigating' | 'Blocked' | 'Resolved';
  linkedCaseIds: string[];
  ringId?: string;
  estimatedImpact?: number;
  isInternational?: boolean;
  operationalRequests: OperationalRequest[];
  governance: GovernanceDossier;
}

export interface AnalyticsSummary {
  totalPreventionInr: number;
  potentialExposureInr: number;
  threatPosture: ThreatPosture;
  topIdentifiers: { value: string; type: string; count: number }[];
  channelDistribution: Record<string, number>;
  emergingWaves: EmergingWave[];
  scamRings: ScamRing[];
  languageDistribution: Record<string, number>;
  honeypotSuccessRate: number;
  governanceMetrics: {
    avgPrivacyScore: number;
    reviewPendingCount: number;
    complianceRate: number;
  };
}

export interface ScamRing {
  id: string;
  name: string;
  centralIdentifiers: string[];
  caseCount: number;
  totalPreventedInr: number;
  riskTrend: 'Stable' | 'Rising' | 'Falling';
  isInternational: boolean;
}

export interface EmergingWave {
  pattern: string;
  firstSeen: number;
  count: number;
  velocity: number;
  riskLevel: 'Low' | 'Medium' | 'High' | 'Critical';
}

export interface VideoAnalysis {
  isFraudulent: boolean;
  anomalyScore: number;
  forensicNotes: string;
  faceDetected: string;
  logosSeen: string[];
  screenText: string[];
  subjectIdentification: string;
  detectedThreats: string[];
}

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { ScamAnalysis, VideoAnalysis } from "../types";
import { verifyHeader } from "../utils/headerVerifier";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const SCAM_ANALYSIS_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    isScam: { type: Type.BOOLEAN },
    confidence: { type: Type.NUMBER },
    scamType: { type: Type.STRING },
