        <TabNav active={activeTab === 'rings'} onClick={() => setActiveTab('rings')} label="Ring Intelligence" />
        <TabNav active={activeTab === 'waves'} onClick={() => setActiveTab('waves')} label="Wave Patterns" />
      </div>

      {activeTab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
           <div className="lg:col-span-2 bg-white rounded-3xl border border-slate-200 p-8 shadow-xl space-y-8">
              <div className="flex justify-between items-center">
