    if (analysis.threatLevel !== 'High' && analysis.threatLevel !== 'Critical' && !analysis.isScam) return [];
    const reqs: OperationalRequest[] = [];
    const pushReq = (type: any, target: string) => reqs.push({ id: `REQ-${Math.random().toString(36).substr(2, 5).toUpperCase()}`, type, target, evidenceHash: 'PENDING', priority: analysis.threatLevel === 'Critical' ? 'Urgent' : 'Standard', status: 'Pending' });

    analysis.extractedInfo.upiIds.forEach(u => u.confidence > 70 && pushReq('BANK_FREEZE', u.value));
    analysis.extractedInfo.phoneNumbers.forEach(p => p.confidence > 70 && pushReq('TELECOM_BLOCK', p.value));
    analysis.extractedInfo.links.forEach(l => l.confidence > 70 && pushReq('URL_TAKEDOWN', l.value));

    return reqs;
  };

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis, isNewSession: boolean = false) => {
    setIsUpdating(false);
    if (isNewSession || !currentSessionIdRef.current) currentSessionIdRef.current = generateCaseId();
    const sessionId = currentSessionIdRef.current;

    const indicators = new Set([
      ...analysis.extractedInfo.upiIds.map(i => i.value.toLowerCase()),
      ...analysis.extractedInfo.phoneNumbers.map(i => i.value.toLowerCase()),
      ...analysis.extractedInfo.links.map(i => i.value.toLowerCase())
    ]);

    const linkedLogs = logs.filter(log => {
      const logIndicators = [
        ...log.extractedInfo.upiIds.map(i => i.value.toLowerCase()),
        ...log.extractedInfo.phoneNumbers.map(i => i.value.toLowerCase()),
        ...log.extractedInfo.links.map(i => i.value.toLowerCase())
      ];
      return logIndicators.some(li => indicators.has(li));
    });

    const isMultiPlatform = linkedLogs.some(log => log.channel !== analysis.channel);
    const ringId = linkedLogs[0]?.ringId || (linkedLogs.length > 0 ? `RING-${Math.floor(100 + Math.random() * 900)}` : undefined);

    setLogs(prev => {
      const existingIdx = prev.findIndex(l => l.id === sessionId);
      const newLog: IntelligenceLog = {
        ...analysis,
        id: sessionId,
        originalMessage: message,
        timestamp: Date.now(),
        status: 'Open',
        linkedCaseIds: linkedLogs.map(l => l.id),
        ringId: ringId,
        multiPlatformPropagation: isMultiPlatform,
        estimatedImpact: analysis.potentialImpact ? analysis.potentialImpact * analysis.confidence : 0,
        operationalRequests: existingIdx >= 0 ? prev[existingIdx].operationalRequests : createOperationalRequests(analysis),
        governance: existingIdx >= 0 ? prev[existingIdx].governance : createGovernanceDossier(analysis),
        messages: analysis.isScam ? (existingIdx >= 0 ? prev[existingIdx].messages : [{ role: 'scammer', content: message, timestamp: Date.now() }]) : []
      };
      if (existingIdx >= 0) {
        const updated = [...prev];
        updated[existingIdx] = newLog;
        return updated;
      }
      return [newLog, ...prev];
    });

    setLatestAnalysis({ message, analysis, sessionId });

    const isHighRisk = analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical';
    if (isHighRisk) {
      setActiveAlert({
        level: analysis.threatLevel as 'High' | 'Critical',
        message: analysis.safetyAlert,
        details: isMultiPlatform ? `MULTI-PLATFORM THREAT. Linked to Criminal Ring (${ringId}).` : linkedLogs.length > 0 ? `Linked to Criminal Ring (${ringId}).` : "Priority containment dossier generated.",
        isEngaging: true
      });
    }
  };

  const updateBaitMessages = (sessionId: string, messages: ChatMessage[]) => {
    setLogs(prev => prev.map(l => l.id === sessionId ? { ...l, messages } : l));
  };

  const updateBaitIntel = (sessionId: string, info: ExtractedInfo) => {
    setLogs(prev => prev.map(l => {
      if (l.id === sessionId) {
        // Create new operational requests based on newly extracted intel
        const newAnalysis = { ...l, extractedInfo: info };
        const updatedRequests = [...l.operationalRequests];

        info.upiIds.forEach(u => {
          if (!updatedRequests.some(r => r.target === u.value)) {
            updatedRequests.push({ id: `REQ-AUTO-${Math.random().toString(36).substr(2, 4).toUpperCase()}`, type: 'BANK_FREEZE', target: u.value, evidenceHash: 'AUTO_EVIDENCE', priority: 'Standard', status: 'Pending' });
          }
        });

        return { ...l, extractedInfo: info, operationalRequests: updatedRequests };
      }
      return l;
    }));
  };

  const handleSendRequest = (caseId: string, requestId: string) => {
    setLogs(prev => prev.map(l => l.id === caseId ? {
      ...l,
      operationalRequests: l.operationalRequests.map(r => r.id === requestId ? { ...r, status: 'Sent' } : r),
      governance: { ...l.governance, auditLog: [...l.governance.auditLog, { action: 'CONTAINMENT_EXECUTED', timestamp: Date.now(), actor: 'Institutional_Gateway' }] }
    } : l));
  };

  const runSimulation = () => {
    const syntheticLogs: IntelligenceLog[] = Array.from({ length: 5 }).map((_, i) => ({
      isScam: true,
      confidence: 0.95,
      scamType: 'Simulated Fraud Wave',
      channel: 'text',
      threatLevel: 'High',
