      safetyAlert: "SIMULATED THREAT",
      killChainStage: 'Exploitation',
      extractedInfo: { upiIds: [], bankDetails: [], ifscCodes: [], phoneNumbers: [{ value: '+9100000000', confidence: 99 }], links: [], cryptoWallets: [], fakeIdentities: [] },
      fingerprint: { primaryHandle: 'SIM', primaryPhone: '', primaryLink: '', category: 'Simulation' },
      recommendedActions: [],
      suggestedBaitResponse: "",
      potentialImpact: 50000,
      id: `SIM-${Date.now()}-${i}`,
      originalMessage: "Synthetic simulation log.",
      timestamp: Date.now(),
      status: 'Open',
      linkedCaseIds: [],
      operationalRequests: [],
      governance: createGovernanceDossier({} as any),
      messages: [],
      aiReasoningTrace: "Simulation logic active.",
      sourceIntelligence: {
        likelyOrigin: "Internal Test",
        networkDetails: "Dev Grid",
        institutionInference: "N/A",
        isCrossBorder: false,
        geographicMarkers: ["Test Lab"],
        clusterId: "SIM-C1",
