        signalStrength: 100,
        sourceCategory: 'Institutional',
        headerStatus: 'NOT_APPLICABLE',
        coordinates: { lat: 28.6139, lng: 77.2090 } // Delhi coordinates
      }
    }));
    setLogs(prev => [...syntheticLogs, ...prev]);
  };

  const activeCase = logs.find(l => l.id === latestAnalysis?.sessionId);

  return (
