        </nav>

        <div className="flex items-center space-x-4">
          <button onClick={runSimulation} className="text-[9px] font-black text-blue-600 uppercase bg-blue-50 border border-blue-100 px-4 py-2 rounded-xl hover:bg-blue-100 transition-all">Test Readiness</button>
          <div className="flex items-center space-x-2">
