export const analyzeMessage = async (message: string): Promise<ScamAnalysis> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Forensic Analysis Request: "${message}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: SCAM_ANALYSIS_SCHEMA,
      systemInstruction: "You are the Sovereign Forensic Analyst. Detect scams and map to Cyber Kill Chain."
    },
  });
  const analysis: ScamAnalysis = JSON.parse(response.text);
  if (analysis.sourceIntelligence) {
    analysis.sourceIntelligence.headerStatus = verifyHeader(message.split(' ')[0]);
  }
  return analysis;
};

export const generateAgenticBait = async (history: { role: string, content: string }[]): Promise<{ response: string, reasoning: string, suspicionLevel: number }> => {
  const response = await ai.models.generateContent({
    model: "gemini-3-pro-preview",
    contents: `Mission History: ${JSON.stringify(history)}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          response: { type: Type.STRING, description: "The message to send to the scammer." },
          reasoning: { type: Type.STRING, description: "Your internal thought process for this turn." },
          suspicionLevel: { type: Type.NUMBER, description: "Your estimate of the scammer's suspicion (0-100)." }
        },
        required: ["response", "reasoning", "suspicionLevel"]
      },
      systemInstruction: AGENT_PERSONA_DIRECTIVE,
      thinkingConfig: { thinkingBudget: 2000 }
    }
  });
  return JSON.parse(response.text);
};

export const generateAudioFromText = async (text: string): Promise<string | undefined> => {
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
    },
  });
  return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
};

export function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

export async function decodeAudioData(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  return buffer;
}

