  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onMetricsUpdate?: (metrics: EngagementMetrics) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onMetricsUpdate }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [suspicion, setSuspicion] = useState(0);
  const [startTime] = useState(Date.now());
  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [initialMessages, isTyping]);

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    setIsTyping(true);
    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result = await generateAgenticBait(history);

      setSuspicion(result.suspicionLevel);

      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.response, 
        timestamp: Date.now(),
        reasoning: result.reasoning 
      }];

      onMessagesUpdate(updatedMessages);

      const metrics: EngagementMetrics = {
        turns: updatedMessages.length,
        durationSeconds: Math.floor((Date.now() - startTime) / 1000),
        suspicionLevel: result.suspicionLevel,
        extractionQuality: 85 // Heuristic
      };
      onMetricsUpdate?.(metrics);

    } catch (e) {
      console.error("Agent logic failed", e);
    } finally {
      setIsTyping(false);
    }
  };

  useEffect(() => {
    if (initialMessages.length === 1 && initialMessages[0].role === 'scammer') {
      const timer = setTimeout(() => runAgenticTurn(initialMessages), 1000);
      return () => clearTimeout(timer);
    }
  }, []);

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim()) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);

    // Analyze for new intel
    analyzeMessage(reply).then(analysis => {
      if (analysis.isScam) onIntelExtracted(analysis.extractedInfo);
    });

    setTimeout(() => runAgenticTurn(updatedMessages), 800);
  };

  return (
    <div className="bg-slate-900 rounded-[2rem] border border-slate-800 flex flex-col h-full overflow-hidden shadow-2xl relative">
      {/* Agent Header */}
      <div className="p-6 bg-black border-b border-white/5 flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <div className="relative">
            <div className={`w-3 h-3 rounded-full bg-blue-500 shadow-[0_0_10px_blue] ${isTyping ? 'animate-ping' : ''}`} />
          </div>
          <div>
            <h3 className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Autonomous Agent Terminal</h3>
            <p className="text-[8px] font-bold text-slate-500 uppercase">Case: {sessionId}</p>
          </div>
        </div>

        <div className="flex items-center space-x-6">
           <div className="text-right">
              <div className="text-[7px] font-black text-slate-500 uppercase mb-1">Scammer Suspicion</div>
              <div className="w-24 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                 <div className={`h-full transition-all duration-1000 ${suspicion > 70 ? 'bg-red-500' : 'bg-blue-500'}`} style={{ width: `${suspicion}%` }} />
              </div>
           </div>
           <div className="text-right">
              <div className="text-[7px] font-black text-slate-500 uppercase mb-1">Mission Clock</div>
              <div className="text-xs font-black text-blue-500 font-mono">
                 {Math.floor((Date.now() - startTime) / 1000)}s
              </div>
           </div>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Chat Stream */}
        <div className="flex-1 flex flex-col overflow-hidden border-r border-white/5">
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar">
            {initialMessages.map((m, idx) => (
              <div key={idx} className={`flex flex-col ${m.role === 'scammer' ? 'items-start' : 'items-end'}`}>
                {m.reasoning && (
                  <div className="mb-2 text-[8px] font-black text-blue-500 uppercase tracking-widest flex items-center bg-blue-500/10 px-2 py-1 rounded">
                     <span className="mr-2">Reasoning:</span>
                     <span className="text-slate-400 font-medium normal-case">{m.reasoning}</span>
                  </div>
                )}
                <div className={`max-w-[80%] rounded-2xl px-5 py-3 text-xs leading-relaxed transition-all duration-500 ${
                  m.role === 'scammer' 
                  ? 'bg-slate-800 text-slate-300 border border-white/5' 
                  : 'bg-blue-600 text-white shadow-xl shadow-blue-900/40'
                }`}>
                  {m.content}
                </div>
              </div>
            ))}
            {isTyping && (
               <div className="flex justify-end">
                  <div className="bg-blue-500/10 text-blue-400 px-4 py-2 rounded-2xl text-[9px] font-black uppercase tracking-widest animate-pulse border border-blue-500/20">
                     Synthesizing Agentic Response...
                  </div>
               </div>
            )}
          </div>

