        <TabButton active={activeType === IntakeType.QR} onClick={() => setActiveType(IntakeType.QR)} label="QR Forensics" icon="📱" />
        <TabButton active={activeType === IntakeType.URL} onClick={() => setActiveType(IntakeType.URL)} label="Web Reputation" icon="🌐" />
