import React, { useState, useEffect, useRef } from 'react';
import { generateAgenticBait, analyzeMessage } from '../services/geminiService';
import { ChatMessage, ExtractedInfo, EngagementMetrics } from '../types';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onMetricsUpdate?: (metrics: EngagementMetrics) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onMetricsUpdate }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [suspicion, setSuspicion] = useState(0);
  const [startTime] = useState(Date.now());
  const [activeStrategy, setActiveStrategy] = useState("Probing Scammer Intent");
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [initialMessages, isTyping]);

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    setIsTyping(true);
    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result = await generateAgenticBait(history);

      setSuspicion(result.suspicionLevel);
      if (result.strategyShift) setActiveStrategy(result.strategyShift);

      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.response, 
        timestamp: Date.now(),
        reasoning: result.reasoning,
        strategyShift: result.strategyShift
      }];

      onMessagesUpdate(updatedMessages);

      const metrics: EngagementMetrics = {
        turns: updatedMessages.length,
        durationSeconds: Math.floor((Date.now() - startTime) / 1000),
        suspicionLevel: result.suspicionLevel,
        extractionQuality: 92,
        intelExtractedCount: updatedMessages.filter(m => m.role === 'scammer' && m.content.includes('@')).length // Rough heuristic
      };
      onMetricsUpdate?.(metrics);

    } catch (e) {
      console.error("Agent logic failed", e);
    } finally {
      setIsTyping(false);
    }
  };

  useEffect(() => {
    if (initialMessages.length === 1 && initialMessages[0].role === 'scammer') {
      const timer = setTimeout(() => runAgenticTurn(initialMessages), 1000);
      return () => clearTimeout(timer);
    }
  }, []);

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim()) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);

    analyzeMessage(reply).then(analysis => {
      if (analysis.isScam) onIntelExtracted(analysis.extractedInfo);
    });

    setTimeout(() => runAgenticTurn(updatedMessages), 800);
  };

  return (
    <div className="bg-slate-900 rounded-[2.5rem] border border-slate-800 flex flex-col h-full overflow-hidden shadow-2xl relative">
      <div className="p-6 bg-black border-b border-white/5 flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <div className="relative">
            <div className={`w-3.5 h-3.5 rounded-full bg-blue-500 shadow-[0_0_15px_blue] ${isTyping ? 'animate-ping' : ''}`} />
          </div>
          <div>
            <h3 className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Autonomous Cyber Honey-Pot</h3>
            <p className="text-[8px] font-bold text-slate-500 uppercase tracking-widest">Active Tactic: <span className="text-blue-400">{activeStrategy}</span></p>
          </div>
        </div>

        <div className="flex items-center space-x-6">
           <div className="text-right">
              <div className="text-[7px] font-black text-slate-500 uppercase mb-1">Engage Duration</div>
              <div className="text-xs font-black text-blue-500 font-mono">
                 {Math.floor((Date.now() - startTime) / 1000)}s
              </div>
           </div>
           <div className="text-right">
              <div className="text-[7px] font-black text-slate-500 uppercase mb-1">Extraction Confidence</div>
              <div className="text-xs font-black text-green-500 font-mono">HIGH</div>
           </div>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        <div className="flex-1 flex flex-col overflow-hidden border-r border-white/5">
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-6 no-scrollbar bg-[radial-gradient(circle_at_50%_50%,_#1e293b_0%,_#0f172a_100%)]">
            {initialMessages.map((m, idx) => (
              <div key={idx} className={`flex flex-col ${m.role === 'scammer' ? 'items-start' : 'items-end'} animate-in fade-in slide-in-from-bottom-2`}>
                {m.reasoning && (
                  <div className="mb-2 text-[9px] font-mono text-blue-500/80 max-w-[70%] text-right bg-blue-500/5 px-3 py-2 rounded-xl border border-blue-500/10">
                     <span className="font-black text-blue-400">MEMORY_PULSE:</span> {m.reasoning}
                  </div>
                )}
                <div className={`max-w-[85%] rounded-[1.5rem] px-6 py-4 text-xs leading-relaxed font-medium transition-all shadow-xl ${
                  m.role === 'scammer' 
                  ? 'bg-slate-800 text-slate-200 border border-white/5 rounded-bl-none' 
                  : 'bg-blue-600 text-white border border-blue-400/20 rounded-br-none'
                }`}>
                  {m.content}
                </div>
              </div>
            ))}
            {isTyping && (
               <div className="flex justify-end">
                  <div className="bg-blue-600/10 text-blue-400 px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest animate-pulse border border-blue-500/20">
                     Agent Reasoning...
                  </div>
               </div>
            )}
          </div>

          <div className="p-8 bg-black/60 border-t border-white/5 backdrop-blur-md">
            <form onSubmit={(e) => {
              e.preventDefault();
              const target = e.target as any;
              handleManualScammerReply(target.reply.value);
              target.reply.value = '';
            }} className="flex space-x-4">
              <input 
                name="reply"
                type="text" 
                autoComplete="off"
                placeholder="Type response to evaluate Honey-Pot handoff..."
                className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-sm text-white outline-none focus:ring-2 focus:ring-blue-600 transition-all placeholder:text-slate-600"
              />
              <button type="submit" className="bg-blue-600 hover:bg-blue-500 text-white px-8 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all shadow-xl shadow-blue-600/20">
                Transmit
              </button>
            </form>
          </div>
        </div>

        <div className="w-80 bg-black/40 p-8 space-y-10 overflow-y-auto no-scrollbar border-l border-white/5">
           <div>
              <h4 className="text-[10px] font-black text-blue-500 uppercase tracking-[0.3em] mb-6">Extraction Progress</h4>
              <div className="grid grid-cols-2 gap-4">
                 <MetricBox label="Turns" value={initialMessages.length} />
                 <MetricBox label="Suspicion" value={`${suspicion}%`} />
              </div>
           </div>

           <div className="space-y-6">
              <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest border-b border-white/5 pb-2">Intelligence Vault</h4>
              <div className="space-y-3">
                 <ExtractionSlot label="UPI Handles" icon="💸" />
