           </div>

           <div className="p-6 bg-blue-600/10 rounded-3xl border border-blue-500/20">
              <div className="text-[9px] font-black text-blue-400 uppercase tracking-widest mb-2">Honey-Pot Health</div>
              <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden mb-2">
                 <div className="h-full bg-blue-500" style={{ width: '88%' }} />
              </div>
              <div className="text-[8px] font-bold text-slate-500 uppercase">Latency: 1.2s avg</div>
           </div>
        </div>
      </div>
    </div>
  );
};

