          </div>
          <div>
            <h1 className="text-xl font-black tracking-tight text-slate-800">Bharat Cyber <span className="text-blue-600">Rakshak</span></h1>
            <p className="text-[9px] text-slate-400 font-black uppercase tracking-[0.2em]">National Agentic Honey-Pot V7.0</p>
          </div>
        </div>

        <nav className="flex items-center space-x-1 bg-slate-100/50 p-1 rounded-2xl border border-slate-200 shadow-inner">
           <NavBtn active={view === 'analyzer'} onClick={() => { setView('analyzer'); setLiveMode(false); }} label="Shield" />
           <NavBtn active={view === 'command'} onClick={() => { setView('command'); setLiveMode(false); }} label="API Simulator" />
           <NavBtn active={view === 'history'} onClick={() => { setView('history'); setLiveMode(false); }} label="Dossiers" />
           <NavBtn active={view === 'intelligence'} onClick={() => { setView('intelligence'); setLiveMode(false); }} label="Strategic" />
        </nav>

        <div className="flex items-center space-x-4">
          <div className="flex flex-col items-end">
             <span className="text-[8px] font-black uppercase text-slate-400">System Integrity</span>
             <span className="text-[10px] font-black text-green-600 uppercase">Sovereign-Verified</span>
          </div>
          <div className="w-3 h-3 bg-green-500 rounded-full animate-pulse shadow-[0_0_10px_green]"></div>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main className="flex-1 container mx-auto px-6 py-12 max-w-7xl space-y-16">
        {view === 'intelligence' ? (
          <IntelligenceDashboard logs={logs} />
        ) : view === 'command' ? (
          <div className="space-y-12 animate-in fade-in duration-700">
             <div className="text-center space-y-2">
                <h2 className="text-4xl font-black text-slate-900 uppercase tracking-tight">API Evaluation Center</h2>
                <p className="text-slate-500 font-medium text-lg italic">Test JSON payload structures for competition compliance.</p>
             </div>
             <ApiExplorer />
          </div>
        ) : view === 'history' ? (
          <CaseHistory logs={logs} onUpdateStatus={() => {}} onSendRequest={() => {}} />
        ) : liveMode ? (
          <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_SHIELD_INTERCEPTION", analysis, true)} />
        ) : (
          <div className="max-w-6xl mx-auto space-y-16 animate-in fade-in duration-500">
            <div className="text-center space-y-4">
              <div className="inline-flex items-center px-5 py-2 rounded-full bg-blue-50 border border-blue-100 text-[11px] font-black text-blue-600 uppercase tracking-widest mb-4">
                Autonomous Fraud Interception Grid Active
              </div>
              <h2 className="text-6xl font-black text-slate-800 tracking-tighter leading-none uppercase">Agentic Cyber Hub</h2>
              <p className="text-slate-500 max-w-2xl mx-auto text-xl font-medium italic opacity-80 leading-relaxed">
                Autonomous Honey-Pot Hand-off. Believable Persona Synthesis. Deep Extraction Forensics.
              </p>
              <div className="flex justify-center pt-8">
                <button onClick={() => setLiveMode(true)} className="group relative inline-flex items-center justify-center px-12 py-6 font-black text-white bg-blue-600 rounded-[2.5rem] shadow-[0_20px_40px_rgba(37,99,235,0.3)] hover:bg-blue-700 transition-all hover:scale-105 active:scale-95 overflow-hidden">
                  <div className="absolute inset-0 bg-gradient-to-r from-blue-400/20 to-transparent animate-shimmer"></div>
                  <svg className="w-6 h-6 mr-3 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                  <span>Launch National Live Intercept Shield</span>
                </button>
              </div>
            </div>

            <ScamAnalyzer onAnalysisComplete={handleAnalysisComplete} onAnalysisStart={() => setIsUpdating(true)} onClear={() => setLatestAnalysis(null)} />

            {latestAnalysis && (
              <div className="grid grid-cols-1 gap-16 animate-in slide-in-from-bottom-12 duration-1000">
                <ResultPanel analysis={latestAnalysis.analysis} onClose={() => setLatestAnalysis(null)} />
                {latestAnalysis.analysis.isScam && (
                  <div className="h-[700px]">
                    <BaitSession 
                      sessionId={latestAnalysis.sessionId}
                      initialMessages={logs.find(l => l.id === latestAnalysis.sessionId)?.messages || []}
                      onMessagesUpdate={(msgs) => updateBaitMessages(latestAnalysis.sessionId, msgs)}
                      onIntelExtracted={(info) => updateBaitIntel(latestAnalysis.sessionId, info)}
                    />
                  </div>
                )}
                <ForensicLab analysis={latestAnalysis.analysis} />
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="py-16 px-12 border-t border-slate-200 mt-24 bg-white/80 backdrop-blur-md">
         <div className="container mx-auto max-w-7xl flex flex-col md:flex-row items-center justify-between text-[11px] font-black uppercase tracking-widest text-slate-400 space-y-8 md:space-y-0">
            <div className="flex items-center space-x-8">
               <div className="flex items-center space-x-2">
                 <div className="w-2 h-2 bg-blue-600 rounded-full"></div>
                 <span>© 2026 Bharat Cyber Rakshak AI</span>
               </div>
               <span className="opacity-30">|</span>
               <span>Institutional Protocol V7.0-ALPHA</span>
            </div>
            <div className="flex items-center space-x-10">
               <span className="text-blue-600 hover:text-blue-700 cursor-pointer transition-colors">Forensic Integrity: 100%</span>
               <span className="opacity-30">|</span>
               <span className="hover:text-slate-800 transition-colors cursor-pointer">MeitY Compliance Certified</span>
            </div>
         </div>
      </footer>
    </div>
  );
};

