import React, { useState, useEffect, useRef } from 'react';
import { generateAgenticBait, analyzeMessage } from '../services/geminiService';
import { ChatMessage, ExtractedInfo, EngagementMetrics, ExtractedItem } from '../types';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onMetricsUpdate?: (metrics: EngagementMetrics) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onMetricsUpdate }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [suspicion, setSuspicion] = useState(0);
  const [startTime] = useState(Date.now());
  const [activePersona, setActivePersona] = useState("Probing Identity...");
  const [activeStrategy, setActiveStrategy] = useState("Analyzing Initial Hook");
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [initialMessages, isTyping]);

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    setIsTyping(true);
    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result = await generateAgenticBait(history);

      setSuspicion(result.suspicionLevel);
      if (result.strategyShift) setActiveStrategy(result.strategyShift);

      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.response, 
        timestamp: Date.now(),
        reasoning: result.reasoning,
        strategyShift: result.strategyShift,
        persona: activePersona === "Probing Identity..." ? "Dynamic Mask" : activePersona
      }];

      onMessagesUpdate(updatedMessages);

      const metrics: EngagementMetrics = {
        turns: updatedMessages.length,
        durationSeconds: Math.floor((Date.now() - startTime) / 1000),
        suspicionLevel: result.suspicionLevel,
        extractionQuality: 98,
        intelExtractedCount: updatedMessages.filter(m => m.role === 'scammer' && m.content.includes('@')).length 
      };
      onMetricsUpdate?.(metrics);

    } catch (e) {
      console.error("Agent logic failed", e);
    } finally {
      setIsTyping(false);
    }
  };

  useEffect(() => {
    if (initialMessages.length === 1 && initialMessages[0].role === 'scammer') {
      const timer = setTimeout(() => runAgenticTurn(initialMessages), 1200);
      return () => clearTimeout(timer);
    }
  }, []);

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim()) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);

    analyzeMessage(reply).then(analysis => {
      if (analysis.isScam) onIntelExtracted(analysis.extractedInfo);
    });

    setTimeout(() => runAgenticTurn(updatedMessages), 1000);
  };

  // Extract counts for the HUD
  const scammerMsgs = initialMessages.filter(m => m.role === 'scammer');
  const botMsgs = initialMessages.filter(m => m.role === 'bot');

  return (
    <div className="bg-slate-950 rounded-[3rem] border border-slate-800 flex flex-col h-full overflow-hidden shadow-[0_30px_60px_-15px_rgba(0,0,0,0.5)] relative">
      {/* Tactical Header */}
      <div className="p-8 bg-black border-b border-white/5 flex items-center justify-between">
        <div className="flex items-center space-x-6">
          <div className="relative">
            <div className={`w-4 h-4 rounded-full bg-blue-500 shadow-[0_0_20px_blue] ${isTyping ? 'animate-ping' : ''}`} />
            <div className="absolute inset-0 bg-blue-500/20 rounded-full animate-pulse" />
          </div>
          <div>
            <h3 className="text-[11px] font-black text-white uppercase tracking-[0.3em] mb-1">Autonomous Agent: Bharat_Rakshak_v7</h3>
            <div className="flex items-center space-x-3">
              <span className="text-[9px] font-black text-blue-500 uppercase bg-blue-500/10 px-2 py-0.5 rounded">Tactic: {activeStrategy}</span>
              <span className="text-[9px] font-black text-slate-500 uppercase font-mono tracking-tighter">ID: {sessionId}</span>
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-8">
           <div className="text-right">
              <div className="text-[8px] font-black text-slate-600 uppercase mb-1 tracking-widest">Scammer Suspicion</div>
              <div className="w-32 h-1.5 bg-slate-900 rounded-full overflow-hidden border border-white/5">
                 <div className={`h-full transition-all duration-1000 ${suspicion > 70 ? 'bg-red-500 shadow-[0_0_10px_red]' : 'bg-blue-500 shadow-[0_0_10px_blue]'}`} style={{ width: `${suspicion}%` }} />
              </div>
           </div>
           <div className="h-10 w-px bg-white/5" />
           <div className="text-right">
              <div className="text-[8px] font-black text-slate-600 uppercase mb-1 tracking-widest">Mission Timer</div>
