                 {Math.floor((Date.now() - startTime) / 1000)}<span className="text-blue-500 text-xs">s</span>
              </div>
           </div>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Main Interaction Stream */}
        <div className="flex-1 flex flex-col overflow-hidden border-r border-white/5">
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-10 space-y-8 no-scrollbar bg-[radial-gradient(circle_at_50%_0%,_#1e293b_0%,_#020617_100%)]">
            {initialMessages.map((m, idx) => (
              <div key={idx} className={`flex flex-col ${m.role === 'scammer' ? 'items-start' : 'items-end'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
