import React, { useState, useEffect, useRef } from 'react';
import { generateAgenticBait, analyzeMessage } from '../services/geminiService';
import { ChatMessage, ExtractedInfo, EngagementMetrics } from '../types';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onMetricsUpdate?: (metrics: EngagementMetrics) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onMetricsUpdate }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [suspicion, setSuspicion] = useState(0);
  const [startTime] = useState(Date.now());
  const [activePersona, setActivePersona] = useState("Confused Retiree");
  const [activeStrategy, setActiveStrategy] = useState("Mirroring Scammer Urgency");
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [initialMessages, isTyping]);

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    setIsTyping(true);
    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result = await generateAgenticBait(history);

      setSuspicion(result.suspicionLevel);
      if (result.strategyShift) setActiveStrategy(result.strategyShift);

      // Heuristic: If suspicion is low and scammer is aggressive, use 'retiree', else 'professional'
      if (result.suspicionLevel > 50) setActivePersona("Defensive Professional");
      else setActivePersona("Eager Lottery Hopeful");

      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.response, 
        timestamp: Date.now(),
        reasoning: result.reasoning,
        strategyShift: result.strategyShift,
        persona: activePersona
      }];

      onMessagesUpdate(updatedMessages);

      onMetricsUpdate?.({
        turns: updatedMessages.length,
        durationSeconds: Math.floor((Date.now() - startTime) / 1000),
        suspicionLevel: result.suspicionLevel,
        extractionQuality: 98,
        intelExtractedCount: updatedMessages.filter(m => m.role === 'scammer' && m.content.includes('@')).length 
      });

    } catch (e) {
      console.error("Agent logic failed", e);
    } finally {
      setIsTyping(false);
    }
  };

  useEffect(() => {
    if (initialMessages.length === 1 && initialMessages[0].role === 'scammer') {
      const timer = setTimeout(() => runAgenticTurn(initialMessages), 1500);
      return () => clearTimeout(timer);
    }
  }, []);

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim()) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);

    analyzeMessage(reply).then(analysis => {
      if (analysis.isScam) onIntelExtracted(analysis.extractedInfo);
    });

    setTimeout(() => runAgenticTurn(updatedMessages), 800);
  };

  return (
    <div className="bg-[#020617] rounded-[3rem] border border-slate-800 flex flex-col h-full overflow-hidden shadow-[0_40px_80px_-20px_rgba(0,0,0,0.8)] relative font-sans">
      {/* Sovereign Terminal Header */}
      <div className="p-10 bg-black/40 border-b border-white/5 flex items-center justify-between backdrop-blur-xl">
        <div className="flex items-center space-x-8">
          <div className="relative group">
            <div className={`w-12 h-12 rounded-2xl bg-blue-600/20 border border-blue-500/30 flex items-center justify-center transition-all ${isTyping ? 'animate-pulse' : ''}`}>
               <div className={`w-3 h-3 rounded-full bg-blue-500 shadow-[0_0_20px_#3b82f6] ${isTyping ? 'animate-ping' : ''}`} />
            </div>
            <div className="absolute -inset-2 bg-blue-500/10 rounded-[2rem] blur opacity-0 group-hover:opacity-100 transition duration-500" />
          </div>
          <div>
            <h3 className="text-[12px] font-black text-white uppercase tracking-[0.4em] mb-1.5 flex items-center">
              Agentic Nexus Terminal
              <span className="ml-4 text-green-500 text-[8px] animate-pulse">● ENCRYPTED</span>
            </h3>
            <div className="flex items-center space-x-4">
              <div className="flex items-center space-x-2">
                 <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Active Disguise:</span>
                 <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest bg-blue-500/10 px-2 py-0.5 rounded">{activePersona}</span>
              </div>
              <div className="w-px h-3 bg-white/10" />
              <div className="flex items-center space-x-2">
                 <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Tactic:</span>
                 <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">{activeStrategy}</span>
              </div>
            </div>
          </div>
        </div>

        <div className="flex items-center space-x-10">
           <div className="text-right">
              <div className="text-[8px] font-black text-slate-600 uppercase mb-2 tracking-widest">Neural Load</div>
              <div className="w-32 h-1 bg-slate-800 rounded-full overflow-hidden border border-white/5">
                 <div className={`h-full bg-blue-600 transition-all duration-700 ${isTyping ? 'w-full' : 'w-20'}`} />
              </div>
           </div>
           <div className="text-right">
              <div className="text-[8px] font-black text-slate-600 uppercase mb-1 tracking-widest">Scammer Suspicion</div>
              <div className="flex items-center space-x-2">
                 <div className="text-sm font-black text-white font-mono">{suspicion}%</div>
                 <div className="w-20 h-2 bg-slate-900 rounded-full overflow-hidden border border-white/5">
                    <div className={`h-full transition-all duration-1000 ${suspicion > 70 ? 'bg-red-500 shadow-[0_0_10px_red]' : 'bg-blue-500 shadow-[0_0_10px_blue]'}`} style={{ width: `${suspicion}%` }} />
                 </div>
              </div>
           </div>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Interaction Stream */}
