import React, { useState, useEffect, useRef } from 'react';
import { generateAgenticBait, analyzeMessage } from '../services/geminiService';
import { ChatMessage, ExtractedInfo, EngagementMetrics } from '../types';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onMetricsUpdate?: (metrics: EngagementMetrics) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onMetricsUpdate }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [suspicion, setSuspicion] = useState(0);
  const [startTime] = useState(Date.now());
  const [activePersona, setActivePersona] = useState("Probing Identity");
  const [activeStrategy, setActiveStrategy] = useState("Establishing Rapport");
  const [thinkingProcess, setThinkingProcess] = useState<string[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [initialMessages, isTyping, thinkingProcess]);

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    setIsTyping(true);
    setThinkingProcess(["Analyzing conversation tone...", "Evaluating scammer suspicion metrics...", "Synthesizing persona response..."]);

    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result = await generateAgenticBait(history);

      setSuspicion(result.suspicionLevel);
      if (result.strategyShift) setActiveStrategy(result.strategyShift);

      // Dynamic Persona Selection
      const personas = ["Vulnerable Retiree", "Tech-Savvy Youth", "Frantic Professional", "Curious Investor"];
      setActivePersona(personas[Math.floor(Math.random() * personas.length)]);

      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.response, 
        timestamp: Date.now(),
        reasoning: result.reasoning,
        strategyShift: result.strategyShift,
        persona: activePersona
      }];

      onMessagesUpdate(updatedMessages);

      onMetricsUpdate?.({
        turns: updatedMessages.length,
        durationSeconds: Math.floor((Date.now() - startTime) / 1000),
        suspicionLevel: result.suspicionLevel,
        extractionQuality: 98,
        intelExtractedCount: updatedMessages.filter(m => m.role === 'scammer' && m.content.includes('@')).length 
      });

    } catch (e) {
      console.error("Agent logic failed", e);
    } finally {
      setIsTyping(false);
      setThinkingProcess([]);
    }
  };

  useEffect(() => {
    if (initialMessages.length === 1 && initialMessages[0].role === 'scammer') {
      const timer = setTimeout(() => runAgenticTurn(initialMessages), 1500);
      return () => clearTimeout(timer);
    }
  }, []);

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim()) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);

    analyzeMessage(reply).then(analysis => {
      if (analysis.isScam) onIntelExtracted(analysis.extractedInfo);
    });

    setTimeout(() => runAgenticTurn(updatedMessages), 1000);
  };

  return (
    <div className="bg-[#020617] rounded-[4rem] border border-slate-800 flex flex-col h-full overflow-hidden shadow-[0_60px_100px_-30px_rgba(0,0,0,0.9)] relative font-sans transition-all duration-700">
      {/* Sovereign Terminal Header */}
      <div className="p-12 bg-black/50 border-b border-white/5 flex items-center justify-between backdrop-blur-3xl">
        <div className="flex items-center space-x-10">
          <div className="relative">
            <div className={`w-16 h-16 rounded-[2rem] bg-blue-600/10 border border-blue-500/20 flex items-center justify-center ${isTyping ? 'animate-pulse' : ''}`}>
               <div className={`w-4 h-4 rounded-full bg-blue-500 shadow-[0_0_25px_#3b82f6] ${isTyping ? 'animate-ping' : ''}`} />
            </div>
          </div>
          <div className="space-y-2">
            <h3 className="text-[14px] font-black text-white uppercase tracking-[0.5em] flex items-center">
              Autonomous Honey-Pot v8.2
              <span className="ml-6 text-green-500 text-[10px] bg-green-500/10 px-3 py-1 rounded-full border border-green-500/20 tracking-widest">● LIVE_AGENT</span>
            </h3>
            <div className="flex items-center space-x-6 text-[10px] font-black uppercase tracking-widest text-slate-500">
               <span className="flex items-center"><span className="w-1.5 h-1.5 bg-blue-500 rounded-full mr-2" /> Persona: <span className="text-blue-400 ml-1.5">{activePersona}</span></span>
               <span className="w-px h-3 bg-white/10" />
               <span className="flex items-center"><span className="w-1.5 h-1.5 bg-indigo-500 rounded-full mr-2" /> Strategy: <span className="text-indigo-400 ml-1.5">{activeStrategy}</span></span>
